    [Fact]
    public void UnsupportedGradientPercentageCoordinatesRemainOpaque()
    {
        var rectangle = new A.FillToRectangle();
        foreach (var name in new[] { "l", "t", "r", "b" })
            rectangle.SetAttribute(new OpenXmlAttribute(name, string.Empty, "50%"));
        var gradient = new A.GradientFill(
            new A.GradientStopList(
                new A.GradientStop(new A.RgbColorModelHex { Val = "FFD966" }) { Position = 0 },
                new A.GradientStop(new A.RgbColorModelHex { Val = "FF9900" }) { Position = 100_000 }),
            new A.PathGradientFill(rectangle) { Path = A.PathShadeValues.Circle });

        Assert.False(PptxGradientFillCodec.TryRead(gradient, out var semantic));
        Assert.Empty(semantic.Stops);
    }


    [Fact]
    public void ImportedSlideBindingRequiresValidatedSourcePackageSnapshot()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.NotNull(Assert.Single(imported.Artifact.Presentation.Slides).Source);

        imported.Artifact.Source = null;
        imported.Artifact.OpaqueOpc.SourcePackage = new SourcePackageSnapshot();
        var rejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ExportPptx,
            Family = ArtifactFamily.Presentation,
            Artifact = imported.Artifact,
        });

        Assert.False(rejected.Ok);
        Assert.Equal("missing_source_package", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ProtocolRoundTripsMinimalPresentation()
    {
        var exported = Invoke(ExportRequest());
        Assert.True(exported.Ok, Diagnostics(exported));
        Assert.Equal("PK", System.Text.Encoding.ASCII.GetString(exported.File.Span[..2]));
        using (var stream = new MemoryStream(exported.File.ToByteArray()))
        using (var presentation = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(presentation));

        var imported = Import(exported.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.Equal(ArtifactFamily.Presentation, imported.Artifact.Family);
        Assert.Collection(imported.Artifact.Presentation.Slides,
            slide => Assert.Collection(slide.Elements,
                shape =>
                {
                    Assert.Equal("Quarterly brief", shape.Shape.Text);
                    Assert.True(shape.Source.Editable);
                    Assert.Equal("rect", shape.Shape.Geometry);
                }));
    }

    [Fact]
    public void ThinImportOmitsOnlyHashBoundSourcePayloadBytes()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = AddPicture(authored.File.ToByteArray());
        var thin = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ImportPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(sourceBytes),
            ThinPresentationImportResponse = true,
        });

        Assert.True(thin.Ok, Diagnostics(thin));
        Assert.Empty(thin.Artifact.OpaqueOpc.SourcePackage.Data);
        var asset = Assert.Single(thin.Artifact.Assets);
        Assert.NotEmpty(asset.Data);
        Assert.Equal(asset.Sha256, Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(asset.Data.Span)).ToLowerInvariant());

        var full = Import(sourceBytes);
        Assert.True(full.Ok, Diagnostics(full));
        Assert.NotEmpty(full.Artifact.OpaqueOpc.SourcePackage.Data);
        Assert.NotEmpty(Assert.Single(full.Artifact.Assets).Data);

        var invalid = ExportRequest();
        invalid.ThinPresentationImportResponse = true;
        var rejected = Invoke(invalid);
        Assert.False(rejected.Ok);
        Assert.Equal("invalid_request", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void EditPlanChangesOnlyOneBoundTextLeafWithoutReserializingTheSlide()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements);
        const string replacement = "Verified brief";
        var operation = new PresentationEditOperation
        {
            OperationId = "op-0001",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = element.Id,
            ShapeTreeIndex = element.Source.ShapeTreeIndex,
            ExpectedElementSha256 = element.Source.ElementSha256,
            ExpectedSemanticSha256 = element.Source.SemanticSha256,
            TextLeafIndex = 0,
            ExpectedValue = element.Shape.Text,
            Value = replacement,
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(element.Shape.Text))).ToLowerInvariant(),
        };
        var request = new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        };

        var edited = Invoke(request);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(["ppt/slides/slide1.xml"], edited.PresentationEditPlan.ChangedParts);
        var result = Assert.Single(edited.PresentationEditPlan.Operations);
        Assert.Equal(operation.OperationId, result.OperationId);
        Assert.NotEqual(result.SourceElementSha256, result.OutputElementSha256);
        Assert.Equal(operation.ExpectedElementSha256, result.SourceElementSha256);
        var sourceXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, operation.SlidePartPath));
        var outputBytes = edited.File.ToByteArray();
        var outputXml = Encoding.UTF8.GetString(ZipBytes(outputBytes, operation.SlidePartPath));
        Assert.Equal(sourceXml, outputXml.Replace(replacement, operation.ExpectedValue, StringComparison.Ordinal));
        Assert.DoesNotContain("xmlns:a14=", outputXml, StringComparison.Ordinal);
        Assert.Equal(sourceBytes, authored.File.ToByteArray());
        Assert.Equal(replacement, Assert.Single(Assert.Single(Import(outputBytes).Artifact.Presentation.Slides).Elements).Shape.Text);

        var stale = request.Clone();
        stale.PresentationEditPlan.Operations[0].ExpectedElementSha256 = new string('0', 64);
        var rejected = Invoke(stale);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_element_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);

        var staleSemantic = request.Clone();
        staleSemantic.PresentationEditPlan.Operations[0].ExpectedSemanticSha256 = new string('0', 64);
        var semanticRejected = Invoke(staleSemantic);
        Assert.False(semanticRejected.Ok);
        Assert.Equal("presentation_semantic_binding_mismatch", Assert.Single(semanticRejected.Diagnostics).Code);
    }

    [Fact]
    public void EditPlanChangesTextInsideASourceOwnedStyledShapeWithoutReserializingItsStyle()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = AddSourceOwnedShapeStyle(authored.File.ToByteArray());
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements);
        Assert.False(element.Source.Editable);
        Assert.True(element.Source.TextEditable);
        const string replacement = "Styled source proof";
        var operation = new PresentationEditOperation
        {
            OperationId = "op-styled-shape-text",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = element.Id,
            ShapeTreeIndex = element.Source.ShapeTreeIndex,
            ExpectedElementSha256 = element.Source.ElementSha256,
            ExpectedSemanticSha256 = element.Source.SemanticSha256,
            TextLeafIndex = 0,
            ExpectedValue = element.Shape.Text,
            Value = replacement,
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(element.Shape.Text))).ToLowerInvariant(),
        };
        operation.ShapeTreePath.Add(element.Source.ShapeTreeIndex);

        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(sourceBytes),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        });

        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([operation.SlidePartPath], edited.PresentationEditPlan.ChangedParts);
        var sourceXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, operation.SlidePartPath));
        var outputXml = Encoding.UTF8.GetString(ZipBytes(edited.File.ToByteArray(), operation.SlidePartPath));
        Assert.Contains("<p:style>", outputXml, StringComparison.Ordinal);
        Assert.Equal(sourceXml, outputXml.Replace(replacement, operation.ExpectedValue, StringComparison.Ordinal));
        var reopened = Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements);
        Assert.Equal(replacement, reopened.Shape.Text);
        Assert.False(reopened.Source.Editable);
        Assert.True(reopened.Source.TextEditable);
    }

    [Fact]
    public void EditPlanChangesAGroupChildTextLeafWithoutReserializingItsGroup()
    {
        var export = ExportRequest();
        var slideArtifact = Assert.Single(export.Artifact.Presentation.Slides);
        var child = Assert.Single(slideArtifact.Elements).Clone();
        child.Id = "presentation/slide/1/group/1/element/1";
        child.Name = "Nested brief";
        slideArtifact.Elements.Clear();
        var group = new PresentationElement
        {
            Id = "presentation/slide/1/group/1",
            Name = "Evidence group",
            Group = new PresentationGroup
            {
                LeftEmu = 200_000,
                TopEmu = 300_000,
                WidthEmu = 4_000_000,
                HeightEmu = 1_600_000,
                ChildLeftEmu = 0,
                ChildTopEmu = 0,
                ChildWidthEmu = 4_000_000,
                ChildHeightEmu = 1_600_000,
            },
        };
        group.Group.Children.Add(child);
        slideArtifact.Elements.Add(group);
        var authored = Invoke(export);
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedSlide = Assert.Single(imported.Artifact.Presentation.Slides);
        var importedGroup = Assert.Single(importedSlide.Elements);
        var importedChild = Assert.Single(importedGroup.Group.Children);
        const string replacement = "Verified nested brief";
        var operation = new PresentationEditOperation
        {
            OperationId = "op-group-child-0001",
            SlideId = importedSlide.Id,
            SlidePartPath = importedSlide.Source.PartPath,
            ExpectedSlideSha256 = importedSlide.Source.SlideXmlSha256,
            TargetId = importedChild.Id,
            ShapeTreeIndex = importedGroup.Source.ShapeTreeIndex,
            ExpectedElementSha256 = importedChild.Source.ElementSha256,
            ExpectedSemanticSha256 = importedChild.Source.SemanticSha256,
            TextLeafIndex = 0,
            ExpectedValue = importedChild.Shape.Text,
            Value = replacement,
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(importedChild.Shape.Text))).ToLowerInvariant(),
        };
        operation.ShapeTreePath.Add(importedGroup.Source.ShapeTreeIndex);
        operation.ShapeTreePath.Add(importedChild.Source.ShapeTreeIndex);
        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        });
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(operation.ShapeTreePath, Assert.Single(edited.PresentationEditPlan.Operations).ShapeTreePath);
        var sourceXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, operation.SlidePartPath));
        var outputXml = Encoding.UTF8.GetString(ZipBytes(edited.File.ToByteArray(), operation.SlidePartPath));
        Assert.Equal(sourceXml, outputXml.Replace(replacement, operation.ExpectedValue, StringComparison.Ordinal));
        var reopenedChild = Assert.Single(Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements).Group.Children);
        Assert.Equal(replacement, reopenedChild.Shape.Text);

        var fillOperation = operation.Clone();
        fillOperation.OperationId = "op-group-child-fill-0001";
        fillOperation.LeafKind = "fillRgb";
        fillOperation.ExpectedValue = importedChild.Shape.FillRgb;
        fillOperation.Value = "A1B2C3";
        fillOperation.ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(fillOperation.ExpectedValue))).ToLowerInvariant();
        var fillEdited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { fillOperation },
            },
        });
        Assert.True(fillEdited.Ok, Diagnostics(fillEdited));
        var fillSourceXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, fillOperation.SlidePartPath));
        var fillOutputXml = Encoding.UTF8.GetString(ZipBytes(fillEdited.File.ToByteArray(), fillOperation.SlidePartPath));
        Assert.Equal(fillSourceXml, fillOutputXml.Replace(fillOperation.Value, fillOperation.ExpectedValue, StringComparison.Ordinal));
        var reopenedFillChild = Assert.Single(Assert.Single(Assert.Single(Import(fillEdited.File.ToByteArray()).Artifact.Presentation.Slides).Elements).Group.Children);
        Assert.Equal(fillOperation.Value, reopenedFillChild.Shape.FillRgb);
    }

    [Fact]
    public void EditPlanChangesCodecProvenColorAndGeometryLeavesWithoutReserializingTheShape()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements);
        var cases = new (string Kind, string Expected, string Value)[]
        {
            ("fillRgb", element.Shape.FillRgb, "A1B2C3"),
            ("lineRgb", element.Shape.LineRgb, "C3B2A1"),
            ("leftEmu", element.Shape.LeftEmu.ToString(), "571501"),
            ("topEmu", element.Shape.TopEmu.ToString(), "381001"),
            ("widthEmu", element.Shape.WidthEmu.ToString(), "8191501"),
            ("heightEmu", element.Shape.HeightEmu.ToString(), "666751"),
        };
        foreach (var item in cases)
        {
            var operation = new PresentationEditOperation
            {
                OperationId = $"op-{item.Kind}",
                SlideId = slide.Id,
                SlidePartPath = slide.Source.PartPath,
                ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
                TargetId = element.Id,
                ShapeTreeIndex = element.Source.ShapeTreeIndex,
                LeafKind = item.Kind,
                ExpectedElementSha256 = element.Source.ElementSha256,
                ExpectedSemanticSha256 = element.Source.SemanticSha256,
                TextLeafIndex = 0,
                ExpectedValue = item.Expected,
                Value = item.Value,
                ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(item.Expected))).ToLowerInvariant(),
            };
            operation.ShapeTreePath.Add(element.Source.ShapeTreeIndex);
            var edited = Invoke(new CodecRequest
            {
                ProtocolVersion = CodecProtocol.ProtocolVersion,
                Operation = CodecOperation.ApplyPptxEditPlan,
                Family = ArtifactFamily.Presentation,
                File = authored.File,
                PresentationEditPlan = new PresentationEditPlanRequest
                {
                    ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                    Operations = { operation },
                },
            });
            Assert.True(edited.Ok, $"{item.Kind}: {Diagnostics(edited)}");
            var result = Assert.Single(edited.PresentationEditPlan.Operations);
            Assert.Equal(item.Kind, result.LeafKind);
            Assert.Equal(operation.ShapeTreePath, result.ShapeTreePath);
            var sourceXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, operation.SlidePartPath));
            var outputXml = Encoding.UTF8.GetString(ZipBytes(edited.File.ToByteArray(), operation.SlidePartPath));
            Assert.Equal(sourceXml, outputXml.Replace(item.Value, item.Expected, StringComparison.Ordinal));
            var reopened = Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements).Shape;
            Assert.Equal(item.Value, item.Kind switch
            {
                "fillRgb" => reopened.FillRgb,
                "lineRgb" => reopened.LineRgb,
                "leftEmu" => reopened.LeftEmu.ToString(),
                "topEmu" => reopened.TopEmu.ToString(),
                "widthEmu" => reopened.WidthEmu.ToString(),
                "heightEmu" => reopened.HeightEmu.ToString(),
                _ => throw new InvalidOperationException(),
            });
        }

        var lowerCaseSource = ReplaceZipText(sourceBytes, slide.Source.PartPath, xml =>
            xml.Replace("val=\"FFFFFF\"", "val=\"ffffff\"", StringComparison.Ordinal));
        var lowerCaseImported = Import(lowerCaseSource);
        Assert.True(lowerCaseImported.Ok, Diagnostics(lowerCaseImported));
        var lowerCaseSlide = Assert.Single(lowerCaseImported.Artifact.Presentation.Slides);
        var lowerCaseElement = Assert.Single(lowerCaseSlide.Elements);
        Assert.Equal("ffffff", lowerCaseElement.Shape.FillRgb);
        var lowerCaseOperation = new PresentationEditOperation
        {
            OperationId = "op-lowercase-fill",
            SlideId = lowerCaseSlide.Id,
            SlidePartPath = lowerCaseSlide.Source.PartPath,
            ExpectedSlideSha256 = lowerCaseSlide.Source.SlideXmlSha256,
            TargetId = lowerCaseElement.Id,
            ShapeTreeIndex = lowerCaseElement.Source.ShapeTreeIndex,
            LeafKind = "fillRgb",
            ExpectedElementSha256 = lowerCaseElement.Source.ElementSha256,
            ExpectedSemanticSha256 = lowerCaseElement.Source.SemanticSha256,
            ExpectedValue = "ffffff",
            Value = "AABBCC",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData("ffffff"u8.ToArray())).ToLowerInvariant(),
        };
        lowerCaseOperation.ShapeTreePath.Add(lowerCaseElement.Source.ShapeTreeIndex);
        var lowerCaseEdited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(lowerCaseSource),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = lowerCaseImported.Artifact.Source.PackageSha256,
                Operations = { lowerCaseOperation },
            },
        });
        Assert.True(lowerCaseEdited.Ok, Diagnostics(lowerCaseEdited));
        var lowerCaseSourceXml = Encoding.UTF8.GetString(ZipBytes(lowerCaseSource, lowerCaseOperation.SlidePartPath));
        var lowerCaseOutputXml = Encoding.UTF8.GetString(ZipBytes(lowerCaseEdited.File.ToByteArray(), lowerCaseOperation.SlidePartPath));
        Assert.Equal(lowerCaseSourceXml, lowerCaseOutputXml.Replace("AABBCC", "ffffff", StringComparison.Ordinal));

        var colorCaseNoOp = lowerCaseOperation.Clone();
        colorCaseNoOp.Value = "FFFFFF";
        var colorCaseRejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(lowerCaseSource),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = lowerCaseImported.Artifact.Source.PackageSha256,
                Operations = { colorCaseNoOp },
            },
        });
        Assert.False(colorCaseRejected.Ok);
        Assert.Equal("presentation_edit_plan_noop", Assert.Single(colorCaseRejected.Diagnostics).Code);

        var invalidWidth = lowerCaseOperation.Clone();
        invalidWidth.OperationId = "op-invalid-width";
        invalidWidth.LeafKind = "widthEmu";
        invalidWidth.ExpectedValue = lowerCaseElement.Shape.WidthEmu.ToString();
        invalidWidth.Value = "0";
        invalidWidth.ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(invalidWidth.ExpectedValue))).ToLowerInvariant();
        var invalidWidthRejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(lowerCaseSource),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = lowerCaseImported.Artifact.Source.PackageSha256,
                Operations = { invalidWidth },
            },
        });
        Assert.False(invalidWidthRejected.Ok);
        Assert.Equal("invalid_presentation_edit_operation", Assert.Single(invalidWidthRejected.Diagnostics).Code);
    }

    [Fact]
    public void EditPlanChangesMultipleGeometryLeavesWithFinalOutputOffsets()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements);

        PresentationEditOperation GeometryOperation(string id, string kind, string expected, string value)
        {
            var operation = new PresentationEditOperation
            {
                OperationId = id,
                SlideId = slide.Id,
                SlidePartPath = slide.Source.PartPath,
                ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
                TargetId = element.Id,
                ShapeTreeIndex = element.Source.ShapeTreeIndex,
                LeafKind = kind,
                ExpectedElementSha256 = element.Source.ElementSha256,
                ExpectedSemanticSha256 = element.Source.SemanticSha256,
                ExpectedValue = expected,
                Value = value,
                ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(expected))).ToLowerInvariant(),
            };
            operation.ShapeTreePath.Add(element.Source.ShapeTreeIndex);
            return operation;
        }

        var left = GeometryOperation("op-multi-left", "leftEmu", element.Shape.LeftEmu.ToString(), "5");
        var width = GeometryOperation("op-multi-width", "widthEmu", element.Shape.WidthEmu.ToString(), "123456789");
        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { left, width },
            },
        });

        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([slide.Source.PartPath], edited.PresentationEditPlan.ChangedParts);
        var sourcePart = ZipBytes(sourceBytes, slide.Source.PartPath);
        var outputPart = ZipBytes(edited.File.ToByteArray(), slide.Source.PartPath);
        var operationById = new[] { left, width }.ToDictionary(operation => operation.OperationId, StringComparer.Ordinal);
        var masks = new List<(int Start, int End, byte[] Source)>();
        foreach (var result in edited.PresentationEditPlan.Operations)
        {
            var operation = operationById[result.OperationId];
            var sourceStart = checked((int)result.SourceStartOffset);
            var sourceEnd = checked((int)result.SourceEndOffset);
            var outputEnd = checked((int)result.OutputEndOffset);
            var expected = Encoding.UTF8.GetBytes(operation.ExpectedValue);
            var replacement = Encoding.UTF8.GetBytes(operation.Value);
            var outputStart = outputEnd - replacement.Length;
            Assert.Equal(expected, sourcePart[sourceStart..sourceEnd]);
            Assert.Equal(replacement, outputPart[outputStart..outputEnd]);
            masks.Add((outputStart, outputEnd, expected));
        }
        var masked = outputPart;
        foreach (var mask in masks.OrderByDescending(mask => mask.Start))
            masked = [.. masked[..mask.Start], .. mask.Source, .. masked[mask.End..]];
        Assert.Equal(sourcePart, masked);

        var reopened = Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements).Shape;
        Assert.Equal(5L, reopened.LeftEmu);
        Assert.Equal(123456789L, reopened.WidthEmu);
    }

    [Fact]
