        var reopened = Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements,
            candidate => candidate.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.Equal(value, reopened.Table.Rows[1].Cells[1].Text);
    }

    [Fact]
    public void EditPlanRebasesSurvivingTargetsAfterEarlierElementDeletion()
    {
        var request = ExportRequest();
        var table = new PresentationTable
        {
            LeftEmu = 500_000,
            TopEmu = 1_300_000,
            WidthEmu = 4_000_000,
            HeightEmu = 600_000,
        };
        table.ColumnWidthsEmu.Add([4_000_000]);
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 600_000,
            Cells = { new PresentationTableCell { Text = "Pending" } },
        });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/table/rebase",
            Name = "Rebased table",
            Table = table,
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var removed = Assert.Single(slide.Elements, candidate => candidate.ContentCase == PresentationElement.ContentOneofCase.Shape);
        var surviving = Assert.Single(slide.Elements, candidate => candidate.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.True(removed.Source.DeletionCapability.Supported);
        var deletion = new PresentationEditOperation
        {
            OperationId = "op-delete-before-table",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = removed.Id,
            ShapeTreeIndex = removed.Source.ShapeTreeIndex,
            LeafKind = "deleteElement",
            ExpectedElementSha256 = removed.Source.ElementSha256,
            ExpectedSemanticSha256 = removed.Source.SemanticSha256,
            ExpectedValue = removed.Id,
            Value = string.Empty,
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(removed.Id))).ToLowerInvariant(),
            ElementDeletion = new PresentationEditElementDeletion { ExpectedNativeId = removed.Source.DeletionCapability.NativeId },
        };
        deletion.ShapeTreePath.Add(removed.Source.ShapeTreeIndex);
        var cellEdit = new PresentationEditOperation
        {
            OperationId = "op-edit-table-after-delete",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = surviving.Id,
            ShapeTreeIndex = surviving.Source.ShapeTreeIndex,
            LeafKind = "tableCellText",
            ExpectedElementSha256 = surviving.Source.ElementSha256,
            ExpectedSemanticSha256 = surviving.Source.SemanticSha256,
            ExpectedValue = "Pending",
            Value = "Approved",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes("Pending"))).ToLowerInvariant(),
        };
        cellEdit.ShapeTreePath.Add(surviving.Source.ShapeTreeIndex);
        var plan = new PresentationEditPlanRequest
        {
            ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
            Operations = { deletion, cellEdit },
        };

        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = plan,
        });

        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([slide.Source.PartPath], edited.PresentationEditPlan.ChangedParts);
        Assert.Equal(2, edited.PresentationEditPlan.Operations.Count);
        var reopenedSlide = Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides);
        var reopenedTable = Assert.Single(reopenedSlide.Elements);
        Assert.Equal(PresentationElement.ContentOneofCase.Table, reopenedTable.ContentCase);
        Assert.Equal("Approved", reopenedTable.Table.Rows[0].Cells[0].Text);

        var conflictingEdit = new PresentationEditOperation
        {
            OperationId = "op-edit-deleted-shape",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = removed.Id,
            ShapeTreeIndex = removed.Source.ShapeTreeIndex,
            LeafKind = "text",
            ExpectedElementSha256 = removed.Source.ElementSha256,
            ExpectedSemanticSha256 = removed.Source.SemanticSha256,
            ExpectedValue = removed.Shape.Text,
            Value = "Conflicting edit",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(removed.Shape.Text))).ToLowerInvariant(),
        };
        conflictingEdit.ShapeTreePath.Add(removed.Source.ShapeTreeIndex);
        var conflictingPlan = plan.Clone();
        conflictingPlan.Operations.Clear();
        conflictingPlan.Operations.Add(deletion);
        conflictingPlan.Operations.Add(conflictingEdit);
        var rejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationEditPlan = conflictingPlan,
        });
        Assert.False(rejected.Ok);
        Assert.Equal("invalid_presentation_edit_target", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void EditPlanChangesOneOpaqueChartTitleLeafWithoutReserializingTheChart()
    {
        var request = ExportRequest();
        var chart = new PresentationChart
        {
            LeftEmu = 4_000_000,
            TopEmu = 1_500_000,
            WidthEmu = 4_500_000,
            HeightEmu = 2_500_000,
            Type = SpreadsheetChartType.Bar,
            Title = "Native chart proof",
            HasLegend = true,
        };
        chart.Categories.Add(["A", "B"]);
        chart.Series.Add(new SpreadsheetChartSeriesArtifact { Name = "Evidence", Values = { 8, 13 } });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/chart/native-title",
            Name = "Native source chart",
            Chart = chart,
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        string chartPath;
        using (var stream = new MemoryStream(authored.File.ToByteArray(), writable: false))
        using (var package = PresentationDocument.Open(stream, false))
            chartPath = Assert.Single(package.PresentationPart!.SlideParts.Single().ChartParts).Uri.OriginalString.TrimStart('/');
        var sourceBytes = ReplaceZipText(authored.File.ToByteArray(), chartPath, xml =>
            Regex.Replace(
                xml,
                "<c:numLit>(?<body>.*?)</c:numLit>",
                "<c:numRef><c:f>Sheet1!$B$2:$B$3</c:f><c:numCache>${body}</c:numCache></c:numRef>",
                RegexOptions.Singleline,
                TimeSpan.FromSeconds(1)));
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements, candidate => candidate.Name == "Native source chart");
        Assert.Equal(PresentationElement.ContentOneofCase.Opaque, element.ContentCase);
        var binding = Assert.IsType<PresentationNativeChart>(element.Opaque.NativeChart);
        var leaf = Assert.Single(binding.TitleLeaves);
        Assert.Equal("Native chart proof", leaf.Text);
        Assert.Matches("^ppt/(?:[A-Za-z0-9_.-]+/)*[A-Za-z0-9_.-]+[.]xml$", binding.PartPath);
        Assert.Matches("^[0-9a-f]{64}$", binding.SourceSha256);
        Assert.NotEmpty(binding.RelationshipId);
        const string replacement = "Native chart verified";
        var operation = new PresentationEditOperation
        {
            OperationId = "chart-title-0001",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = element.Id,
            ShapeTreeIndex = element.Source.ShapeTreeIndex,
            ExpectedElementSha256 = element.Source.ElementSha256,
            ExpectedSemanticSha256 = element.Source.SemanticSha256,
            TextLeafIndex = leaf.TextLeafIndex,
            LeafKind = "chartTitleText",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(leaf.Text))).ToLowerInvariant(),
            ExpectedValue = leaf.Text,
            Value = replacement,
            TargetPartPath = binding.PartPath,
            ExpectedTargetPartSha256 = binding.SourceSha256,
            RelationshipId = binding.RelationshipId,
        };
        var editRequest = new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(sourceBytes),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        };

        var edited = Invoke(editRequest);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([binding.PartPath], edited.PresentationEditPlan.ChangedParts);
        var result = Assert.Single(edited.PresentationEditPlan.Operations);
        Assert.Equal(binding.PartPath, result.MutationPartPath);
        Assert.Equal(result.SourceElementSha256, result.OutputElementSha256);
        var sourceChartXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, binding.PartPath));
        var outputBytes = edited.File.ToByteArray();
        var outputChartXml = Encoding.UTF8.GetString(ZipBytes(outputBytes, binding.PartPath));
        Assert.Equal(sourceChartXml, outputChartXml.Replace(replacement, leaf.Text, StringComparison.Ordinal));
        foreach (var path in ZipPartPaths(sourceBytes).Where(path => !path.Equals(binding.PartPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(sourceBytes, path), ZipBytes(outputBytes, path));
        var reopened = Import(outputBytes);
        Assert.True(reopened.Ok, Diagnostics(reopened));
        var reopenedChart = Assert.Single(Assert.Single(reopened.Artifact.Presentation.Slides).Elements, candidate => candidate.Id == element.Id);
        Assert.Equal(replacement, Assert.Single(reopenedChart.Opaque.NativeChart.TitleLeaves).Text);

        var stale = editRequest.Clone();
        stale.PresentationEditPlan.Operations[0].ExpectedTargetPartSha256 = new string('0', 64);
        var rejected = Invoke(stale);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_chart_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void EditPlanChangesOneChartCacheAndItsEmbeddedWorkbookCellWithoutReserializingEitherPackage()
    {
        var request = ExportRequest();
        var chart = new PresentationChart
        {
            LeftEmu = 4_000_000,
            TopEmu = 1_500_000,
            WidthEmu = 4_500_000,
            HeightEmu = 2_500_000,
            Type = SpreadsheetChartType.Bar,
            Title = "Native chart data proof",
            HasLegend = true,
        };
        chart.Categories.Add(["A", "B"]);
        chart.Series.Add(new SpreadsheetChartSeriesArtifact { Name = "Evidence", Values = { 8, 13 } });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/chart/native-data",
            Name = "Native source chart data",
            Chart = chart,
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        string chartPath;
        using (var stream = new MemoryStream(authored.File.ToByteArray(), writable: false))
        using (var package = PresentationDocument.Open(stream, false))
            chartPath = Assert.Single(package.PresentationPart!.SlideParts.Single().ChartParts).Uri.OriginalString.TrimStart('/');
        const string workbookPath = "ppt/embeddings/native-chart-data.xlsx";
        var sourceBytes = AddEmbeddedChartDataWorkbook(authored.File.ToByteArray(), chartPath, workbookPath);
        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements, candidate => candidate.Name == "Native source chart data");
        var binding = Assert.IsType<PresentationNativeChart>(element.Opaque.NativeChart);
        Assert.Equal(workbookPath, binding.EmbeddedPackagePartPath);
        var point = Assert.Single(binding.DataPoints, candidate => candidate.SeriesIndex == 0 && candidate.PointIndex == 0);
        Assert.Equal("8", point.Value);
        Assert.Equal("Sheet1!$B$2:$B$3", point.Formula);
        Assert.Equal("B2", point.CellReference);
        const string replacement = "9";
        var operation = new PresentationEditOperation
        {
            OperationId = "chart-data-0001",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = element.Id,
            ShapeTreeIndex = element.Source.ShapeTreeIndex,
            ExpectedElementSha256 = element.Source.ElementSha256,
            ExpectedSemanticSha256 = element.Source.SemanticSha256,
            LeafKind = "chartDataValue",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(point.Value))).ToLowerInvariant(),
            ExpectedValue = point.Value,
            Value = replacement,
            TargetPartPath = binding.PartPath,
            ExpectedTargetPartSha256 = binding.SourceSha256,
            RelationshipId = binding.RelationshipId,
            EmbeddedPackagePartPath = binding.EmbeddedPackagePartPath,
            ExpectedEmbeddedPackageSha256 = binding.EmbeddedPackageSourceSha256,
            EmbeddedPackageRelationshipId = binding.EmbeddedPackageRelationshipId,
            EmbeddedWorksheetPartPath = point.WorksheetPartPath,
            ExpectedEmbeddedWorksheetSha256 = point.WorksheetSourceSha256,
            EmbeddedCellReference = point.CellReference,
            ChartSeriesIndex = point.SeriesIndex,
            ChartPointIndex = point.PointIndex,
            ChartFormula = point.Formula,
        };
        var editRequest = new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(sourceBytes),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        };

        var edited = Invoke(editRequest);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(new[] { binding.PartPath, binding.EmbeddedPackagePartPath }.OrderBy(value => value, StringComparer.Ordinal), edited.PresentationEditPlan.ChangedParts);
        var result = Assert.Single(edited.PresentationEditPlan.Operations);
        Assert.Equal(binding.PartPath, result.MutationPartPath);
        var nested = Assert.Single(result.NestedFootprints);
        Assert.Equal(binding.EmbeddedPackagePartPath, nested.ContainerPartPath);
        Assert.Equal(point.WorksheetPartPath, nested.PartPath);
        var outputBytes = edited.File.ToByteArray();
        var sourceChartXml = Encoding.UTF8.GetString(ZipBytes(sourceBytes, binding.PartPath));
        var outputChartXml = Encoding.UTF8.GetString(ZipBytes(outputBytes, binding.PartPath));
        Assert.Equal(sourceChartXml, outputChartXml.Replace("<c:v>9</c:v>", "<c:v>8</c:v>", StringComparison.Ordinal));
        foreach (var path in ZipPartPaths(sourceBytes).Where(path =>
                     !path.Equals(binding.PartPath, StringComparison.OrdinalIgnoreCase) &&
                     !path.Equals(binding.EmbeddedPackagePartPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(sourceBytes, path), ZipBytes(outputBytes, path));

        var sourceWorkbook = ZipBytes(sourceBytes, binding.EmbeddedPackagePartPath);
        var outputWorkbook = ZipBytes(outputBytes, binding.EmbeddedPackagePartPath);
        var sourceWorksheet = ZipBytes(sourceWorkbook, point.WorksheetPartPath);
        var outputWorksheet = ZipBytes(outputWorkbook, point.WorksheetPartPath);
        Assert.Equal("8", Encoding.UTF8.GetString(sourceWorksheet[(int)nested.SourceStartOffset..(int)nested.SourceEndOffset]));
        var outputStart = checked((int)nested.OutputEndOffset - Encoding.UTF8.GetByteCount(replacement));
        Assert.Equal(replacement, Encoding.UTF8.GetString(outputWorksheet[outputStart..(int)nested.OutputEndOffset]));
        var maskedWorksheet = outputWorksheet[..outputStart]
            .Concat(Encoding.UTF8.GetBytes(point.Value))
            .Concat(outputWorksheet[(int)nested.OutputEndOffset..])
            .ToArray();
        Assert.Equal(sourceWorksheet, maskedWorksheet);
        foreach (var path in ZipPartPaths(sourceWorkbook).Where(path => !path.Equals(point.WorksheetPartPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(sourceWorkbook, path), ZipBytes(outputWorkbook, path));
        var reopened = Import(outputBytes);
        Assert.True(reopened.Ok, Diagnostics(reopened));
        var reopenedChart = Assert.Single(Assert.Single(reopened.Artifact.Presentation.Slides).Elements, candidate => candidate.Id == element.Id);
        Assert.Equal(replacement, Assert.Single(reopenedChart.Opaque.NativeChart.DataPoints, candidate => candidate.SeriesIndex == 0 && candidate.PointIndex == 0).Value);

        var stale = editRequest.Clone();
        stale.PresentationEditPlan.Operations[0].ExpectedEmbeddedWorksheetSha256 = new string('0', 64);
        var rejected = Invoke(stale);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_leaf_precondition_failed", Assert.Single(rejected.Diagnostics).Code);

        var ambiguousSource = ReplaceZipText(sourceBytes, chartPath, xml =>
            new Regex(
                    "(<c:numRef><c:f>Sheet1!\\$B\\$2:\\$B\\$3</c:f><c:numCache>.*?)(<c:pt idx=\"0\"><c:v>8</c:v></c:pt>)",
                    RegexOptions.Singleline,
                    TimeSpan.FromSeconds(1))
                .Replace(xml, "$1$2$2", 1));
        Assert.False(sourceBytes.SequenceEqual(ambiguousSource));
        var ambiguousImport = Import(ambiguousSource);
        Assert.True(ambiguousImport.Ok, Diagnostics(ambiguousImport));
        var ambiguousChart = Assert.Single(
            Assert.Single(ambiguousImport.Artifact.Presentation.Slides).Elements,
            candidate => candidate.Name == "Native source chart data").Opaque.NativeChart;
        Assert.Empty(ambiguousChart.DataPoints);
        Assert.Empty(ambiguousChart.EmbeddedPackagePartPath);
    }

    [Fact]
    public void ShapeAccessibilityAuthorsImportsEditsAndKeepsIrregularMetadataSourceOwned()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Elements[0].Shape.Accessibility = new PresentationNonVisualAccessibility
        {
            Title = "Quarterly delivery decision",
            Description = "A single-slide release decision with the current owner and status.",
            Decorative = false,
        };

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var nonVisual = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Shape>().Single()
                .NonVisualShapeProperties!.NonVisualDrawingProperties!;
            Assert.Equal("Quarterly delivery decision", nonVisual.Title!.Value);
            Assert.Equal("A single-slide release decision with the current owner and status.", nonVisual.Description!.Value);
            Assert.False(Assert.Single(nonVisual.Descendants<AD.Decorative>()).Val!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedElement = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements);
        Assert.True(importedElement.Source.AccessibilityEditable);
        Assert.Equal("Quarterly delivery decision", importedElement.Shape.Accessibility.Title);
        Assert.Equal("A single-slide release decision with the current owner and status.", importedElement.Shape.Accessibility.Description);
        Assert.True(importedElement.Shape.Accessibility.HasDecorative);
        Assert.False(importedElement.Shape.Accessibility.Decorative);

        importedElement.Shape.Accessibility.ClearTitle();
        importedElement.Shape.Accessibility.ClearDescription();
        importedElement.Shape.Accessibility.Decorative = true;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripShape = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements).Shape;
        Assert.False(roundTripShape.Accessibility.HasTitle);
        Assert.False(roundTripShape.Accessibility.HasDescription);
        Assert.True(roundTripShape.Accessibility.HasDecorative);
        Assert.True(roundTripShape.Accessibility.Decorative);

        var invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Elements[0].Shape.Accessibility = new PresentationNonVisualAccessibility
        {
            Title = new string('a', 1_025),
        };
        Assert.Equal("invalid_presentation_shape", Assert.Single(Invoke(invalid).Diagnostics).Code);
        var empty = ExportRequest();
        empty.Artifact.Presentation.Slides[0].Elements[0].Shape.Accessibility = new PresentationNonVisualAccessibility();
        Assert.Equal("invalid_presentation_shape", Assert.Single(Invoke(empty).Diagnostics).Code);
        var contradictory = ExportRequest();
        contradictory.Artifact.Presentation.Slides[0].Elements[0].Shape.Accessibility = new PresentationNonVisualAccessibility
        {
            Title = "Meaningful",
            Decorative = true,
        };
        Assert.Equal("invalid_presentation_shape", Assert.Single(Invoke(contradictory).Diagnostics).Code);

        var irregularBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            xml.Replace("name=\"Title\"", "name=\"Title\" xmlns:fixture=\"urn:office-kit:shape-accessibility\" fixture:opaque=\"kept\"", StringComparison.Ordinal));
        var irregular = Import(irregularBytes);
        Assert.True(irregular.Ok, Diagnostics(irregular));
        var irregularElement = Assert.Single(Assert.Single(irregular.Artifact.Presentation.Slides).Elements);
        Assert.True(irregularElement.Source.Editable);
        Assert.False(irregularElement.Source.AccessibilityEditable);
        Assert.Null(irregularElement.Shape.Accessibility);

        irregularElement.Shape.Text = "Edited safely";
        irregularElement.Shape.TextBody.Paragraphs[0].Runs[0].Text = "Edited safely";
        var otherEdit = Export(irregular.Artifact);
        Assert.True(otherEdit.Ok, Diagnostics(otherEdit));
        using (var stream = new MemoryStream(otherEdit.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var nonVisual = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Shape>().Single()
                .NonVisualShapeProperties!.NonVisualDrawingProperties!;
            Assert.Equal("Quarterly delivery decision", nonVisual.Title!.Value);
            Assert.Equal("kept", Assert.Single(nonVisual.ExtendedAttributes).Value);
        }

        irregularElement.Shape.Accessibility = new PresentationNonVisualAccessibility { Title = "Must reject" };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(irregular.Artifact).Diagnostics).Code);

        var duplicateDecorativeBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            xml.Replace(
                "</a:extLst>",
                "<a:ext uri=\"{C183D7F6-B498-43B3-948B-1728B52AA6E4}\"><adec:decorative xmlns:adec=\"http://schemas.microsoft.com/office/drawing/2017/decorative\" val=\"0\"/></a:ext></a:extLst>",
                StringComparison.Ordinal));
        var duplicateDecorative = Import(duplicateDecorativeBytes);
        Assert.True(duplicateDecorative.Ok, Diagnostics(duplicateDecorative));
        var duplicateDecorativeShape = Assert.Single(Assert.Single(duplicateDecorative.Artifact.Presentation.Slides).Elements);
        Assert.True(duplicateDecorativeShape.Source.Editable);
        Assert.False(duplicateDecorativeShape.Source.AccessibilityEditable);
        Assert.Null(duplicateDecorativeShape.Shape.Accessibility);
        duplicateDecorativeShape.Shape.Accessibility = new PresentationNonVisualAccessibility { Decorative = true };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(duplicateDecorative.Artifact).Diagnostics).Code);
    }

    [Fact]
    public void GraphicFrameAccessibilityAuthorsImportsEditsAndKeepsIrregularMetadataSourceOwned()
    {
        var request = ExportRequest();
        var table = new PresentationTable
        {
            LeftEmu = 500_000,
            TopEmu = 1_300_000,
            WidthEmu = 3_000_000,
            HeightEmu = 1_000_000,
            Accessibility = new PresentationNonVisualAccessibility
            {
                Title = "Delivery gate table",
                Description = "Two-column table listing each release gate and its current state.",
                Decorative = false,
            },
        };
        table.ColumnWidthsEmu.Add([1_500_000, 1_500_000]);
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells = { new PresentationTableCell { Text = "Gate" }, new PresentationTableCell { Text = "State" } },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells = { new PresentationTableCell { Text = "QA" }, new PresentationTableCell { Text = "Pass" } },
        });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/table/accessibility",
            Name = "Accessible table",
            Table = table,
        });

        var chart = new PresentationChart
        {
            LeftEmu = 3_800_000,
            TopEmu = 1_300_000,
            WidthEmu = 3_000_000,
            HeightEmu = 1_700_000,
            Type = SpreadsheetChartType.Bar,
            Title = "Regional revenue",
            HasLegend = false,
            Accessibility = new PresentationNonVisualAccessibility
            {
                Title = "Regional revenue chart",
                Description = "Bar chart comparing North and South regional revenue.",
                Decorative = false,
            },
        };
        chart.Categories.Add(["North", "South"]);
        chart.Series.Add(new SpreadsheetChartSeriesArtifact { Name = "Revenue", Values = { 42, 37 } });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/chart/accessibility",
            Name = "Accessible chart",
            Chart = chart,
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var frames = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.GraphicFrame>().ToArray();
            var tableNonVisual = Assert.Single(frames, frame => frame.NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!.Name == "Accessible table")
                .NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!;
            var chartNonVisual = Assert.Single(frames, frame => frame.NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!.Name == "Accessible chart")
                .NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!;
            Assert.Equal("Delivery gate table", tableNonVisual.Title!.Value);
            Assert.Equal("Two-column table listing each release gate and its current state.", tableNonVisual.Description!.Value);
            Assert.False(Assert.Single(tableNonVisual.Descendants<AD.Decorative>()).Val!.Value);
            Assert.Equal("Regional revenue chart", chartNonVisual.Title!.Value);
            Assert.Equal("Bar chart comparing North and South regional revenue.", chartNonVisual.Description!.Value);
            Assert.False(Assert.Single(chartNonVisual.Descendants<AD.Decorative>()).Val!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedElements = Assert.Single(imported.Artifact.Presentation.Slides).Elements;
        var importedTable = Assert.Single(importedElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        var importedChart = Assert.Single(importedElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Chart);
        Assert.True(importedTable.Source.AccessibilityEditable);
        Assert.True(importedChart.Source.AccessibilityEditable);
        Assert.Equal("Delivery gate table", importedTable.Table.Accessibility.Title);
        Assert.Equal("Regional revenue chart", importedChart.Chart.Accessibility.Title);
        Assert.False(importedTable.Table.Accessibility.Decorative);
        Assert.False(importedChart.Chart.Accessibility.Decorative);

        importedTable.Table.Accessibility.Title = "Release gate table";
        importedTable.Table.Accessibility.ClearDescription();
        importedChart.Chart.Accessibility.ClearTitle();
        importedChart.Chart.Accessibility.ClearDescription();
        importedChart.Chart.Accessibility.Decorative = true;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripElements = Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements;
        var roundTripTable = Assert.Single(roundTripElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        var roundTripChart = Assert.Single(roundTripElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Chart);
        Assert.Equal("Release gate table", roundTripTable.Table.Accessibility.Title);
        Assert.False(roundTripTable.Table.Accessibility.HasDescription);
        Assert.False(roundTripChart.Chart.Accessibility.HasTitle);
        Assert.False(roundTripChart.Chart.Accessibility.HasDescription);
        Assert.True(roundTripChart.Chart.Accessibility.Decorative);

        var invalid = request.Clone();
        Assert.Single(invalid.Artifact.Presentation.Slides[0].Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table)
            .Table.Accessibility = new PresentationNonVisualAccessibility();
        Assert.Equal("invalid_presentation_table", Assert.Single(Invoke(invalid).Diagnostics).Code);

        var irregularBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml => xml
            .Replace("name=\"Accessible table\"", "name=\"Accessible table\" xmlns:fixture=\"urn:office-kit:graphic-frame-accessibility\" fixture:table=\"kept\"", StringComparison.Ordinal)
            .Replace("name=\"Accessible chart\"", "name=\"Accessible chart\" xmlns:fixture=\"urn:office-kit:graphic-frame-accessibility\" fixture:chart=\"kept\"", StringComparison.Ordinal));
        var irregular = Import(irregularBytes);
        Assert.True(irregular.Ok, Diagnostics(irregular));
        var irregularElements = Assert.Single(irregular.Artifact.Presentation.Slides).Elements;
        var irregularTable = Assert.Single(irregularElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        var irregularChart = Assert.Single(irregularElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Chart);
        Assert.True(irregularTable.Source.Editable);
        Assert.True(irregularChart.Source.Editable);
        Assert.False(irregularTable.Source.AccessibilityEditable);
        Assert.False(irregularChart.Source.AccessibilityEditable);
        Assert.Null(irregularTable.Table.Accessibility);
        Assert.Null(irregularChart.Chart.Accessibility);

        irregularTable.Table.Rows[1].Cells[1].Text = "Reviewed";
        irregularChart.Chart.Title = "Reviewed regional revenue";
        var otherEdit = Export(irregular.Artifact);
        Assert.True(otherEdit.Ok, Diagnostics(otherEdit));
        using (var stream = new MemoryStream(otherEdit.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var frames = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.GraphicFrame>().ToArray();
            var tableNonVisual = Assert.Single(frames, frame => frame.NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!.Name == "Accessible table")
                .NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!;
            var chartNonVisual = Assert.Single(frames, frame => frame.NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!.Name == "Accessible chart")
                .NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!;
            Assert.Equal("kept", Assert.Single(tableNonVisual.ExtendedAttributes).Value);
            Assert.Equal("kept", Assert.Single(chartNonVisual.ExtendedAttributes).Value);
            Assert.Equal("Delivery gate table", tableNonVisual.Title!.Value);
            Assert.Equal("Regional revenue chart", chartNonVisual.Title!.Value);
        }

        var tableBypass = Import(irregularBytes);
        Assert.Single(Assert.Single(tableBypass.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table)
            .Table.Accessibility = new PresentationNonVisualAccessibility { Title = "Must reject table" };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(tableBypass.Artifact).Diagnostics).Code);
        var chartBypass = Import(irregularBytes);
        Assert.Single(Assert.Single(chartBypass.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Chart)
            .Chart.Accessibility = new PresentationNonVisualAccessibility { Title = "Must reject chart" };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(chartBypass.Artifact).Diagnostics).Code);
    }

    [Fact]
