            Group = group,
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var nativeGroup = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.GroupShape>()
                .Single(item => item.NonVisualGroupShapeProperties!.NonVisualDrawingProperties!.Name == "Accessible approval group");
            var groupNonVisual = nativeGroup.NonVisualGroupShapeProperties!.NonVisualDrawingProperties!;
            var connectorNonVisual = Assert.Single(nativeGroup.Elements<P.ConnectionShape>())
                .NonVisualConnectionShapeProperties!.NonVisualDrawingProperties!;
            Assert.Equal("Approval flow", groupNonVisual.Title!.Value);
            Assert.Equal("Grouped visual showing the direction of the approval process.", groupNonVisual.Description!.Value);
            Assert.False(Assert.Single(groupNonVisual.Descendants<AD.Decorative>()).Val!.Value);
            Assert.Equal("Approval direction", connectorNonVisual.Title!.Value);
            Assert.Equal("Arrow from intake to final approval.", connectorNonVisual.Description!.Value);
            Assert.False(Assert.Single(connectorNonVisual.Descendants<AD.Decorative>()).Val!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedGroupElement = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group);
        var importedConnector = Assert.Single(importedGroupElement.Group.Children).Connector;
        Assert.True(importedGroupElement.Source.AccessibilityEditable);
        Assert.True(Assert.Single(importedGroupElement.Group.Children).Source.AccessibilityEditable);
        Assert.Equal("Approval flow", importedGroupElement.Group.Accessibility.Title);
        Assert.Equal("Approval direction", importedConnector.Accessibility.Title);
        Assert.False(importedGroupElement.Group.Accessibility.Decorative);
        Assert.False(importedConnector.Accessibility.Decorative);

        importedGroupElement.Group.Accessibility.ClearTitle();
        importedGroupElement.Group.Accessibility.ClearDescription();
        importedGroupElement.Group.Accessibility.Decorative = true;
        importedConnector.Accessibility.ClearTitle();
        importedConnector.Accessibility.Description = "Reviewed direction from intake to approval.";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripGroup = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group).Group;
        Assert.False(roundTripGroup.Accessibility.HasTitle);
        Assert.False(roundTripGroup.Accessibility.HasDescription);
        Assert.True(roundTripGroup.Accessibility.Decorative);
        Assert.False(Assert.Single(roundTripGroup.Children).Connector.Accessibility.HasTitle);
        Assert.Equal("Reviewed direction from intake to approval.", Assert.Single(roundTripGroup.Children).Connector.Accessibility.Description);
        Assert.False(Assert.Single(roundTripGroup.Children).Connector.Accessibility.Decorative);

        var invalidGroup = request.Clone();
        Assert.Single(Assert.Single(invalidGroup.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group).Group.Accessibility = new PresentationNonVisualAccessibility();
        Assert.Equal("invalid_presentation_group", Assert.Single(Invoke(invalidGroup).Diagnostics).Code);
        var invalidConnector = request.Clone();
        Assert.Single(Assert.Single(Assert.Single(invalidConnector.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group).Group.Children)
            .Connector.Accessibility = new PresentationNonVisualAccessibility();
        Assert.Equal("invalid_presentation_connector", Assert.Single(Invoke(invalidConnector).Diagnostics).Code);

        var irregularBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml => xml
            .Replace("name=\"Accessible approval group\"", "name=\"Accessible approval group\" xmlns:fixture=\"urn:office-kit:group-connector-accessibility\" fixture:group=\"kept\"", StringComparison.Ordinal)
            .Replace("name=\"Approval flow connector\"", "name=\"Approval flow connector\" xmlns:fixture=\"urn:office-kit:group-connector-accessibility\" fixture:connector=\"kept\"", StringComparison.Ordinal));
        var irregular = Import(irregularBytes);
        Assert.True(irregular.Ok, Diagnostics(irregular));
        var irregularGroupElement = Assert.Single(Assert.Single(irregular.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group);
        var irregularConnectorElement = Assert.Single(irregularGroupElement.Group.Children);
        Assert.True(irregularGroupElement.Source.Editable);
        Assert.True(irregularConnectorElement.Source.Editable);
        Assert.False(irregularGroupElement.Source.AccessibilityEditable);
        Assert.False(irregularConnectorElement.Source.AccessibilityEditable);
        Assert.Null(irregularGroupElement.Group.Accessibility);
        Assert.Null(irregularConnectorElement.Connector.Accessibility);

        irregularGroupElement.Group.LeftEmu += 20_000;
        irregularConnectorElement.Connector.LineWidthEmu += 9_525;
        var otherEdit = Export(irregular.Artifact);
        Assert.True(otherEdit.Ok, Diagnostics(otherEdit));
        using (var stream = new MemoryStream(otherEdit.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var nativeGroup = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.GroupShape>()
                .Single(item => item.NonVisualGroupShapeProperties!.NonVisualDrawingProperties!.Name == "Accessible approval group");
            var groupNonVisual = nativeGroup.NonVisualGroupShapeProperties!.NonVisualDrawingProperties!;
            var connectorNonVisual = Assert.Single(nativeGroup.Elements<P.ConnectionShape>())
                .NonVisualConnectionShapeProperties!.NonVisualDrawingProperties!;
            Assert.Equal("kept", Assert.Single(groupNonVisual.ExtendedAttributes).Value);
            Assert.Equal("kept", Assert.Single(connectorNonVisual.ExtendedAttributes).Value);
            Assert.Equal("Approval flow", groupNonVisual.Title!.Value);
            Assert.Equal("Approval direction", connectorNonVisual.Title!.Value);
        }

        var groupBypass = Import(irregularBytes);
        Assert.Single(Assert.Single(groupBypass.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group)
            .Group.Accessibility = new PresentationNonVisualAccessibility { Title = "Must reject group" };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(groupBypass.Artifact).Diagnostics).Code);
        var connectorBypass = Import(irregularBytes);
        Assert.Single(Assert.Single(Assert.Single(connectorBypass.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Group).Group.Children)
            .Connector.Accessibility = new PresentationNonVisualAccessibility { Title = "Must reject connector" };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(connectorBypass.Artifact).Diagnostics).Code);
    }

    [Fact]
    public void CustomShowsAuthorImportAndEditWithinFixedTopology()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides.Add(new PresentationSlide { Id = "presentation/slide/2", Name = "Evidence" });
        request.Artifact.Presentation.Slides.Add(new PresentationSlide { Id = "presentation/slide/3", Name = "Appendix" });
        var executive = new PresentationCustomShowArtifact
        {
            Id = "custom-show/executive",
            Name = "Executive route",
            NativeId = 7,
        };
        executive.SlideIds.Add("presentation/slide/1");
        executive.SlideIds.Add("presentation/slide/3");
        var review = new PresentationCustomShowArtifact
        {
            Id = "custom-show/review",
            Name = "Review route",
            NativeId = 11,
        };
        review.SlideIds.Add("presentation/slide/2");
        request.Artifact.Presentation.CustomShows.Add(executive);
        request.Artifact.Presentation.CustomShows.Add(review);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var shows = package.PresentationPart!.Presentation!.CustomShowList!.Elements<P.CustomShow>().ToArray();
            Assert.Equal(2, shows.Length);
            Assert.Equal(("Executive route", 7U), (shows[0].Name!.Value, shows[0].Id!.Value));
            Assert.Equal(new[] { "rIdSlide1", "rIdSlide3" }, shows[0].SlideList!.Elements<P.SlideListEntry>().Select(entry => entry.Id!.Value));
            Assert.Equal(("Review route", 11U), (shows[1].Name!.Value, shows[1].Id!.Value));
            Assert.Equal(new[] { "rIdSlide2" }, shows[1].SlideList!.Elements<P.SlideListEntry>().Select(entry => entry.Id!.Value));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.False(imported.Artifact.Presentation.CustomShowsOpaque);
        Assert.Collection(imported.Artifact.Presentation.CustomShows,
            show =>
            {
                Assert.Equal("Executive route", show.Name);
                Assert.Equal(7U, show.NativeId);
                Assert.Equal(new[] { "presentation/slide/1", "presentation/slide/3" }, show.SlideIds);
                Assert.True(show.Source!.Editable);
            },
            show =>
            {
                Assert.Equal("Review route", show.Name);
                Assert.Equal(11U, show.NativeId);
                Assert.Equal(new[] { "presentation/slide/2" }, show.SlideIds);
                Assert.True(show.Source!.Editable);
            });

        imported.Artifact.Presentation.CustomShows[0].Name = "Board route";
        imported.Artifact.Presentation.CustomShows[0].SlideIds.Clear();
        imported.Artifact.Presentation.CustomShows[0].SlideIds.Add("presentation/slide/3");
        imported.Artifact.Presentation.CustomShows[0].SlideIds.Add("presentation/slide/1");
        imported.Artifact.Presentation.CustomShows[0].SlideIds.Add("presentation/slide/3");
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        Assert.Collection(roundTrip.Artifact.Presentation.CustomShows,
            show =>
            {
                Assert.Equal("Board route", show.Name);
                Assert.Equal(7U, show.NativeId);
                Assert.Equal(new[] { "presentation/slide/3", "presentation/slide/1", "presentation/slide/3" }, show.SlideIds);
            },
            show => Assert.Equal("Review route", show.Name));

        var added = Import(authored.File.ToByteArray()).Artifact;
        var extra = new PresentationCustomShowArtifact { Id = "custom-show/extra", Name = "Extra", NativeId = 12 };
        extra.SlideIds.Add("presentation/slide/1");
        added.Presentation.CustomShows.Add(extra);
        Assert.Equal("presentation_custom_show_topology_changed", Assert.Single(Export(added).Diagnostics).Code);

        var identityChanged = Import(authored.File.ToByteArray()).Artifact;
        identityChanged.Presentation.CustomShows[0].NativeId = 99;
        Assert.Equal("presentation_custom_show_topology_changed", Assert.Single(Export(identityChanged).Diagnostics).Code);

        var bindingChanged = Import(authored.File.ToByteArray()).Artifact;
        bindingChanged.Presentation.CustomShows[0].Source.SemanticSha256 = new string('0', 64);
        Assert.Equal("presentation_custom_show_source_binding_mismatch", Assert.Single(Export(bindingChanged).Diagnostics).Code);
    }

    [Fact]
    public void PowerPointSectionsAuthorImportAndEditWithinFixedTopology()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides.Add(new PresentationSlide { Id = "presentation/slide/2", Name = "Evidence" });
        request.Artifact.Presentation.Slides.Add(new PresentationSlide { Id = "presentation/slide/3", Name = "Appendix" });
        var opening = new PresentationSectionArtifact
        {
            Id = "section/opening",
            Name = "Opening",
            NativeId = "{01F07B81-39E6-4BBB-9B89-66EA253FBD29}",
        };
        opening.SlideIds.Add("presentation/slide/1");
        var content = new PresentationSectionArtifact
        {
            Id = "section/content",
            Name = "Content",
            NativeId = "{1FEF2C88-0CF2-4176-BA81-0DE6FD9D1274}",
        };
        content.SlideIds.Add("presentation/slide/2");
        content.SlideIds.Add("presentation/slide/3");
        request.Artifact.Presentation.Sections.Add(opening);
        request.Artifact.Presentation.Sections.Add(content);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var extension = Assert.Single(
                package.PresentationPart!.Presentation!.PresentationExtensionList!.Elements<P.PresentationExtension>(),
                candidate => candidate.Uri?.Value == PptxSectionCodec.ExtensionUri);
            var sections = extension.GetFirstChild<P14.SectionList>()!.Elements<P14.Section>().ToArray();
            Assert.Equal(2, sections.Length);
            Assert.Equal(("Opening", "{01F07B81-39E6-4BBB-9B89-66EA253FBD29}"), (sections[0].Name!.Value, sections[0].Id!.Value));
            Assert.Equal(new[] { 256U }, sections[0].SectionSlideIdList!.Elements<P14.SectionSlideIdListEntry>().Select(entry => entry.Id!.Value));
            Assert.Equal(("Content", "{1FEF2C88-0CF2-4176-BA81-0DE6FD9D1274}"), (sections[1].Name!.Value, sections[1].Id!.Value));
            Assert.Equal(new[] { 257U, 258U }, sections[1].SectionSlideIdList!.Elements<P14.SectionSlideIdListEntry>().Select(entry => entry.Id!.Value));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.False(imported.Artifact.Presentation.SectionsOpaque);
        Assert.Collection(imported.Artifact.Presentation.Sections,
            section =>
            {
                Assert.Equal("Opening", section.Name);
                Assert.Equal("{01F07B81-39E6-4BBB-9B89-66EA253FBD29}", section.NativeId);
                Assert.Equal(new[] { "presentation/slide/1" }, section.SlideIds);
                Assert.True(section.Source!.Editable);
            },
            section =>
            {
                Assert.Equal("Content", section.Name);
                Assert.Equal("{1FEF2C88-0CF2-4176-BA81-0DE6FD9D1274}", section.NativeId);
                Assert.Equal(new[] { "presentation/slide/2", "presentation/slide/3" }, section.SlideIds);
                Assert.True(section.Source!.Editable);
            });

        imported.Artifact.Presentation.Sections[0].Name = "Introduction";
        imported.Artifact.Presentation.Sections[0].SlideIds.Clear();
        imported.Artifact.Presentation.Sections[0].SlideIds.Add("presentation/slide/1");
        imported.Artifact.Presentation.Sections[0].SlideIds.Add("presentation/slide/2");
        imported.Artifact.Presentation.Sections[1].SlideIds.Clear();
        imported.Artifact.Presentation.Sections[1].SlideIds.Add("presentation/slide/3");
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        Assert.Collection(roundTrip.Artifact.Presentation.Sections,
            section =>
            {
                Assert.Equal("Introduction", section.Name);
                Assert.Equal("{01F07B81-39E6-4BBB-9B89-66EA253FBD29}", section.NativeId);
                Assert.Equal(new[] { "presentation/slide/1", "presentation/slide/2" }, section.SlideIds);
            },
            section => Assert.Equal(new[] { "presentation/slide/3" }, section.SlideIds));

        var added = Import(authored.File.ToByteArray()).Artifact;
        var extra = new PresentationSectionArtifact
        {
            Id = "section/extra",
            Name = "Extra",
            NativeId = "{CA1E145A-94F4-4C2D-9BC0-76C4A01D48ED}",
        };
        extra.SlideIds.Add("presentation/slide/1");
        extra.SlideIds.Add("presentation/slide/2");
        extra.SlideIds.Add("presentation/slide/3");
        added.Presentation.Sections.Add(extra);
        Assert.Equal("presentation_section_topology_changed", Assert.Single(Export(added).Diagnostics).Code);

        var identityChanged = Import(authored.File.ToByteArray()).Artifact;
        identityChanged.Presentation.Sections[0].NativeId = "{CA1E145A-94F4-4C2D-9BC0-76C4A01D48ED}";
        Assert.Equal("presentation_section_topology_changed", Assert.Single(Export(identityChanged).Diagnostics).Code);

        var bindingChanged = Import(authored.File.ToByteArray()).Artifact;
        bindingChanged.Presentation.Sections[0].Source.SemanticSha256 = new string('0', 64);
        Assert.Equal("presentation_section_source_binding_mismatch", Assert.Single(Export(bindingChanged).Diagnostics).Code);

        var clone = Import(authored.File.ToByteArray()).Artifact;
        AddPendingClone(clone.Presentation, 0, "presentation/clone/section");
        Assert.Equal("unsupported_presentation_slide_clone", Assert.Single(Export(clone).Diagnostics).Code);
    }

    [Fact]
    public void IrregularPowerPointSectionGraphRemainsOpaqueAndFailClosed()
    {
        var request = ExportRequest();
        var section = new PresentationSectionArtifact
        {
            Id = "section/1",
            Name = "Canonical",
            NativeId = "{01F07B81-39E6-4BBB-9B89-66EA253FBD29}",
        };
        section.SlideIds.Add("presentation/slide/1");
        request.Artifact.Presentation.Sections.Add(section);
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));

        using var stream = new MemoryStream();
        stream.Write(authored.File.Span);
        stream.Position = 0;
        using (var package = PresentationDocument.Open(stream, true))
        {
            var extension = Assert.Single(
                package.PresentationPart!.Presentation!.PresentationExtensionList!.Elements<P.PresentationExtension>(),
                candidate => candidate.Uri?.Value == PptxSectionCodec.ExtensionUri);
            extension.GetFirstChild<P14.SectionList>()!.GetFirstChild<P14.Section>()!.Append(new P14.ExtensionList());
            package.PresentationPart.Presentation.Save();
        }
        var irregularBytes = stream.ToArray();
        var imported = Import(irregularBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.True(imported.Artifact.Presentation.SectionsOpaque);
        Assert.Empty(imported.Artifact.Presentation.Sections);
        Assert.Contains(imported.Diagnostics, diagnostic => diagnostic.Code == "opaque_presentation_sections_retained");

        var preserved = Export(imported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        static string SectionXml(byte[] bytes)
        {
            using var source = new MemoryStream(bytes);
            using var package = PresentationDocument.Open(source, false);
            var extension = package.PresentationPart!.Presentation!.PresentationExtensionList!.Elements<P.PresentationExtension>()
                .Single(candidate => candidate.Uri?.Value == PptxSectionCodec.ExtensionUri);
            return extension.OuterXml;
        }
        Assert.Equal(SectionXml(irregularBytes), SectionXml(preserved.File.ToByteArray()));

        imported.Artifact.Presentation.SectionsOpaque = false;
        var rejected = Export(imported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_section_topology_changed", Assert.Single(rejected.Diagnostics).Code);
    }

