    [Fact]
    public void SlideVisibilityAuthorsImportsEditsAndRejectsOpaqueLexicalValues()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Hidden = true;
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            Assert.False(Assert.Single(package.PresentationPart!.SlideParts).Slide!.Show!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var hidden = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.True(hidden.HasHidden);
        Assert.True(hidden.Hidden);
        Assert.True(hidden.Source!.VisibilityEditable);
        Assert.NotEmpty(hidden.Source.VisibilitySemanticSha256);

        hidden.Hidden = false;
        var shown = Export(imported.Artifact);
        Assert.True(shown.Ok, Diagnostics(shown));
        using (var stream = new MemoryStream(shown.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Null(Assert.Single(package.PresentationPart!.SlideParts).Slide!.Show);
        var shownRoundTrip = Assert.Single(Import(shown.File.ToByteArray()).Artifact.Presentation.Slides);
        Assert.True(shownRoundTrip.HasHidden);
        Assert.False(shownRoundTrip.Hidden);

        var stale = Import(authored.File.ToByteArray());
        stale.Artifact.Presentation.Slides[0].Source!.VisibilitySemanticSha256 = new string('0', 64);
        Assert.Equal("presentation_slide_binding_mismatch", Assert.Single(Export(stale.Artifact).Diagnostics).Code);

        var opaqueBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            xml.Replace("show=\"0\"", "show=\"sometimes\"", StringComparison.Ordinal));
        var opaque = Import(opaqueBytes);
        Assert.True(opaque.Ok, Diagnostics(opaque));
        var opaqueSlide = Assert.Single(opaque.Artifact.Presentation.Slides);
        Assert.False(opaqueSlide.HasHidden);
        Assert.False(opaqueSlide.Source!.VisibilityEditable);
        var preserved = Export(opaque.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Equal(ZipBytes(opaqueBytes, "ppt/slides/slide1.xml"), ZipBytes(preserved.File.ToByteArray(), "ppt/slides/slide1.xml"));

        opaqueSlide.Hidden = true;
        Assert.Equal("presentation_slide_visibility_binding_mismatch", Assert.Single(Export(opaque.Artifact).Diagnostics).Code);
    }

    [Fact]
    public void LegacyCommentsAuthorImportSupportsTextOnlySourceBoundEdits()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "presentation/slide/1/legacy-comment/1",
            Author = "Review Owner",
            Text = "Confirm the customer evidence before delivery.",
            CreatedAt = "2026-07-18T02:55:00Z",
            PositionXEmu = 1_234_500,
            PositionYEmu = 2_345_600,
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var author = Assert.Single(package.PresentationPart!.CommentAuthorsPart!.CommentAuthorList!.Elements<P.CommentAuthor>());
            Assert.Equal("Review Owner", author.Name!.Value);
            Assert.Equal(0U, author.Id!.Value);
            Assert.Equal(1U, author.LastIndex!.Value);
            var comment = Assert.Single(Assert.Single(package.PresentationPart.SlideParts).SlideCommentsPart!.CommentList!.Elements<P.Comment>());
            Assert.Equal(0U, comment.AuthorId!.Value);
            Assert.Equal(1U, comment.Index!.Value);
            Assert.Equal("Confirm the customer evidence before delivery.", comment.Text!.Text);
            Assert.Equal(1_234_500L, comment.Position!.X!.Value);
            Assert.Equal(2_345_600L, comment.Position.Y!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedSlide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.False(importedSlide.Source.LegacyCommentsAddable);
        Assert.True(importedSlide.Source.LegacyCommentsEditable);
        Assert.True(importedSlide.Source.CommentPartPresent);
        Assert.Equal("legacy", importedSlide.Source.CommentFamily);
        var importedComment = Assert.Single(importedSlide.LegacyComments);
        Assert.Equal("presentation/slide/1/legacy-comment/1", importedComment.Id);
        Assert.Equal("Review Owner", importedComment.Author);
        Assert.Equal("Confirm the customer evidence before delivery.", importedComment.Text);
        Assert.Equal(1_234_500L, importedComment.PositionXEmu);
        Assert.Equal(2_345_600L, importedComment.PositionYEmu);
        Assert.Equal(0U, importedComment.NativeAuthorId);
        Assert.Equal(1U, importedComment.NativeIndex);

        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(
            ZipBytes(authored.File.ToByteArray(), "ppt/comments/comment1.xml"),
            ZipBytes(unchanged.File.ToByteArray(), "ppt/comments/comment1.xml"));
        Assert.Equal(
            ZipBytes(authored.File.ToByteArray(), "ppt/commentAuthors.xml"),
            ZipBytes(unchanged.File.ToByteArray(), "ppt/commentAuthors.xml"));

        importedComment.Text = "Changed after import.";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.NotEqual(
            ZipBytes(authored.File.ToByteArray(), "ppt/comments/comment1.xml"),
            ZipBytes(edited.File.ToByteArray(), "ppt/comments/comment1.xml"));
        Assert.Equal(
            ZipBytes(authored.File.ToByteArray(), "ppt/commentAuthors.xml"),
            ZipBytes(edited.File.ToByteArray(), "ppt/commentAuthors.xml"));
        Assert.Equal(
            ZipBytes(authored.File.ToByteArray(), "ppt/slides/slide1.xml"),
            ZipBytes(edited.File.ToByteArray(), "ppt/slides/slide1.xml"));
        var editedRoundTrip = Import(edited.File.ToByteArray());
        Assert.True(editedRoundTrip.Ok, Diagnostics(editedRoundTrip));
        var editedComment = Assert.Single(Assert.Single(editedRoundTrip.Artifact.Presentation.Slides).LegacyComments);
        Assert.Equal("Changed after import.", editedComment.Text);
        Assert.Equal("Review Owner", editedComment.Author);
        Assert.Equal("2026-07-18T02:55:00.0000000Z", editedComment.CreatedAt);
        Assert.Equal(1_234_500L, editedComment.PositionXEmu);
        Assert.Equal(2_345_600L, editedComment.PositionYEmu);
        Assert.Equal(0U, editedComment.NativeAuthorId);
        Assert.Equal(1U, editedComment.NativeIndex);

        var positionMutation = Import(authored.File.ToByteArray());
        Assert.True(positionMutation.Ok, Diagnostics(positionMutation));
        Assert.Single(positionMutation.Artifact.Presentation.Slides).LegacyComments[0].PositionXEmu++;
        var rejected = Export(positionMutation.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_comment_edit", Assert.Single(rejected.Diagnostics).Code);

        var authorMutation = Import(authored.File.ToByteArray());
        Assert.True(authorMutation.Ok, Diagnostics(authorMutation));
        Assert.Single(authorMutation.Artifact.Presentation.Slides).LegacyComments[0].Author = "Different reviewer";
        rejected = Export(authorMutation.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_comment_edit", Assert.Single(rejected.Diagnostics).Code);

        var invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "invalid-comment",
            Author = "Reviewer",
            Text = "Needs an invalid timestamp.",
            CreatedAt = "not-a-timestamp",
        });
        rejected = Invoke(invalid);
        Assert.False(rejected.Ok);
        Assert.Equal("invalid_presentation_legacy_comment", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void LegacyCommentsSourceBoundEditRetainsOtherCanonicalText()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "presentation/slide/1/legacy-comment/1",
            Author = "Review Owner",
            Text = "Keep this first review note unchanged.",
            CreatedAt = "2026-07-18T03:05:00Z",
            PositionXEmu = 1_000_000,
            PositionYEmu = 2_000_000,
        });
        request.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "presentation/slide/1/legacy-comment/2",
            Author = "Review Owner",
            Text = "Replace only this second review note.",
            CreatedAt = "2026-07-18T03:06:00Z",
            PositionXEmu = 3_000_000,
            PositionYEmu = 4_000_000,
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedSlide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.True(importedSlide.Source.LegacyCommentsEditable);
        importedSlide.LegacyComments[1].Text = "The second review note has the approved wording.";

        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var editedBytes = edited.File.ToByteArray();
        Assert.Equal(ZipBytes(sourceBytes, "ppt/commentAuthors.xml"), ZipBytes(editedBytes, "ppt/commentAuthors.xml"));
        Assert.NotEqual(ZipBytes(sourceBytes, "ppt/comments/comment1.xml"), ZipBytes(editedBytes, "ppt/comments/comment1.xml"));

        var roundTrip = Import(editedBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var comments = Assert.Single(roundTrip.Artifact.Presentation.Slides).LegacyComments;
        Assert.Equal("Keep this first review note unchanged.", comments[0].Text);
        Assert.Equal("The second review note has the approved wording.", comments[1].Text);
        Assert.Equal((1_000_000L, 2_000_000L, 0U, 1U), (comments[0].PositionXEmu, comments[0].PositionYEmu, comments[0].NativeAuthorId, comments[0].NativeIndex));
        Assert.Equal((3_000_000L, 4_000_000L, 0U, 2U), (comments[1].PositionXEmu, comments[1].PositionYEmu, comments[1].NativeAuthorId, comments[1].NativeIndex));
    }

    [Fact]
    public void ImportedCommentFreePresentationAddsCanonicalLegacyReviewGraphAndRejectsCapabilityTampering()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides.Add(new PresentationSlide
        {
            Id = "presentation/slide/2",
            Name = "Second review target",
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = AddLegacyCommentRelationshipIdCollisions(authored.File.ToByteArray());

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.All(imported.Artifact.Presentation.Slides, slide => Assert.True(slide.Source.LegacyCommentsAddable));
        imported.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "review-a",
            Author = "Review Owner",
            Text = "Confirm the customer evidence.",
            CreatedAt = "2026-07-20T03:04:05Z",
            PositionXEmu = 1_234_500,
            PositionYEmu = 2_345_600,
        });
        imported.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "review-b",
            Author = "Legal Owner",
            Text = "Confirm the release language.",
            CreatedAt = "2026-07-20T03:05:06Z",
            PositionXEmu = 2_000_000,
            PositionYEmu = 1_000_000,
        });
        imported.Artifact.Presentation.Slides[1].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "review-c",
            Author = "Review Owner",
            Text = "Carry the evidence into the appendix.",
            CreatedAt = "2026-07-20T03:06:07Z",
            PositionXEmu = 3_000_000,
            PositionYEmu = 1_500_000,
        });

        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        var outputBytes = exported.File.ToByteArray();
        using (var stream = new MemoryStream(outputBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var presentationPart = package.PresentationPart!;
            var authorsPart = Assert.IsType<CommentAuthorsPart>(presentationPart.CommentAuthorsPart);
            Assert.NotEqual("rIdCommentAuthors1", presentationPart.GetIdOfPart(authorsPart));
            Assert.Contains(presentationPart.HyperlinkRelationships, relationship => relationship.Id == "rIdCommentAuthors1");
            var authors = authorsPart.CommentAuthorList!.Elements<P.CommentAuthor>().ToArray();
            Assert.Equal(2, authors.Length);
            Assert.Equal((0U, "Review Owner", 2U), (authors[0].Id!.Value, authors[0].Name!.Value, authors[0].LastIndex!.Value));
            Assert.Equal((1U, "Legal Owner", 1U), (authors[1].Id!.Value, authors[1].Name!.Value, authors[1].LastIndex!.Value));

            var slides = OrderedSlides(package);
            Assert.All(slides, slide =>
            {
                var commentsPart = Assert.IsType<SlideCommentsPart>(slide.SlideCommentsPart);
                Assert.NotEqual("rIdComments1", slide.GetIdOfPart(commentsPart));
                Assert.Contains(slide.HyperlinkRelationships, relationship => relationship.Id == "rIdComments1");
                Assert.Empty(commentsPart.Parts);
                Assert.Empty(commentsPart.ExternalRelationships);
            });
            var first = slides[0].SlideCommentsPart!.CommentList!.Elements<P.Comment>().ToArray();
            Assert.Equal((0U, 1U), (first[0].AuthorId!.Value, first[0].Index!.Value));
            Assert.Equal((1U, 1U), (first[1].AuthorId!.Value, first[1].Index!.Value));
            var second = Assert.Single(slides[1].SlideCommentsPart!.CommentList!.Elements<P.Comment>());
            Assert.Equal((0U, 2U), (second.AuthorId!.Value, second.Index!.Value));
        }

        var roundTrip = Import(outputBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        Assert.All(roundTrip.Artifact.Presentation.Slides, slide => Assert.False(slide.Source.LegacyCommentsAddable));
        Assert.Equal(
            ["Confirm the customer evidence.", "Confirm the release language.", "Carry the evidence into the appendix."],
            roundTrip.Artifact.Presentation.Slides.SelectMany(slide => slide.LegacyComments).Select(comment => comment.Text));

        var falselyGranted = Import(outputBytes);
        falselyGranted.Artifact.Presentation.Slides[0].Source.LegacyCommentsAddable = true;
        var rejected = Export(falselyGranted.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_slide_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);

        var falselyRevoked = Import(sourceBytes);
        falselyRevoked.Artifact.Presentation.Slides[0].Source.LegacyCommentsAddable = false;
        falselyRevoked.Artifact.Presentation.Slides[0].LegacyComments.Add(new PresentationLegacyComment
        {
            Id = "cannot-self-authorize",
            Author = "Review Owner",
            Text = "The source binding is immutable evidence.",
            CreatedAt = "2026-07-20T03:07:08Z",
            PositionXEmu = 1_000_000,
            PositionYEmu = 1_000_000,
        });
        rejected = Export(falselyRevoked.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_slide_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ModernCommentThreadRoundTripsAndAllowsOnlyTextAndStatusEdits()
    {
        var request = ExportRequest();
        var thread = new PresentationModernCommentThread
        {
            Id = "{11111111-1111-4111-8111-111111111111}",
            TargetId = "presentation/slide/1/title/text",
            PositionXEmu = 1_234_500,
            PositionYEmu = 2_345_600,
            Anchor = new PresentationModernCommentAnchor
            {
                Kind = PresentationModernCommentAnchor.Types.Kind.TextRange,
                NativeSlideId = 256,
                TextStart = 0,
                TextLength = 9,
            },
            Root = new PresentationModernComment
            {
                Id = "{11111111-1111-4111-8111-111111111111}",
                AuthorId = "{AAAAAAAA-AAAA-4AAA-8AAA-AAAAAAAAAAAA}",
                Author = "Review Owner",
                Initials = "RO",
                UserId = "review.owner@example.test",
                ProviderId = "None",
                Text = "Confirm the customer evidence.",
                CreatedAt = "2026-07-19T02:55:00Z",
                Status = "active",
            },
        };
        thread.Anchor.Monikers.Add(new PresentationModernCommentMoniker { Type = "spMk", NativeId = 2 });
        thread.Replies.Add(new PresentationModernComment
        {
            Id = "{22222222-2222-4222-8222-222222222222}",
            AuthorId = "{BBBBBBBB-BBBB-4BBB-8BBB-BBBBBBBBBBBB}",
            Author = "Evidence Owner",
            Initials = "EO",
            UserId = "evidence.owner@example.test",
            ProviderId = "None",
            Text = "Evidence is attached.",
            CreatedAt = "2026-07-19T03:05:00Z",
            Status = "active",
        });
        request.Artifact.Presentation.Slides[0].ModernComments.Add(thread);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var authoredBytes = authored.File.ToByteArray();
        using (var stream = new MemoryStream(authoredBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var authorsPart = Assert.Single(package.PresentationPart!.Parts.Select(pair => pair.OpenXmlPart).OfType<PowerPointAuthorsPart>());
            var commentsPart = Assert.Single(Assert.Single(package.PresentationPart.SlideParts).Parts.Select(pair => pair.OpenXmlPart).OfType<PowerPointCommentPart>());
            Assert.Equal("application/vnd.ms-powerpoint.authors+xml", authorsPart.ContentType);
            Assert.Equal("application/vnd.ms-powerpoint.comments+xml", commentsPart.ContentType);
        }

        var imported = Import(authoredBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedSlide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.False(importedSlide.Source.LegacyCommentsAddable);
        Assert.True(importedSlide.Source.CommentPartPresent);
        Assert.Equal("modern", importedSlide.Source.CommentFamily);
        var importedThread = Assert.Single(importedSlide.ModernComments);
        Assert.Equal("presentation/slide/1/element/1/text", importedThread.TargetId);
        Assert.Equal(PresentationModernCommentAnchor.Types.Kind.TextRange, importedThread.Anchor.Kind);
        Assert.Equal(0U, importedThread.Anchor.TextStart);
        Assert.Equal(9U, importedThread.Anchor.TextLength);
        Assert.Equal("Confirm the customer evidence.", importedThread.Root.Text);
        Assert.Equal("Evidence is attached.", Assert.Single(importedThread.Replies).Text);
        Assert.True(importedThread.Source.Editable);
        Assert.Equal(64, importedThread.Source.CommentXmlSha256.Length);
        Assert.Equal(64, importedThread.Source.AuthorsXmlSha256.Length);
        Assert.Equal(64, importedThread.Source.FixedTopologySha256.Length);

        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(
            ModernPartBytes<PowerPointCommentPart>(authoredBytes),
            ModernPartBytes<PowerPointCommentPart>(unchanged.File.ToByteArray()));
        Assert.Equal(
            ModernPartBytes<PowerPointAuthorsPart>(authoredBytes),
            ModernPartBytes<PowerPointAuthorsPart>(unchanged.File.ToByteArray()));

        importedThread.Root.Text = "Customer evidence confirmed.";
        importedThread.Root.Status = "resolved";
        importedThread.Replies[0].Text = "Recorded in the decision log.";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        using (var stream = new MemoryStream(edited.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripThread = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).ModernComments);
        Assert.Equal("Customer evidence confirmed.", roundTripThread.Root.Text);
        Assert.Equal("resolved", roundTripThread.Root.Status);
        Assert.Equal("Recorded in the decision log.", Assert.Single(roundTripThread.Replies).Text);

        roundTripThread.Root.Author = "Changed identity";
        var rejected = Export(roundTrip.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_comment_topology_changed", Assert.Single(rejected.Diagnostics).Code);
    }

