    [Fact]
    public void ConnectedModernCommentGraphStaysOpaqueAndRejectsModeledReplacement()
    {
        var authored = Invoke(ModernCommentExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var commentPath = SingleZipEntryPath(authored.File.ToByteArray(), path => path.StartsWith("ppt/comments/", StringComparison.Ordinal) && path.EndsWith(".xml", StringComparison.Ordinal));
        var fileName = Path.GetFileName(commentPath);
        var relationshipPath = $"ppt/comments/_rels/{fileName}.rels";
        var connected = AddZipText(
            authored.File.ToByteArray(),
            relationshipPath,
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rIdUnexpected\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink\" Target=\"https://example.invalid/review\" TargetMode=\"External\"/></Relationships>");

        var imported = Import(connected);
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.Empty(Assert.Single(imported.Artifact.Presentation.Slides).ModernComments);
        Assert.Contains(imported.Diagnostics, diagnostic => diagnostic.Code == "unsupported_presentation_modern_comments_preserved");

        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(ZipBytes(connected, commentPath), ZipBytes(unchanged.File.ToByteArray(), commentPath));
        Assert.Equal(ZipBytes(connected, relationshipPath), ZipBytes(unchanged.File.ToByteArray(), relationshipPath));

        imported.Artifact.Presentation.Slides[0].ModernComments.Add(
            ModernCommentExportRequest().Artifact.Presentation.Slides[0].ModernComments[0].Clone());
        var rejected = Export(imported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_comment_edit", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ImportedViewPropertiesExposeGridSnapAndGuidesAndRemainSourceBound()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = AddViewProperties(authored.File.ToByteArray());
        var sourceViewXml = ZipBytes(sourceBytes, "ppt/viewProps.xml");

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var view = imported.Artifact.Presentation.ViewProperties;
        Assert.NotNull(view);
        Assert.Equal(72_008, view.GridSpacingCxEmu);
        Assert.Equal(91_440, view.GridSpacingCyEmu);
        Assert.True(view.SlideViewSnapToGrid);
        Assert.False(view.SlideViewSnapToObjects);
        Assert.Collection(view.SlideGuides,
            guide =>
            {
                Assert.Equal(PresentationSlideGuide.Types.Orientation.Horizontal, guide.Orientation);
                Assert.Equal(2_160, guide.Position);
            },
            guide =>
            {
                Assert.Equal(PresentationSlideGuide.Types.Orientation.Vertical, guide.Orientation);
                Assert.Equal(2_880, guide.Position);
            });
        Assert.Equal("ppt/viewProps.xml", view.Source.PartPath);
        Assert.False(string.IsNullOrWhiteSpace(view.Source.RelationshipId));
        Assert.Equal(64, view.Source.ViewXmlSha256.Length);
        Assert.Equal(64, view.Source.SemanticSha256.Length);
        Assert.Equal(64, view.Source.ResidualSha256.Length);
        Assert.True(view.Source.Editable);

        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(sourceViewXml, ZipBytes(unchanged.File.ToByteArray(), "ppt/viewProps.xml"));
        using (var stream = new MemoryStream(unchanged.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));

        view.GridSpacingCxEmu = 72_009;
        view.GridSpacingCyEmu = 91_441;
        view.SlideViewSnapToGrid = false;
        view.SlideViewSnapToObjects = true;
        view.SlideGuides[0].Position = 2_161;
        view.SlideGuides[1].Position = 2_881;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var editedBytes = edited.File.ToByteArray();
        Assert.Equal(ZipPartPaths(sourceBytes), ZipPartPaths(editedBytes));
        foreach (var path in ZipPartPaths(sourceBytes).Where(path => !path.Equals("ppt/viewProps.xml", StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(sourceBytes, path), ZipBytes(editedBytes, path));
        var editedViewXml = Encoding.UTF8.GetString(ZipBytes(editedBytes, "ppt/viewProps.xml"));
        Assert.Contains("cx=\"72009\"", editedViewXml);
        Assert.Contains("cy=\"91441\"", editedViewXml);
        Assert.Contains("snapToGrid=\"0\"", editedViewXml);
        Assert.Contains("snapToObjects=\"1\"", editedViewXml);
        Assert.Contains("showGuides=\"1\"", editedViewXml);
        Assert.Contains("orient=\"horz\" pos=\"2161\"", editedViewXml);
        Assert.Contains("orient=\"vert\" pos=\"2881\"", editedViewXml);

        var reimported = Import(editedBytes);
        Assert.True(reimported.Ok, Diagnostics(reimported));
        var reimportedView = reimported.Artifact.Presentation.ViewProperties;
        Assert.Equal(72_009, reimportedView.GridSpacingCxEmu);
        Assert.Equal(91_441, reimportedView.GridSpacingCyEmu);
        Assert.False(reimportedView.SlideViewSnapToGrid);
        Assert.True(reimportedView.SlideViewSnapToObjects);
        Assert.Equal(2_161, reimportedView.SlideGuides[0].Position);
        Assert.Equal(2_881, reimportedView.SlideGuides[1].Position);

        var guideTopologyChanged = Import(sourceBytes);
        Assert.True(guideTopologyChanged.Ok, Diagnostics(guideTopologyChanged));
        guideTopologyChanged.Artifact.Presentation.ViewProperties.SlideGuides.Add(new PresentationSlideGuide
        {
            Orientation = PresentationSlideGuide.Types.Orientation.Horizontal,
            Position = 9_999,
        });
        var rejected = Export(guideTopologyChanged.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_view_topology_changed", Assert.Single(rejected.Diagnostics).Code);

        var sourceBindingChanged = Import(sourceBytes);
        Assert.True(sourceBindingChanged.Ok, Diagnostics(sourceBindingChanged));
        sourceBindingChanged.Artifact.Presentation.ViewProperties.Source.ResidualSha256 = new string('0', 64);
        rejected = Export(sourceBindingChanged.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_view_source_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);

        var sourceFree = ExportRequest();
        sourceFree.Artifact.Presentation.ViewProperties = new PresentationViewProperties
        {
            GridSpacingCxEmu = 72_008,
        };
        rejected = Invoke(sourceFree);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_features", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ImportedShapeBackgroundFillFlagIsVisiblePreservedAndReadOnly()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        byte[] sourceBytes;
        using (var stream = new MemoryStream())
        {
            stream.Write(authored.File.Span);
            stream.Position = 0;
            using (var package = PresentationDocument.Open(stream, true))
            {
                var slidePart = Assert.Single(package.PresentationPart!.SlideParts);
                var shape = Assert.Single(slidePart.Slide!.Descendants<P.Shape>());
                shape.UseBackgroundFill = true;
                slidePart.Slide.Save();
            }
            sourceBytes = stream.ToArray();
        }
        var sourceSlideXml = ZipBytes(sourceBytes, "ppt/slides/slide1.xml");

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedShape = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements).Shape;
        Assert.True(importedShape.HasUseBackgroundFill);
        Assert.True(importedShape.UseBackgroundFill);

        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(sourceSlideXml, ZipBytes(unchanged.File.ToByteArray(), "ppt/slides/slide1.xml"));
        using (var stream = new MemoryStream(unchanged.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));

        importedShape.UseBackgroundFill = false;
        var rejected = Export(imported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rejected.Diagnostics).Code);

        var sourceFree = ExportRequest();
        sourceFree.Artifact.Presentation.Slides[0].Elements[0].Shape.UseBackgroundFill = true;
        rejected = Invoke(sourceFree);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_features", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void SpeakerNotesAuthorImportEditAndFailClosedForUnsupportedSourceText()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].SpeakerNotes = new PresentationSpeakerNotes
        {
            Text = "Open with the customer outcome.\nThen explain the operating model.",
        };
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            Assert.NotNull(package.PresentationPart!.NotesMasterPart);
            var notesPart = Assert.Single(package.PresentationPart.SlideParts).NotesSlidePart;
            Assert.NotNull(notesPart);
            Assert.NotNull(notesPart!.NotesMasterPart);
            Assert.Equal(2, notesPart.NotesSlide!.Descendants<A.Paragraph>().Count());
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedNotes = Assert.Single(imported.Artifact.Presentation.Slides).SpeakerNotes;
        Assert.Equal("Open with the customer outcome.\nThen explain the operating model.", importedNotes.Text);
        Assert.True(importedNotes.Source.Editable);
        Assert.StartsWith("ppt/notesSlides/notesSlide", importedNotes.Source.PartPath, StringComparison.OrdinalIgnoreCase);

        importedNotes.Text = "Lead with evidence.\nClose with the decision.";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        Assert.Equal("Lead with evidence.\nClose with the decision.", Assert.Single(roundTrip.Artifact.Presentation.Slides).SpeakerNotes.Text);

        var richRequest = ExportRequest();
        richRequest.Artifact.Presentation.Slides[0].SpeakerNotes = RichSpeakerNotes();
        var richAuthored = Invoke(richRequest);
        Assert.True(richAuthored.Ok, Diagnostics(richAuthored));
        using (var stream = new MemoryStream(richAuthored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var nativeParagraphs = package.PresentationPart!.SlideParts.Single().NotesSlidePart!.NotesSlide!
                .Descendants<A.Paragraph>().ToArray();
            Assert.Equal(2, nativeParagraphs.Length);
            Assert.Equal(2, nativeParagraphs[0].Elements<A.Run>().Count());
            Assert.True(nativeParagraphs[0].Elements<A.Run>().First().RunProperties!.Bold!.Value);
            Assert.True(nativeParagraphs[0].Elements<A.Run>().Last().RunProperties!.Italic!.Value);
            Assert.NotNull(nativeParagraphs[0].ParagraphProperties!.GetFirstChild<A.CharacterBullet>());
            var autoNumber = nativeParagraphs[1].ParagraphProperties!.GetFirstChild<A.AutoNumberedBullet>()!;
            Assert.Equal("arabicPeriod", autoNumber.Type!.InnerText);
            Assert.Equal(2, autoNumber.StartAt!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var rich = Import(richAuthored.File.ToByteArray());
        Assert.True(rich.Ok, Diagnostics(rich));
        var richNotes = Assert.Single(rich.Artifact.Presentation.Slides).SpeakerNotes;
        Assert.True(richNotes.Source.Editable);
        Assert.Equal(2, richNotes.TextBody.Paragraphs.Count);
        Assert.Equal(2, richNotes.TextBody.Paragraphs[0].Runs.Count);
        Assert.True(richNotes.TextBody.Paragraphs[0].Runs[0].Bold);
        Assert.True(richNotes.TextBody.Paragraphs[0].Runs[1].Italic);
        Assert.Equal("arabicPeriod", richNotes.TextBody.Paragraphs[1].AutoNumber.Scheme);
        Assert.Equal(2U, richNotes.TextBody.Paragraphs[1].AutoNumber.StartAt);

        var richNoOp = Export(rich.Artifact);
        Assert.True(richNoOp.Ok, Diagnostics(richNoOp));
        Assert.Equal(
            ZipBytes(richAuthored.File.ToByteArray(), "ppt/notesSlides/notesSlide1.xml"),
            ZipBytes(richNoOp.File.ToByteArray(), "ppt/notesSlides/notesSlide1.xml"));

        richNotes.TextBody.Paragraphs[0].Runs[1].Text = "evidence.";
        richNotes.TextBody.Paragraphs[0].Runs[1].Italic = false;
        richNotes.TextBody.Paragraphs[0].Runs[1].Bold = true;
        richNotes.Text = PptxTextCodec.Flatten(richNotes.TextBody);
        var richEdited = Export(rich.Artifact);
        Assert.True(richEdited.Ok, Diagnostics(richEdited));
        var richRoundTrip = Import(richEdited.File.ToByteArray());
        Assert.True(richRoundTrip.Ok, Diagnostics(richRoundTrip));
        var editedNotes = Assert.Single(richRoundTrip.Artifact.Presentation.Slides).SpeakerNotes;
        Assert.Equal("Open with evidence.\nThen explain the operating model.", editedNotes.Text);
        Assert.True(editedNotes.TextBody.Paragraphs[0].Runs[1].Bold);
        Assert.False(editedNotes.TextBody.Paragraphs[0].Runs[1].Italic);

        richNotes.Text = "Do not flatten the source formatting.";
        var rejected = Export(rich.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_notes_text_mismatch", Assert.Single(rejected.Diagnostics).Code);

        var unsupported = Import(AddUnsupportedSpeakerNotesField(richAuthored.File.ToByteArray()));
        Assert.True(unsupported.Ok, Diagnostics(unsupported));
        var unsupportedNotes = Assert.Single(unsupported.Artifact.Presentation.Slides).SpeakerNotes;
        Assert.False(unsupportedNotes.Source.Editable);
        var preserved = Export(unsupported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        unsupportedNotes.Text = "Do not edit source-owned note fields.";
        rejected = Export(unsupported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ImportedSlideWithoutNotesAddsCanonicalNotesMasterAndSlideGraph()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Null(package.PresentationPart!.NotesMasterPart);
            Assert.Null(Assert.Single(package.PresentationPart.SlideParts).NotesSlidePart);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.Null(slide.SpeakerNotes);
        Assert.True(slide.Source.SpeakerNotesAddable);
        slide.SpeakerNotes = new PresentationSpeakerNotes
        {
            Text = "Lead with the decision.\nClose with the accountable owner.",
        };

        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        using (var stream = new MemoryStream(exported.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var presentationPart = package.PresentationPart!;
            var notesMaster = Assert.IsType<NotesMasterPart>(presentationPart.NotesMasterPart);
            var notesMasterId = Assert.Single(presentationPart.Presentation!.NotesMasterIdList!.Elements<P.NotesMasterId>());
            Assert.Equal(presentationPart.GetIdOfPart(notesMaster), notesMasterId.Id!.Value);
            Assert.Single(notesMaster.Parts, pair => pair.OpenXmlPart is ThemePart);
            var outputSlide = Assert.Single(presentationPart.SlideParts);
            var notesPart = Assert.IsType<NotesSlidePart>(outputSlide.NotesSlidePart);
            Assert.Equal(2, notesPart.Parts.Count());
            Assert.Single(notesPart.Parts, pair => pair.OpenXmlPart is NotesMasterPart);
            Assert.Single(notesPart.Parts, pair => pair.OpenXmlPart is SlidePart);
            Assert.Equal(
                "Lead with the decision.Close with the accountable owner.",
                string.Concat(notesPart.NotesSlide!.Descendants<A.Text>().Select(text => text.Text)));
        }

        var roundTrip = Import(exported.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripSlide = Assert.Single(roundTrip.Artifact.Presentation.Slides);
        Assert.Equal("Lead with the decision.\nClose with the accountable owner.", roundTripSlide.SpeakerNotes.Text);
        Assert.True(roundTripSlide.SpeakerNotes.Source.Editable);
        Assert.False(roundTripSlide.Source.SpeakerNotesAddable);

        roundTripSlide.Source.SpeakerNotesAddable = true;
        var grantRejected = Export(roundTrip.Artifact);
        Assert.False(grantRejected.Ok);
        Assert.Equal("presentation_slide_binding_mismatch", Assert.Single(grantRejected.Diagnostics).Code);

        var tampered = Import(authored.File.ToByteArray());
        var tamperedSlide = Assert.Single(tampered.Artifact.Presentation.Slides);
        tamperedSlide.Source.SpeakerNotesAddable = false;
        tamperedSlide.SpeakerNotes = new PresentationSpeakerNotes { Text = "Capability flags do not grant authority." };
        var rejected = Export(tampered.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_slide_binding_mismatch", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void ImportedSlideWithoutNotesReusesExistingNotesMasterAndAvoidsRelationshipCollisions()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].SpeakerNotes = new PresentationSpeakerNotes { Text = "Existing notes stay unchanged." };
        request.Artifact.Presentation.Slides.Add(new PresentationSlide
        {
            Id = "presentation/slide/2",
            Name = "Add notes here",
        });
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = AddNotesRelationshipIdCollision(authored.File.ToByteArray(), 1);
        string notesMasterPath;
        byte[] notesMasterBytes;
        byte[] firstNotesBytes;
        using (var stream = new MemoryStream(sourceBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            notesMasterPath = package.PresentationPart!.NotesMasterPart!.Uri.OriginalString.TrimStart('/');
            notesMasterBytes = ZipBytes(sourceBytes, notesMasterPath);
            firstNotesBytes = ZipBytes(sourceBytes, "ppt/notesSlides/notesSlide1.xml");
        }

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.False(imported.Artifact.Presentation.Slides[0].Source.SpeakerNotesAddable);
        var target = imported.Artifact.Presentation.Slides[1];
        Assert.True(target.Source.SpeakerNotesAddable);
        target.SpeakerNotes = new PresentationSpeakerNotes { Text = "New notes reuse the presentation-wide master." };
        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        var outputBytes = exported.File.ToByteArray();
        Assert.Equal(notesMasterBytes, ZipBytes(outputBytes, notesMasterPath));
        Assert.Equal(firstNotesBytes, ZipBytes(outputBytes, "ppt/notesSlides/notesSlide1.xml"));
        using (var stream = new MemoryStream(outputBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var presentationPart = package.PresentationPart!;
            Assert.Single(presentationPart.Parts, pair => pair.OpenXmlPart is NotesMasterPart);
            var slides = OrderedSlides(package);
            Assert.NotNull(slides[0].NotesSlidePart);
            var added = Assert.IsType<NotesSlidePart>(slides[1].NotesSlidePart);
            Assert.NotEqual("rIdNotes1", slides[1].GetIdOfPart(added));
            Assert.Contains(slides[1].HyperlinkRelationships, relationship => relationship.Id == "rIdNotes1");
            Assert.Equal(presentationPart.NotesMasterPart!.Uri, added.NotesMasterPart!.Uri);
        }
        var roundTrip = Import(outputBytes);
        Assert.Equal("New notes reuse the presentation-wide master.", roundTrip.Artifact.Presentation.Slides[1].SpeakerNotes.Text);
    }

    [Fact]
    public void SlideBackgroundAuthorsImportsEditsClearsAndPreservesUnsupportedSource()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Background = new PresentationBackground
        {
            ColorRgb = "F1F5F9",
            Solid = true,
            OpacityThousandthPercent = 45_000,
        };
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var slide = Assert.Single(package.PresentationPart!.SlideParts).Slide!;
            Assert.Equal("F1F5F9", slide.CommonSlideData!.Background!.Descendants<A.RgbColorModelHex>().Single().Val!.Value);
            Assert.Equal(45_000, slide.CommonSlideData.Background.Descendants<A.Alpha>().Single().Val!.Value);
            Assert.Null(package.PresentationPart.SlideMasterParts.Single().SlideLayoutParts.Single().SlideLayout!.CommonSlideData!.Background);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var slideArtifact = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.True(slideArtifact.Source.BackgroundEditable);
        Assert.Equal("F1F5F9", slideArtifact.Background.ColorRgb);
        Assert.True(slideArtifact.Background.HasOpacityThousandthPercent);
        Assert.Equal(45_000U, slideArtifact.Background.OpacityThousandthPercent);
        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = authored.File,
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/background-opacity.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        using (var projectedJson = JsonDocument.Parse(projected.PresentationProgram.ProgramJson.ToByteArray()))
            Assert.Equal(0.45, projectedJson.RootElement.GetProperty("pages")[0].GetProperty("background").GetProperty("opacity").GetDouble(), 3);
        slideArtifact.Background = new PresentationBackground
        {
            ColorScheme = "accent2",
            StyleReferenceIndex = 1002,
        };
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var editedSlide = Assert.Single(roundTrip.Artifact.Presentation.Slides);
        Assert.Equal("accent2", editedSlide.Background.ColorScheme);
        Assert.Equal(1002U, editedSlide.Background.StyleReferenceIndex);

        editedSlide.Background = null;
        var cleared = Export(roundTrip.Artifact);
        Assert.True(cleared.Ok, Diagnostics(cleared));
        using (var stream = new MemoryStream(cleared.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Null(Assert.Single(package.PresentationPart!.SlideParts).Slide!.CommonSlideData!.Background);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }
        var clearedRoundTrip = Import(cleared.File.ToByteArray());
        Assert.Null(Assert.Single(clearedRoundTrip.Artifact.Presentation.Slides).Background);

        var unsupported = Import(AddUnsupportedSlideBackground(authored.File.ToByteArray()));
        Assert.True(unsupported.Ok, Diagnostics(unsupported));
        var unsupportedSlide = Assert.Single(unsupported.Artifact.Presentation.Slides);
        Assert.False(unsupportedSlide.Source.BackgroundEditable);
        Assert.Null(unsupportedSlide.Background);
        var preserved = Export(unsupported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        unsupportedSlide.Background = new PresentationBackground { ColorRgb = "FFFFFF", Solid = true };
        var rejected = Export(unsupported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void SourceBoundImageBackgroundCropAndOpacityEditOnlySlideAndReprojects()
    {
        var request = ExportRequest();
        var imageBytes = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");
        var assetId = AddPictureAsset(request.Artifact, imageBytes, "image/png");
        request.Artifact.Presentation.Slides[0].Background = new PresentationBackground
        {
            ImagePaint = new PresentationImagePaint
            {
                AssetId = assetId,
                Mode = PresentationImagePaint.Types.Mode.Stretch,
                Crop = new PresentationImageCrop
                {
                    LeftThousandthPercent = 5_000,
                    TopThousandthPercent = 10_000,
                    RightThousandthPercent = 15_000,
                    BottomThousandthPercent = 20_000,
                },
                OpacityThousandthPercent = 82_000,
            },
        };
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var source = RemoveEmbeddedPpj(authored.File.ToByteArray());
        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "background-image/source.pptx",
                AssetRootUri = "background-image/assets",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        var program = JsonNode.Parse(projected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var background = program["pages"]![0]!["background"]!.AsObject();
        Assert.Equal("image", background["type"]!.GetValue<string>());
        Assert.Equal("stretch", background["fit"]!.GetValue<string>());
        Assert.Equal(0.82, background["opacity"]!.GetValue<double>(), precision: 6);
        Assert.Equal(0.05, background["crop"]!["left"]!.GetValue<double>(), precision: 6);
        Assert.Equal(0.2, background["crop"]!["bottom"]!.GetValue<double>(), precision: 6);

        background["crop"]!["left"] = 0.08;
        background["crop"]!["bottom"] = 0.04;
        program["design"]!["grammar"]!["tokens"] = new JsonObject
        {
            ["backgroundFit"] = new JsonObject { ["kind"] = "string", ["value"] = "tile" },
            ["backgroundOpacity"] = new JsonObject { ["kind"] = "opacity", ["value"] = 0.63 },
        };
        background["fit"] = new JsonObject { ["token"] = "backgroundFit" };
        background["opacity"] = new JsonObject { ["token"] = "backgroundOpacity" };
        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(program.ToJsonString()),
            },
        });
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(["ppt/slides/slide1.xml"], edited.PresentationProgram.ChangedParts);
        using (var stream = new MemoryStream(edited.File.ToByteArray(), writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var native = Assert.Single(package.PresentationPart!.SlideParts).Slide!.CommonSlideData!
                .Background!.BackgroundProperties!.GetFirstChild<A.BlipFill>()!;
            var crop = native.GetFirstChild<A.SourceRectangle>()!;
            Assert.Equal(8_000, crop.Left!.Value);
            Assert.Equal(4_000, crop.Bottom!.Value);
            Assert.NotNull(native.GetFirstChild<A.Tile>());
            Assert.Null(native.GetFirstChild<A.Stretch>());
            Assert.Equal(63_000, native.GetFirstChild<A.Blip>()!.GetFirstChild<A.AlphaModulationFixed>()!.Amount!.Value);
        }

        var reprojected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = edited.File,
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "background-image/edited.pptx",
                AssetRootUri = "background-image/assets",
            },
        });
        Assert.True(reprojected.Ok, Diagnostics(reprojected));
        var output = JsonNode.Parse(reprojected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var outputBackground = output["pages"]![0]!["background"]!.AsObject();
        Assert.Equal("tile", outputBackground["fit"]!.GetValue<string>());
        Assert.Equal(0.08, outputBackground["crop"]!["left"]!.GetValue<double>(), precision: 6);
        Assert.Equal(0.04, outputBackground["crop"]!["bottom"]!.GetValue<double>(), precision: 6);
        Assert.Equal(0.63, outputBackground["opacity"]!.GetValue<double>(), precision: 6);
    }

    [Fact]
    public void SourceBoundImageBackgroundReplacementClosesRelationshipsAndReprojects()
    {
        var request = ExportRequest();
        var sourceBytes = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");
        var replacementBytes = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl2nGQAAAAASUVORK5CYII=");
        var sourceAssetId = AddPictureAsset(request.Artifact, sourceBytes, "image/png");
        request.Artifact.Presentation.Slides[0].Background = new PresentationBackground
        {
            ImagePaint = new PresentationImagePaint
            {
                AssetId = sourceAssetId,
                Mode = PresentationImagePaint.Types.Mode.Stretch,
                OpacityThousandthPercent = 91_000,
            },
        };
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var source = RemoveEmbeddedPpj(authored.File.ToByteArray());

        string sourceRelationshipId;
        string sourceImagePartPath;
        using (var stream = new MemoryStream(source, writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slide = Assert.Single(package.PresentationPart!.SlideParts);
            var blip = slide.Slide!.CommonSlideData!.Background!.BackgroundProperties!
                .GetFirstChild<A.BlipFill>()!.GetFirstChild<A.Blip>()!;
            sourceRelationshipId = blip.Embed!.Value!;
            sourceImagePartPath = slide.GetPartById(sourceRelationshipId).Uri.OriginalString.TrimStart('/');
        }

        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "background-image-replacement/source.pptx",
                AssetRootUri = "background-image-replacement/assets",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        var program = JsonNode.Parse(projected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var background = program["pages"]![0]!["background"]!.AsObject();
        var projectedSourceAssetId = background["asset"]!.GetValue<string>();
        var replacementDeclaration = program["assets"]!.AsArray()
            .Select(asset => asset?.AsObject() ?? throw new InvalidOperationException("Projected asset declaration is null."))
            .Single(asset => asset["id"]!.GetValue<string>() == projectedSourceAssetId)
            .DeepClone()
            .AsObject();
        var replacementAssetId = "background-replacement";
        var replacementHash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(replacementBytes)).ToLowerInvariant();
        replacementDeclaration["id"] = replacementAssetId;
        replacementDeclaration["uri"] = "background-image-replacement/assets/replacement.png";
        replacementDeclaration["sha256"] = replacementHash;
        program["assets"]!.AsArray().Add(replacementDeclaration);
        background["asset"] = replacementAssetId;
        background["opacity"] = 0.44;

        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(program.ToJsonString()),
                Assets =
                {
                    new Asset
                    {
                        Id = replacementAssetId,
                        FileName = "replacement.png",
                        ContentType = "image/png",
                        Data = ByteString.CopyFrom(replacementBytes),
                        Sha256 = replacementDeclaration["sha256"]!.GetValue<string>(),
                    },
                },
            },
        });
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Contains("ppt/slides/slide1.xml", edited.PresentationProgram.ChangedParts);
        Assert.Contains("ppt/slides/_rels/slide1.xml.rels", edited.PresentationProgram.ChangedParts);
        Assert.Contains(edited.PresentationProgram.ChangedParts, path => path.StartsWith("ppt/media/", StringComparison.Ordinal));
        Assert.DoesNotContain(sourceImagePartPath, ZipPartPaths(edited.File.ToByteArray()), StringComparer.OrdinalIgnoreCase);

        using (var stream = new MemoryStream(edited.File.ToByteArray(), writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var slide = Assert.Single(package.PresentationPart!.SlideParts);
            var blip = slide.Slide!.CommonSlideData!.Background!.BackgroundProperties!
                .GetFirstChild<A.BlipFill>()!.GetFirstChild<A.Blip>()!;
            var outputRelationshipId = blip.Embed?.Value ?? throw new InvalidOperationException("Replaced background image relationship is missing.");
            Assert.NotEqual(sourceRelationshipId, outputRelationshipId);
            var replacementPart = Assert.IsType<ImagePart>(slide.GetPartById(outputRelationshipId));
            using var replacementStream = replacementPart.GetStream(FileMode.Open, FileAccess.Read);
            using var replacementMemory = new MemoryStream();
            replacementStream.CopyTo(replacementMemory);
            Assert.Equal(replacementBytes, replacementMemory.ToArray());
            Assert.Equal(44_000, blip.GetFirstChild<A.AlphaModulationFixed>()!.Amount!.Value);
        }

        var reprojected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = edited.File,
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "background-image-replacement/edited.pptx",
                AssetRootUri = "background-image-replacement/assets",
            },
        });
        Assert.True(reprojected.Ok, Diagnostics(reprojected));
        var output = JsonNode.Parse(reprojected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var outputBackground = output["pages"]![0]!["background"]!.AsObject();
        Assert.Equal("image", outputBackground["type"]!.GetValue<string>());
        var outputAsset = output["assets"]!.AsArray()
            .Select(asset => asset?.AsObject() ?? throw new InvalidOperationException("Reprojected asset declaration is null."))
            .Single(asset => asset["id"]!.GetValue<string>() == outputBackground["asset"]!.GetValue<string>());
        Assert.Equal(replacementHash, outputAsset["sha256"]!.GetValue<string>());
        Assert.Equal(0.44, outputBackground["opacity"]!.GetValue<double>(), precision: 6);
    }

    [Fact]
    public void LiteralCustomGeometryAuthorsImportsEditsAndValidates()
    {
        var request = ExportRequest();
        var shape = request.Artifact.Presentation.Slides[0].Elements[0].Shape;
        shape.Geometry = "custom";
        shape.TextRectangle = new PresentationCustomGeometryTextRectangle
        {
            LeftEmu = 228_600,
            TopEmu = 171_450,
            RightEmu = 1_485_900,
            BottomEmu = 914_400,
        };
        var path = new PresentationCustomGeometryPath
        {
            Width = 21_600,
            Height = 21_600,
            FillMode = PresentationCustomGeometryPath.Types.FillMode.Normal,
            Stroke = true,
            ExtrusionAllowed = false,
        };
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            MoveTo = new PresentationCustomGeometryPoint { X = 1_000, Y = 2_000 },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            LineTo = new PresentationCustomGeometryPoint { X = 20_000, Y = 2_000 },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            QuadraticBezierTo = new PresentationCustomGeometryQuadraticBezier
            {
                Control = new PresentationCustomGeometryPoint { X = 21_000, Y = 6_000 },
                End = new PresentationCustomGeometryPoint { X = 18_000, Y = 12_000 },
            },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            CubicBezierTo = new PresentationCustomGeometryCubicBezier
            {
                Control1 = new PresentationCustomGeometryPoint { X = 21_000, Y = 6_000 },
                Control2 = new PresentationCustomGeometryPoint { X = 18_000, Y = 19_000 },
                End = new PresentationCustomGeometryPoint { X = 10_800, Y = 20_000 },
            },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            ArcTo = new PresentationCustomGeometryArc
            {
                WidthRadius = 3_000,
                HeightRadius = 4_000,
                StartAngle = 5_400_000,
                SweepAngle = 21_600_000,
            },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand { Close = true });
        shape.CustomPaths.Add(path);
        var unfilledPath = path.Clone();
        unfilledPath.FillMode = PresentationCustomGeometryPath.Types.FillMode.None;
        unfilledPath.Stroke = false;
        unfilledPath.ExtrusionAllowed = true;
        shape.CustomPaths.Add(unfilledPath);
        var defaultPath = path.Clone();
        defaultPath.FillMode = PresentationCustomGeometryPath.Types.FillMode.Unspecified;
        defaultPath.ClearStroke();
        defaultPath.ClearExtrusionAllowed();
        shape.CustomPaths.Add(defaultPath);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var properties = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Shape>().Single().ShapeProperties!;
            Assert.Null(properties.GetFirstChild<A.PresetGeometry>());
            var geometry = properties.GetFirstChild<A.CustomGeometry>()!;
            Assert.Collection(geometry.GetFirstChild<A.ShapeGuideList>()!.Elements<A.ShapeGuide>(),
                guide =>
                {
                    Assert.Equal("officeKitTextLeft", guide.Name!.Value);
                    Assert.Equal($"*/ 228600 w {shape.WidthEmu}", guide.Formula!.Value);
                },
                guide =>
                {
                    Assert.Equal("officeKitTextTop", guide.Name!.Value);
                    Assert.Equal($"*/ 171450 h {shape.HeightEmu}", guide.Formula!.Value);
                },
                guide =>
                {
                    Assert.Equal("officeKitTextRight", guide.Name!.Value);
                    Assert.Equal($"*/ 1485900 w {shape.WidthEmu}", guide.Formula!.Value);
                },
                guide =>
                {
                    Assert.Equal("officeKitTextBottom", guide.Name!.Value);
                    Assert.Equal($"*/ 914400 h {shape.HeightEmu}", guide.Formula!.Value);
                });
            var textRectangle = geometry.GetFirstChild<A.Rectangle>()!;
            Assert.Equal("officeKitTextLeft", textRectangle.Left!.Value);
            Assert.Equal("officeKitTextTop", textRectangle.Top!.Value);
            Assert.Equal("officeKitTextRight", textRectangle.Right!.Value);
            Assert.Equal("officeKitTextBottom", textRectangle.Bottom!.Value);
            Assert.Collection(geometry.GetFirstChild<A.PathList>()!.Elements<A.Path>(),
                nativePath =>
                {
                    Assert.Equal(21_600U, nativePath.Width!.Value);
                    Assert.Equal(21_600U, nativePath.Height!.Value);
                    Assert.Equal(A.PathFillModeValues.Norm, nativePath.Fill!.Value);
                    Assert.True(nativePath.Stroke!.Value);
                    Assert.False(nativePath.ExtrusionOk!.Value);
                    Assert.Collection(nativePath.ChildElements,
                        command => Assert.IsType<A.MoveTo>(command),
                        command => Assert.IsType<A.LineTo>(command),
                        command => Assert.IsType<A.QuadraticBezierCurveTo>(command),
                        command => Assert.IsType<A.CubicBezierCurveTo>(command),
                        command =>
                        {
                            var arc = Assert.IsType<A.ArcTo>(command);
                            Assert.Equal("3000", arc.WidthRadius!.Value);
                            Assert.Equal("4000", arc.HeightRadius!.Value);
                            Assert.Equal("5400000", arc.StartAngle!.Value);
                            Assert.Equal("21600000", arc.SwingAngle!.Value);
                        },
                        command => Assert.IsType<A.CloseShapePath>(command));
                },
                nativePath =>
                {
                    Assert.Equal(A.PathFillModeValues.None, nativePath.Fill!.Value);
                    Assert.False(nativePath.Stroke!.Value);
                    Assert.True(nativePath.ExtrusionOk!.Value);
                },
                nativePath =>
                {
                    Assert.Null(nativePath.Fill);
                    Assert.Null(nativePath.Stroke);
                    Assert.Null(nativePath.ExtrusionOk);
                });
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedElement = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements);
        Assert.True(importedElement.Source.Editable);
        Assert.Equal("custom", importedElement.Shape.Geometry);
        Assert.Equal(228_600, importedElement.Shape.TextRectangle.LeftEmu);
        Assert.Equal(171_450, importedElement.Shape.TextRectangle.TopEmu);
        Assert.Equal(1_485_900, importedElement.Shape.TextRectangle.RightEmu);
        Assert.Equal(914_400, importedElement.Shape.TextRectangle.BottomEmu);
        Assert.Equal(3, importedElement.Shape.CustomPaths.Count);
        var importedPath = importedElement.Shape.CustomPaths[0];
        var importedUnfilledPath = importedElement.Shape.CustomPaths[1];
        var importedDefaultPath = importedElement.Shape.CustomPaths[2];
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.Normal, importedPath.FillMode);
        Assert.True(importedPath.HasStroke);
        Assert.True(importedPath.Stroke);
        Assert.True(importedPath.HasExtrusionAllowed);
        Assert.False(importedPath.ExtrusionAllowed);
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.None, importedUnfilledPath.FillMode);
        Assert.True(importedUnfilledPath.HasStroke);
        Assert.False(importedUnfilledPath.Stroke);
        Assert.True(importedUnfilledPath.HasExtrusionAllowed);
        Assert.True(importedUnfilledPath.ExtrusionAllowed);
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.Unspecified, importedDefaultPath.FillMode);
        Assert.False(importedDefaultPath.HasStroke);
        Assert.False(importedDefaultPath.HasExtrusionAllowed);
        Assert.Equal(6, importedPath.Commands.Count);
        Assert.Equal(20_000, importedPath.Commands[1].LineTo.X);
        Assert.Equal(21_000, importedPath.Commands[2].QuadraticBezierTo.Control.X);
        Assert.Equal(21_600_000, importedPath.Commands[4].ArcTo.SweepAngle);

        importedPath.Commands[2].QuadraticBezierTo.Control.X = 20_500;
        importedPath.Commands[4].ArcTo.SweepAngle = -10_800_000;
        importedPath.FillMode = PresentationCustomGeometryPath.Types.FillMode.None;
        importedPath.ClearStroke();
        importedPath.ExtrusionAllowed = true;
        importedUnfilledPath.FillMode = PresentationCustomGeometryPath.Types.FillMode.Normal;
        importedUnfilledPath.Stroke = true;
        importedUnfilledPath.ClearExtrusionAllowed();
        importedElement.Shape.TextRectangle.RightEmu = 1_524_000;
        importedElement.Shape.TextRectangle.BottomEmu = 952_500;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripPaths = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements).Shape.CustomPaths;
        var roundTripTextRectangle = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements).Shape.TextRectangle;
        Assert.Equal(1_524_000, roundTripTextRectangle.RightEmu);
        Assert.Equal(952_500, roundTripTextRectangle.BottomEmu);
        Assert.Equal(3, roundTripPaths.Count);
        var roundTripPath = roundTripPaths[0];
        Assert.Equal(20_500, roundTripPath.Commands[2].QuadraticBezierTo.Control.X);
        Assert.Equal(-10_800_000, roundTripPath.Commands[4].ArcTo.SweepAngle);
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.None, roundTripPath.FillMode);
        Assert.False(roundTripPath.HasStroke);
        Assert.True(roundTripPath.HasExtrusionAllowed);
        Assert.True(roundTripPath.ExtrusionAllowed);
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.Normal, roundTripPaths[1].FillMode);
        Assert.True(roundTripPaths[1].HasStroke);
        Assert.True(roundTripPaths[1].Stroke);
        Assert.False(roundTripPaths[1].HasExtrusionAllowed);
        Assert.Equal(PresentationCustomGeometryPath.Types.FillMode.Unspecified, roundTripPaths[2].FillMode);
        Assert.False(roundTripPaths[2].HasStroke);
        Assert.False(roundTripPaths[2].HasExtrusionAllowed);

        var shaded = Import(SetFirstCustomPathFill(authored.File.ToByteArray(), A.PathFillModeValues.Lighten));
        Assert.True(shaded.Ok, Diagnostics(shaded));
        var shadedElement = Assert.Single(Assert.Single(shaded.Artifact.Presentation.Slides).Elements);
        Assert.False(shadedElement.Source.Editable);
        Assert.Empty(shadedElement.Shape.CustomPaths);
        var preservedShaded = Export(shaded.Artifact);
        Assert.True(preservedShaded.Ok, Diagnostics(preservedShaded));
        using (var stream = new MemoryStream(preservedShaded.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Equal(A.PathFillModeValues.Lighten, package.PresentationPart!.SlideParts.Single().Slide!
                .Descendants<A.Path>().First().Fill!.Value);
        shadedElement.Name = "unsafe-shaded-edit";
        var rejectedShaded = Export(shaded.Artifact);
        Assert.False(rejectedShaded.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rejectedShaded.Diagnostics).Code);

        var missingPaths = ExportRequest();
        missingPaths.Artifact.Presentation.Slides[0].Elements[0].Shape.Geometry = "custom";
        var missingPathsResponse = Invoke(missingPaths);
        Assert.False(missingPathsResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(missingPathsResponse.Diagnostics).Code);

        var misplacedPaths = ExportRequest();
        misplacedPaths.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomPaths.Add(path.Clone());
        var misplacedPathsResponse = Invoke(misplacedPaths);
        Assert.False(misplacedPathsResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(misplacedPathsResponse.Diagnostics).Code);

        var misplacedTextRectangle = ExportRequest();
        misplacedTextRectangle.Artifact.Presentation.Slides[0].Elements[0].Shape.TextRectangle = shape.TextRectangle.Clone();
        var misplacedTextRectangleResponse = Invoke(misplacedTextRectangle);
        Assert.False(misplacedTextRectangleResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(misplacedTextRectangleResponse.Diagnostics).Code);

        var invertedTextRectangle = ExportRequest();
        var invertedTextRectangleShape = invertedTextRectangle.Artifact.Presentation.Slides[0].Elements[0].Shape;
        invertedTextRectangleShape.Geometry = "custom";
        invertedTextRectangleShape.CustomPaths.Add(path.Clone());
        invertedTextRectangleShape.TextRectangle = new PresentationCustomGeometryTextRectangle
        {
            LeftEmu = 100,
            TopEmu = 0,
            RightEmu = 100,
            BottomEmu = 100,
        };
        var invertedTextRectangleResponse = Invoke(invertedTextRectangle);
        Assert.False(invertedTextRectangleResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(invertedTextRectangleResponse.Diagnostics).Code);

        var arcWithoutCurrentPoint = ExportRequest();
        var arcWithoutCurrentPointShape = arcWithoutCurrentPoint.Artifact.Presentation.Slides[0].Elements[0].Shape;
        arcWithoutCurrentPointShape.Geometry = "custom";
        var arcWithoutCurrentPointPath = new PresentationCustomGeometryPath { Width = 21_600, Height = 21_600 };
        arcWithoutCurrentPointPath.Commands.Add(path.Commands[4].Clone());
        arcWithoutCurrentPointShape.CustomPaths.Add(arcWithoutCurrentPointPath);
        var arcWithoutCurrentPointResponse = Invoke(arcWithoutCurrentPoint);
        Assert.False(arcWithoutCurrentPointResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(arcWithoutCurrentPointResponse.Diagnostics).Code);

        var excessiveArc = ExportRequest();
        var excessiveArcShape = excessiveArc.Artifact.Presentation.Slides[0].Elements[0].Shape;
        excessiveArcShape.Geometry = "custom";
        var excessiveArcPath = path.Clone();
        excessiveArcPath.Commands[4].ArcTo.SweepAngle = 21_600_001;
        excessiveArcShape.CustomPaths.Add(excessiveArcPath);
        var excessiveArcResponse = Invoke(excessiveArc);
        Assert.False(excessiveArcResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(excessiveArcResponse.Diagnostics).Code);

        var unknownFill = ExportRequest();
        var unknownFillShape = unknownFill.Artifact.Presentation.Slides[0].Elements[0].Shape;
        unknownFillShape.Geometry = "custom";
        var unknownFillPath = path.Clone();
        unknownFillPath.FillMode = (PresentationCustomGeometryPath.Types.FillMode)99;
        unknownFillShape.CustomPaths.Add(unknownFillPath);
        var unknownFillResponse = Invoke(unknownFill);
        Assert.False(unknownFillResponse.Ok);
        Assert.Equal("invalid_presentation_geometry", Assert.Single(unknownFillResponse.Diagnostics).Code);
    }

    [Fact]
    public void ImportedCustomGeometryWithoutAdjustmentListRemainsEditable()
    {
        var request = ExportRequest();
        var authoredShape = request.Artifact.Presentation.Slides[0].Elements[0].Shape;
        authoredShape.Geometry = "custom";
        var authoredPath = new PresentationCustomGeometryPath { Width = 1_000, Height = 1_000 };
        authoredPath.Commands.Add(new PresentationCustomGeometryCommand
        {
            MoveTo = new PresentationCustomGeometryPoint { X = 0, Y = 0 },
        });
        authoredPath.Commands.Add(new PresentationCustomGeometryCommand
        {
            LineTo = new PresentationCustomGeometryPoint { X = 1_000, Y = 1_000 },
        });
        authoredPath.Commands.Add(new PresentationCustomGeometryCommand { Close = true });
        authoredShape.CustomPaths.Add(authoredPath);
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            new Regex("(?<prefix><a:custGeom\\b[^>]*>[\\s\\S]*?)<a:avLst\\b[^>]*/>(?<suffix>[\\s\\S]*?</a:custGeom>)")
                .Replace(xml, "${prefix}${suffix}", 1));
        using (var sourceStream = new MemoryStream(sourceBytes))
        using (var sourcePackage = PresentationDocument.Open(sourceStream, false))
            Assert.IsType<A.PathList>(sourcePackage.PresentationPart!.SlideParts.Single().Slide!
                .Descendants<A.CustomGeometry>().Single().FirstChild);

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var element = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements);
        Assert.True(element.Source.Editable);
        Assert.Equal("custom", element.Shape.Geometry);
        Assert.NotEmpty(element.Shape.CustomPaths);
        var noOp = Export(imported.Artifact);
        Assert.True(noOp.Ok, Diagnostics(noOp));
        Assert.Equal(sourceBytes, noOp.File.ToByteArray());

        element.Shape.LeftEmu += 100;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        using var stream = new MemoryStream(edited.File.ToByteArray());
        using var package = PresentationDocument.Open(stream, false);
        var geometry = package.PresentationPart!.SlideParts.Single().Slide!
            .Descendants<A.CustomGeometry>().Single();
        Assert.IsType<A.PathList>(geometry.FirstChild);
    }

