        {
            AngleReference = "cd2",
            XReference = "l",
            YReference = "vc",
        });
        shape.CustomAdjustmentHandles.Add(new PresentationCustomGeometryAdjustmentHandle
        {
            Xy = new PresentationCustomGeometryXyAdjustmentHandle
            {
                XAdjustment = "adjX",
                MinXReference = "l",
                MaxXReference = "r",
                YAdjustment = "adjY",
                MinYReference = "t",
                MaxYReference = "b",
                Position = new PresentationCustomGeometryPoint { XReference = "hc", YReference = "vc" },
            },
        });
        shape.CustomAdjustmentHandles.Add(new PresentationCustomGeometryAdjustmentHandle
        {
            Polar = new PresentationCustomGeometryPolarAdjustmentHandle
            {
                RadialAdjustment = "adjRadius",
                MinRadiusReference = "l",
                MaxRadiusReference = "ss",
                AngleAdjustment = "adjSweep",
                MinAngleReference = "t",
                MaxAngleReference = "cd2",
                Position = new PresentationCustomGeometryPoint { XReference = "r", YReference = "vc" },
            },
        });
        shape.CustomConnectionSites.Add(new PresentationCustomGeometryConnectionSite
        {
            AngleReference = "cd4",
            XReference = "r",
            YReference = "vc",
        });
        var path = new PresentationCustomGeometryPath();
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            MoveTo = new PresentationCustomGeometryPoint { XReference = "l", YReference = "vc" },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            LineTo = new PresentationCustomGeometryPoint { XReference = "hc", YReference = "t" },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand
        {
            ArcTo = new PresentationCustomGeometryArc
            {
                WidthRadiusReference = "wd4",
                HeightRadiusReference = "hd4",
                StartAngleReference = "3cd4",
                SweepAngleReference = "cd2",
            },
        });
        path.Commands.Add(new PresentationCustomGeometryCommand { Close = true });
        shape.CustomPaths.Add(path);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var geometry = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.CustomGeometry>().Single();
            Assert.Collection(geometry.GetFirstChild<A.AdjustValueList>()!.Elements<A.ShapeGuide>(),
                guide => Assert.Equal(("adjX", "val 25000"), (guide.Name!.Value, guide.Formula!.Value)),
                guide => Assert.Equal(("adjY", "val 50000"), (guide.Name!.Value, guide.Formula!.Value)),
                guide => Assert.Equal(("adjRadius", "val 250000"), (guide.Name!.Value, guide.Formula!.Value)),
                guide => Assert.Equal(("adjSweep", "val 10800000"), (guide.Name!.Value, guide.Formula!.Value)));
            var nativeGuides = geometry.GetFirstChild<A.ShapeGuideList>()!.Elements<A.ShapeGuide>().ToArray();
            Assert.Equal(18, nativeGuides.Length);
            Assert.Equal(("x1", "*/ w adjX 100000"), (nativeGuides[0].Name!.Value, nativeGuides[0].Formula!.Value));
            Assert.DoesNotContain(nativeGuides, guide => guide.Name?.Value?.StartsWith("officeKitText", StringComparison.Ordinal) == true);
            var textRectangle = geometry.GetFirstChild<A.Rectangle>()!;
            Assert.Equal(("x1", "t", "x2", "b"),
                (textRectangle.Left!.Value, textRectangle.Top!.Value, textRectangle.Right!.Value, textRectangle.Bottom!.Value));
            Assert.Collection(geometry.GetFirstChild<A.AdjustHandleList>()!.ChildElements,
                native =>
                {
                    var handle = Assert.IsType<A.AdjustHandleXY>(native);
                    Assert.Equal(("adjX", "l", "r"), (handle.XAdjustmentGuide!.Value, handle.MinX!.Value, handle.MaxX!.Value));
                    Assert.Equal(("adjY", "t", "b"), (handle.YAdjustmentGuide!.Value, handle.MinY!.Value, handle.MaxY!.Value));
                    Assert.Equal(("hc", "vc"), (handle.Position!.X!.Value, handle.Position.Y!.Value));
                },
                native =>
                {
                    var handle = Assert.IsType<A.AdjustHandlePolar>(native);
                    Assert.Equal(("adjRadius", "l", "ss"), (handle.RadialAdjustmentGuide!.Value, handle.MinRadial!.Value, handle.MaxRadial!.Value));
                    Assert.Equal(("adjSweep", "t", "cd2"), (handle.AngleAdjustmentGuide!.Value, handle.MinAngle!.Value, handle.MaxAngle!.Value));
                    Assert.Equal(("r", "vc"), (handle.Position!.X!.Value, handle.Position.Y!.Value));
                });
            Assert.Collection(geometry.GetFirstChild<A.ConnectionSiteList>()!.Elements<A.ConnectionSite>(),
                site =>
                {
                    Assert.Equal("cd2", site.Angle!.Value);
                    Assert.Equal(("l", "vc"), (site.Position!.X!.Value, site.Position.Y!.Value));
                },
                site =>
                {
                    Assert.Equal("cd4", site.Angle!.Value);
                    Assert.Equal(("r", "vc"), (site.Position!.X!.Value, site.Position.Y!.Value));
                });
            var nativePath = geometry.GetFirstChild<A.PathList>()!.Elements<A.Path>().Single();
            Assert.Null(nativePath.Width);
            Assert.Null(nativePath.Height);
            var move = Assert.IsType<A.MoveTo>(nativePath.ChildElements[0]);
            Assert.Equal("l", move.Point!.X!.Value);
            Assert.Equal("vc", move.Point.Y!.Value);
            var arc = Assert.IsType<A.ArcTo>(nativePath.ChildElements[2]);
            Assert.Equal("wd4", arc.WidthRadius!.Value);
            Assert.Equal("3cd4", arc.StartAngle!.Value);
            Assert.Equal("cd2", arc.SwingAngle!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedShape = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements).Shape;
        Assert.Equal(4, importedShape.CustomAdjustments.Count);
        Assert.Equal(18, importedShape.CustomGuides.Count);
        Assert.Equal(("x1", "t", "x2", "b"),
            (importedShape.TextRectangle.LeftReference, importedShape.TextRectangle.TopReference,
                importedShape.TextRectangle.RightReference, importedShape.TextRectangle.BottomReference));
        Assert.Collection(importedShape.CustomConnectionSites,
            site => Assert.Equal(("cd2", "l", "vc"), (site.AngleReference, site.XReference, site.YReference)),
            site => Assert.Equal(("cd4", "r", "vc"), (site.AngleReference, site.XReference, site.YReference)));
        Assert.Collection(importedShape.CustomAdjustmentHandles,
            entry =>
            {
                Assert.Equal(PresentationCustomGeometryAdjustmentHandle.HandleOneofCase.Xy, entry.HandleCase);
                Assert.Equal(("adjX", "l", "r", "adjY", "t", "b"),
                    (entry.Xy.XAdjustment, entry.Xy.MinXReference, entry.Xy.MaxXReference, entry.Xy.YAdjustment, entry.Xy.MinYReference, entry.Xy.MaxYReference));
                Assert.Equal(("hc", "vc"), (entry.Xy.Position.XReference, entry.Xy.Position.YReference));
            },
            entry =>
            {
                Assert.Equal(PresentationCustomGeometryAdjustmentHandle.HandleOneofCase.Polar, entry.HandleCase);
                Assert.Equal(("adjRadius", "l", "ss", "adjSweep", "t", "cd2"),
                    (entry.Polar.RadialAdjustment, entry.Polar.MinRadiusReference, entry.Polar.MaxRadiusReference, entry.Polar.AngleAdjustment, entry.Polar.MinAngleReference, entry.Polar.MaxAngleReference));
                Assert.Equal(("r", "vc"), (entry.Polar.Position.XReference, entry.Polar.Position.YReference));
            });
        Assert.Equal(0, importedShape.CustomPaths[0].Width);
        Assert.Equal(0, importedShape.CustomPaths[0].Height);
        Assert.Equal("l", importedShape.CustomPaths[0].Commands[0].MoveTo.XReference);
        Assert.Equal("wd4", importedShape.CustomPaths[0].Commands[2].ArcTo.WidthRadiusReference);
        importedShape.CustomAdjustments[0].Formula = "val 30000";
        importedShape.CustomConnectionSites[0].Angle60000 = 5_400_000;
        importedShape.CustomConnectionSites[0].ClearAngleReference();
        importedShape.CustomAdjustmentHandles[0].Xy.ClearMaxXReference();
        importedShape.CustomAdjustmentHandles[0].Xy.MaxX = 90_000;
        importedShape.CustomAdjustmentHandles[1].Polar.Position.XReference = "x1";
        importedShape.TextRectangle.ClearRightReference();
        importedShape.TextRectangle.RightEmu = shape.WidthEmu - 200_000;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTripShape = Assert.Single(Assert.Single(Import(edited.File.ToByteArray()).Artifact.Presentation.Slides).Elements).Shape;
        Assert.Equal("val 30000", roundTripShape.CustomAdjustments[0].Formula);
        Assert.Equal(5_400_000, roundTripShape.CustomConnectionSites[0].Angle60000);
        Assert.Equal(90_000, roundTripShape.CustomAdjustmentHandles[0].Xy.MaxX);
        Assert.Equal("x1", roundTripShape.CustomAdjustmentHandles[1].Polar.Position.XReference);
        Assert.Equal(0, roundTripShape.CustomPaths[0].Width);
        Assert.Equal(0, roundTripShape.CustomPaths[0].Height);
        Assert.Equal("l", roundTripShape.CustomPaths[0].Commands[0].MoveTo.XReference);
        Assert.Equal("x1", roundTripShape.TextRectangle.LeftReference);
        Assert.Equal("t", roundTripShape.TextRectangle.TopReference);
        Assert.Equal(shape.WidthEmu - 200_000, roundTripShape.TextRectangle.RightEmu);
        Assert.Equal("b", roundTripShape.TextRectangle.BottomReference);
        using (var stream = new MemoryStream(edited.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var geometry = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.CustomGeometry>().Single();
            var nativeRectangle = geometry.GetFirstChild<A.Rectangle>()!;
            Assert.Equal(("x1", "t", "officeKitTextRight", "b"),
                (nativeRectangle.Left!.Value, nativeRectangle.Top!.Value, nativeRectangle.Right!.Value, nativeRectangle.Bottom!.Value));
            Assert.Equal(22, geometry.GetFirstChild<A.ShapeGuideList>()!.Elements<A.ShapeGuide>().Count());
        }

        var changedConnectionSiteTopology = Import(authored.File.ToByteArray());
        changedConnectionSiteTopology.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomConnectionSites.RemoveAt(1);
        var changedConnectionSiteTopologyResponse = Export(changedConnectionSiteTopology.Artifact);
        Assert.False(changedConnectionSiteTopologyResponse.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(changedConnectionSiteTopologyResponse.Diagnostics).Code);

        var changedAdjustmentHandleTopology = Import(authored.File.ToByteArray());
        changedAdjustmentHandleTopology.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomAdjustmentHandles[0].Xy.XAdjustment = "adjY";
        var changedAdjustmentHandleTopologyResponse = Export(changedAdjustmentHandleTopology.Artifact);
        Assert.False(changedAdjustmentHandleTopologyResponse.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(changedAdjustmentHandleTopologyResponse.Diagnostics).Code);

        var emptyTopologyRequest = request.Clone();
        emptyTopologyRequest.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomConnectionSites.Clear();
        emptyTopologyRequest.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomAdjustmentHandles.Clear();
        var emptyTopologyAuthored = Invoke(emptyTopologyRequest);
        Assert.True(emptyTopologyAuthored.Ok, Diagnostics(emptyTopologyAuthored));
        var withEmptyTopology = emptyTopologyAuthored.File.ToByteArray();
        using (var stream = new MemoryStream())
        {
            stream.Write(withEmptyTopology);
            stream.Position = 0;
            using (var package = PresentationDocument.Open(stream, true))
            {
                var geometry = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.CustomGeometry>().Single();
                var guideList = geometry.GetFirstChild<A.ShapeGuideList>()!;
                var handles = geometry.InsertAfter(new A.AdjustHandleList(), guideList)!;
                geometry.InsertAfter(new A.ConnectionSiteList(), handles);
            }
            withEmptyTopology = stream.ToArray();
        }
        var importedEmptyTopology = Import(withEmptyTopology);
        Assert.True(importedEmptyTopology.Ok, Diagnostics(importedEmptyTopology));
        Assert.True(Assert.Single(Assert.Single(importedEmptyTopology.Artifact.Presentation.Slides).Elements).Source.Editable);

        byte[] malformedHandleSource;
        using (var stream = new MemoryStream())
        {
            stream.Write(authored.File.Span);
            stream.Position = 0;
            using (var package = PresentationDocument.Open(stream, true))
            {
                var handle = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.AdjustHandleXY>().Single();
                handle.SetAttribute(new OpenXmlAttribute("fixture", "opaque", "urn:office-kit:custom-handle", "kept"));
            }
            malformedHandleSource = stream.ToArray();
        }
        var malformedHandleImport = Import(malformedHandleSource);
        Assert.True(malformedHandleImport.Ok, Diagnostics(malformedHandleImport));
        var opaqueHandleElement = Assert.Single(Assert.Single(malformedHandleImport.Artifact.Presentation.Slides).Elements);
        Assert.False(opaqueHandleElement.Source.Editable);
        Assert.Empty(opaqueHandleElement.Shape.CustomAdjustmentHandles);
        var preservedMalformedHandle = Export(malformedHandleImport.Artifact);
        Assert.True(preservedMalformedHandle.Ok, Diagnostics(preservedMalformedHandle));
        using (var stream = new MemoryStream(preservedMalformedHandle.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var handle = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.AdjustHandleXY>().Single();
            Assert.Equal("kept", handle.GetAttribute("opaque", "urn:office-kit:custom-handle").Value);
        }

        var forwardReference = request.Clone();
        forwardReference.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomGuides[0].Formula = "val later";
        forwardReference.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomGuides.Add(
            new PresentationCustomGeometryGuide { Name = "later", Formula = "val 1" });
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(forwardReference).Diagnostics).Code);

        var reservedName = request.Clone();
        reservedName.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomGuides[0].Name = "officeKitCollision";
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(reservedName).Diagnostics).Code);

        var ambiguousCoordinate = request.Clone();
        ambiguousCoordinate.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomPaths[0].Commands[0].MoveTo.X = 1;
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(ambiguousCoordinate).Diagnostics).Code);

        var ambiguousConnectionSite = request.Clone();
        ambiguousConnectionSite.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomConnectionSites[0].XEmu = 1;
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(ambiguousConnectionSite).Diagnostics).Code);

        var ambiguousTextRectangle = request.Clone();
        ambiguousTextRectangle.Artifact.Presentation.Slides[0].Elements[0].Shape.TextRectangle.LeftEmu = 1;
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(ambiguousTextRectangle).Diagnostics).Code);

        var unknownTextRectangleGuide = request.Clone();
        unknownTextRectangleGuide.Artifact.Presentation.Slides[0].Elements[0].Shape.TextRectangle.RightReference = "missingRectGuide";
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(unknownTextRectangleGuide).Diagnostics).Code);

        var invertedTextRectangleGuides = request.Clone();
        invertedTextRectangleGuides.Artifact.Presentation.Slides[0].Elements[0].Shape.TextRectangle.LeftReference = "x2";
        invertedTextRectangleGuides.Artifact.Presentation.Slides[0].Elements[0].Shape.TextRectangle.RightReference = "x1";
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(invertedTextRectangleGuides).Diagnostics).Code);

        var outOfBoundsConnectionSite = request.Clone();
        var outOfBoundsSite = outOfBoundsConnectionSite.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomConnectionSites[0];
        outOfBoundsSite.ClearXReference();
        outOfBoundsSite.XEmu = shape.WidthEmu + 1;
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(outOfBoundsConnectionSite).Diagnostics).Code);

        var overBudgetConnectionSites = request.Clone();
        var overBudgetShape = overBudgetConnectionSites.Artifact.Presentation.Slides[0].Elements[0].Shape;
        overBudgetShape.CustomConnectionSites.Clear();
        for (var index = 0; index < 1_025; index++)
            overBudgetShape.CustomConnectionSites.Add(new PresentationCustomGeometryConnectionSite());
        Assert.Equal("presentation_item_budget_exceeded", Assert.Single(Invoke(overBudgetConnectionSites).Diagnostics).Code);

        var incompleteHandleRange = request.Clone();
        incompleteHandleRange.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomAdjustmentHandles[0].Xy.ClearMaxXReference();
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(incompleteHandleRange).Diagnostics).Code);

        var outOfRangeHandle = request.Clone();
        var outOfRangeXy = outOfRangeHandle.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomAdjustmentHandles[0].Xy;
        outOfRangeXy.ClearMaxXReference();
        outOfRangeXy.MaxX = 20_000;
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(outOfRangeHandle).Diagnostics).Code);

        var negativeUnboundedRadius = request.Clone();
        var negativeRadiusShape = negativeUnboundedRadius.Artifact.Presentation.Slides[0].Elements[0].Shape;
        negativeRadiusShape.CustomAdjustments[2].Formula = "val -1";
        negativeRadiusShape.CustomAdjustmentHandles[1].Polar.ClearMinRadiusReference();
        negativeRadiusShape.CustomAdjustmentHandles[1].Polar.ClearMaxRadiusReference();
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(negativeUnboundedRadius).Diagnostics).Code);

        var unboundedAngleBeyondTurn = request.Clone();
        var unboundedAngleShape = unboundedAngleBeyondTurn.Artifact.Presentation.Slides[0].Elements[0].Shape;
        unboundedAngleShape.CustomAdjustments[3].Formula = "val 21600001";
        unboundedAngleShape.CustomAdjustmentHandles[1].Polar.ClearMinAngleReference();
        unboundedAngleShape.CustomAdjustmentHandles[1].Polar.ClearMaxAngleReference();
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(unboundedAngleBeyondTurn).Diagnostics).Code);

        var overBudgetAdjustmentHandles = request.Clone();
        var overBudgetHandleShape = overBudgetAdjustmentHandles.Artifact.Presentation.Slides[0].Elements[0].Shape;
        overBudgetHandleShape.CustomAdjustmentHandles.Clear();
        for (var index = 0; index < 1_025; index++)
            overBudgetHandleShape.CustomAdjustmentHandles.Add(new PresentationCustomGeometryAdjustmentHandle());
        Assert.Equal("presentation_item_budget_exceeded", Assert.Single(Invoke(overBudgetAdjustmentHandles).Diagnostics).Code);

        var unknownCoordinate = request.Clone();
        unknownCoordinate.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomPaths[0].Commands[0].MoveTo.XReference = "missingGuide";
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(unknownCoordinate).Diagnostics).Code);

        var divisionByZero = request.Clone();
        divisionByZero.Artifact.Presentation.Slides[0].Elements[0].Shape.CustomGuides[0].Formula = "*/ w 1 0";
        Assert.Equal("invalid_presentation_geometry", Assert.Single(Invoke(divisionByZero).Diagnostics).Code);
    }

    [Fact]
    public void CoreShapesConnectorsAndLiteralChartsAuthorImportAndEdit()
    {
        var request = ExportRequest();
        var slide = request.Artifact.Presentation.Slides[0];
        var first = slide.Elements[0];
        first.Shape.Geometry = "roundRect";
        first.Shape.Shadow = new PresentationShadow
        {
            ColorRgb = "000000",
            BlurRadiusEmu = 38_100,
            DistanceEmu = 19_050,
            DirectionAngle60000 = 45 * 60_000,
            OpacityThousandthPercent = 20_000,
        };
        var second = new PresentationElement
        {
            Id = "presentation/slide/1/body",
            Name = "Body textbox",
            Shape = new PresentationShape
            {
                Geometry = "textbox",
                LeftEmu = 7_000_000,
                TopEmu = 1_300_000,
                WidthEmu = 3_000_000,
                HeightEmu = 800_000,
                Text = "Bounded textbox",
                FillRgb = "FFFFFF",
                LineRgb = "64748B",
                LineWidthEmu = 12_700,
            },
        };
        slide.Elements.Add(second);
        slide.Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/connector",
            Name = "Evidence flow",
            Connector = new PresentationConnector
            {
                ConnectorType = "elbow",
                StartXEmu = 2_000_000,
                StartYEmu = 1_200_000,
                EndXEmu = 8_000_000,
                EndYEmu = 1_700_000,
                LineRgb = "2563EB",
                LineWidthEmu = 25_400,
                StartArrow = "triangle",
                EndArrow = "triangle",
                StartTargetId = first.Id,
                EndTargetId = second.Id,
            },
        });
        foreach (var (type, index) in new[] { (SpreadsheetChartType.Bar, 0), (SpreadsheetChartType.Line, 1), (SpreadsheetChartType.Pie, 2) })
        {
            var chart = new PresentationChart
            {
                LeftEmu = 500_000 + index * 3_600_000L,
                TopEmu = 2_400_000,
                WidthEmu = 3_200_000,
                HeightEmu = 2_500_000,
                Type = type,
                Title = $"{type} evidence",
                HasLegend = true,
                DataLabels = new SpreadsheetChartDataLabelsArtifact { ShowValue = true, Position = SpreadsheetChartDataLabelPosition.Top },
            };
            chart.Categories.Add(["A", "B"]);
            chart.Series.Add(new SpreadsheetChartSeriesArtifact
            {
                Name = "Coverage",
                Fill = new SpreadsheetColor { Rgb = index == 0 ? "2563EB" : index == 1 ? "16A34A" : "F97316" },
                Line = type == SpreadsheetChartType.Line ? new SpreadsheetChartLineStyleArtifact { Color = new SpreadsheetColor { Rgb = "16A34A" }, DashStyle = SpreadsheetChartLineDashStyle.Solid, WidthPoints = 2 } : null,
                Marker = type == SpreadsheetChartType.Line ? new SpreadsheetChartMarkerArtifact { Symbol = SpreadsheetChartMarkerSymbol.Circle, Size = 6 } : null,
            });
            chart.Series[0].Values.Add([3, 5]);
            if (type == SpreadsheetChartType.Line)
            {
                chart.Series[0].Trendlines.Add(new SpreadsheetChartTrendlineArtifact
                {
                    Type = SpreadsheetChartTrendlineType.Linear,
                    Name = "Coverage projection",
                    Forward = 0.5,
                    DisplayEquation = true,
                    Line = new SpreadsheetChartLineStyleArtifact
                    {
                        Color = new SpreadsheetColor { Rgb = "7C3AED" },
                        DashStyle = SpreadsheetChartLineDashStyle.Dashed,
                        WidthPoints = 1.5,
                    },
                });
                chart.Series[0].ErrorBars = new SpreadsheetChartErrorBarsArtifact
                {
                    Direction = SpreadsheetChartErrorBarDirection.Y,
                    Type = SpreadsheetChartErrorBarType.Both,
                    ValueType = SpreadsheetChartErrorBarValueType.Percentage,
                    Value = 10,
                    NoEndCap = true,
                    Line = new SpreadsheetChartLineStyleArtifact
                    {
                        Color = new SpreadsheetColor { Rgb = "DC2626" },
                        DashStyle = SpreadsheetChartLineDashStyle.Dotted,
                        WidthPoints = 1.25,
                    },
                };
            }
            if (type != SpreadsheetChartType.Pie)
            {
                chart.XAxis = new SpreadsheetChartAxisArtifact { Title = "Category" };
                chart.YAxis = new SpreadsheetChartAxisArtifact { Title = "Score", Minimum = 0, Maximum = 10, MajorUnit = 2 };
            }
            slide.Elements.Add(new PresentationElement
            {
                Id = $"presentation/slide/1/chart/{index + 1}",
                Name = $"{type} chart",
                Chart = chart,
            });
        }

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var nativeSlide = package.PresentationPart!.SlideParts.Single().Slide!;
            Assert.Equal(2, nativeSlide.Descendants<P.Shape>().Count());
            Assert.Single(nativeSlide.Descendants<P.ConnectionShape>());
            Assert.Equal(3, nativeSlide.Descendants<C.ChartReference>().Count());
            Assert.Equal(3, package.PresentationPart.SlideParts.Single().ChartParts.Count());
            Assert.NotNull(nativeSlide.Descendants<A.OuterShadow>().Single());
            XNamespace c = "http://schemas.openxmlformats.org/drawingml/2006/chart";
            var trendlineXml = package.PresentationPart.SlideParts.Single().ChartParts
                .Select(part => XDocument.Load(part.GetStream(FileMode.Open, FileAccess.Read)))
                .Single(document => document.Descendants(c + "lineChart").Any());
            Assert.Equal("linear", trendlineXml.Descendants(c + "trendlineType").Single().Attribute("val")!.Value);
            Assert.Equal("0.5", trendlineXml.Descendants(c + "forward").Single().Attribute("val")!.Value);
            var nativeErrorBars = Assert.Single(trendlineXml.Descendants(c + "errBars"));
            Assert.Equal("percentage", nativeErrorBars.Element(c + "errValType")!.Attribute("val")!.Value);
            Assert.Equal("10", nativeErrorBars.Element(c + "val")!.Attribute("val")!.Value);
            Assert.Equal("1", nativeErrorBars.Element(c + "noEndCap")!.Attribute("val")!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var elements = Assert.Single(imported.Artifact.Presentation.Slides).Elements;
        Assert.Equal("roundRect", elements[0].Shape.Geometry);
        Assert.Equal("textbox", elements[1].Shape.Geometry);
        Assert.NotNull(elements[0].Shape.Shadow);
        var connector = Assert.Single(elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Connector);
        Assert.True(connector.Source.Editable);
        Assert.Equal(elements[0].Id, connector.Connector.StartTargetId);
        var charts = elements.Where(item => item.ContentCase == PresentationElement.ContentOneofCase.Chart).ToArray();
        Assert.Equal([SpreadsheetChartType.Bar, SpreadsheetChartType.Line, SpreadsheetChartType.Pie], charts.Select(item => item.Chart.Type));
        Assert.All(charts, item => Assert.True(item.Source.Editable));
        var importedTrendline = Assert.Single(charts[1].Chart.Series[0].Trendlines);
        Assert.Equal("Coverage projection", importedTrendline.Name);
        Assert.True(importedTrendline.DisplayEquation);
        var importedErrorBars = charts[1].Chart.Series[0].ErrorBars;
        Assert.Equal(SpreadsheetChartErrorBarValueType.Percentage, importedErrorBars.ValueType);
        Assert.Equal(10, importedErrorBars.Value);
        Assert.True(importedErrorBars.NoEndCap);
        Assert.Equal("DC2626", importedErrorBars.Line.Color.Rgb);

        elements[0].Shape.Shadow.OpacityThousandthPercent = 35_000;
        connector.Connector.EndArrow = string.Empty;
        charts[0].Chart.Title = "Edited evidence";
        charts[0].Chart.Series[0].Values[1] = 8;
        importedTrendline.Name = "Edited coverage projection";
        importedTrendline.Forward = 1.5;
        importedTrendline.DisplayRSquared = true;
        importedErrorBars.Value = 15;
        importedErrorBars.NoEndCap = false;
        importedErrorBars.Line.Color.Rgb = "EA580C";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripElements = Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements;
        Assert.Equal(35_000U, roundTripElements[0].Shape.Shadow.OpacityThousandthPercent);
        Assert.Equal(string.Empty, Assert.Single(roundTripElements, item => item.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector.EndArrow);
        var roundTripChart = roundTripElements.First(item => item.ContentCase == PresentationElement.ContentOneofCase.Chart).Chart;
        Assert.Equal("Edited evidence", roundTripChart.Title);
        Assert.Equal(8, roundTripChart.Series[0].Values[1]);
        var roundTripLine = roundTripElements.Where(item => item.ContentCase == PresentationElement.ContentOneofCase.Chart).Single(item => item.Chart.Type == SpreadsheetChartType.Line).Chart;
        var roundTripTrendline = Assert.Single(roundTripLine.Series[0].Trendlines);
        Assert.Equal("Edited coverage projection", roundTripTrendline.Name);
        Assert.Equal(1.5, roundTripTrendline.Forward);
        Assert.True(roundTripTrendline.DisplayRSquared);
        Assert.Equal(15, roundTripLine.Series[0].ErrorBars.Value);
        Assert.False(roundTripLine.Series[0].ErrorBars.NoEndCap);
        Assert.Equal("EA580C", roundTripLine.Series[0].ErrorBars.Line.Color.Rgb);

        var removedErrorBars = Import(edited.File.ToByteArray());
        removedErrorBars.Artifact.Presentation.Slides[0].Elements
            .Single(item => item.ContentCase == PresentationElement.ContentOneofCase.Chart && item.Chart.Type == SpreadsheetChartType.Line)
            .Chart.Series[0].ErrorBars = null;
        var rejectedErrorBarTopology = Export(removedErrorBars.Artifact);
        Assert.False(rejectedErrorBarTopology.Ok);
        Assert.Equal("presentation_chart_topology_changed", Assert.Single(rejectedErrorBarTopology.Diagnostics).Code);
    }

    [Fact]
    public void FreePositionedLinesAuthorImportEditAndFailClosed()
    {
        var request = ExportRequest();
        var slide = request.Artifact.Presentation.Slides[0];
        slide.Elements.Clear();
        var profiles = new[]
        {
            (Id: "horizontal", Width: 4_000_000L, Height: 0L, Style: "dashed", Rgb: "2563EB"),
            (Id: "vertical", Width: 0L, Height: 2_000_000L, Style: "dotted", Rgb: "16A34A"),
            (Id: "diagonal", Width: 2_400_000L, Height: 1_300_000L, Style: "dash-dot", Rgb: "F97316"),
            (Id: "evidence", Width: 2_400_000L, Height: 900_000L, Style: "dash-dot-dot", Rgb: "7C3AED"),
            (Id: "hidden", Width: 1_800_000L, Height: 0L, Style: "none", Rgb: ""),
        };
        for (var index = 0; index < profiles.Length; index++)
        {
            var profile = profiles[index];
            slide.Elements.Add(new PresentationElement
            {
                Id = $"presentation/slide/1/line/{profile.Id}",
                Name = $"{profile.Id} free line",
                Shape = new PresentationShape
                {
                    Geometry = "line",
                    LeftEmu = 400_000 + index * 600_000L,
                    TopEmu = 500_000 + index * 700_000L,
                    WidthEmu = profile.Width,
                    HeightEmu = profile.Height,
                    FillRgb = string.Empty,
                    LineRgb = profile.Rgb,
                    LineWidthEmu = 25_400,
                    LineStyle = profile.Style,
                },
            });
        }
        var decoratedLine = slide.Elements[0].Shape;
        decoratedLine.StartArrow = "oval";
        decoratedLine.StartArrowWidth = "sm";
        decoratedLine.StartArrowLength = "med";
        decoratedLine.EndArrow = "arrow";
        decoratedLine.EndArrowWidth = "lg";
        decoratedLine.EndArrowLength = "sm";
        decoratedLine.LineCap = "round";
        decoratedLine.LineJoin = "bevel";

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var nativeSlide = package.PresentationPart!.SlideParts.Single().Slide!;
            Assert.Empty(nativeSlide.Descendants<P.ConnectionShape>());
            var lines = nativeSlide.Descendants<P.Shape>().ToArray();
            Assert.Equal(5, lines.Length);
            Assert.All(lines, line => Assert.Equal(A.ShapeTypeValues.Line,
                line.ShapeProperties!.GetFirstChild<A.PresetGeometry>()!.Preset!.Value));
            Assert.Equal(0L, lines[0].ShapeProperties!.Transform2D!.Extents!.Cy!.Value);
            Assert.Equal(0L, lines[1].ShapeProperties!.Transform2D!.Extents!.Cx!.Value);
            Assert.Equal(A.PresetLineDashValues.Dash, lines[0].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>()!.Val!.Value);
            var decoratedOutline = lines[0].ShapeProperties!.GetFirstChild<A.Outline>()!;
            Assert.Equal(A.LineCapValues.Round, decoratedOutline.CapType!.Value);
            Assert.NotNull(decoratedOutline.GetFirstChild<A.LineJoinBevel>());
            var decoratedHead = decoratedOutline.GetFirstChild<A.HeadEnd>()!;
            Assert.Equal(A.LineEndValues.Oval, decoratedHead.Type!.Value);
            Assert.Equal(A.LineEndWidthValues.Small, decoratedHead.Width!.Value);
            Assert.Equal(A.LineEndLengthValues.Medium, decoratedHead.Length!.Value);
            var decoratedTail = decoratedOutline.GetFirstChild<A.TailEnd>()!;
            Assert.Equal(A.LineEndValues.Arrow, decoratedTail.Type!.Value);
            Assert.Equal(A.LineEndWidthValues.Large, decoratedTail.Width!.Value);
            Assert.Equal(A.LineEndLengthValues.Small, decoratedTail.Length!.Value);
            Assert.Equal(A.PresetLineDashValues.Dot, lines[1].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>()!.Val!.Value);
            Assert.Equal(A.PresetLineDashValues.DashDot, lines[2].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>()!.Val!.Value);
            Assert.Equal(A.PresetLineDashValues.LargeDashDotDot, lines[3].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>()!.Val!.Value);
            Assert.NotNull(lines[4].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.NoFill>());
            Assert.Null(lines[4].ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>());
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedLines = Assert.Single(imported.Artifact.Presentation.Slides).Elements;
        Assert.Equal(5, importedLines.Count);
        Assert.All(importedLines, element =>
        {
            Assert.Equal(PresentationElement.ContentOneofCase.Shape, element.ContentCase);
            Assert.True(element.Source.Editable);
            Assert.Equal("line", element.Shape.Geometry);
        });
        Assert.Equal(profiles.Select(profile => profile.Style), importedLines.Select(element => element.Shape.LineStyle));
        Assert.Equal("oval", importedLines[0].Shape.StartArrow);
        Assert.Equal("sm", importedLines[0].Shape.StartArrowWidth);
        Assert.Equal("med", importedLines[0].Shape.StartArrowLength);
        Assert.Equal("arrow", importedLines[0].Shape.EndArrow);
        Assert.Equal("lg", importedLines[0].Shape.EndArrowWidth);
        Assert.Equal("sm", importedLines[0].Shape.EndArrowLength);
        Assert.Equal("round", importedLines[0].Shape.LineCap);
        Assert.Equal("bevel", importedLines[0].Shape.LineJoin);

        // Imported separator rules are often placed a few points outside the
        // canvas.  Keep that source-bound line editable without widening the
        // negative-frame exception to ordinary shapes.
        var negativeLineSource = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
        {
            var updated = new Regex("<a:off\\s+x=\"400000\"[^>]*/>", RegexOptions.CultureInvariant)
                .Replace(xml, match => match.Value.Replace("x=\"400000\"", "x=\"-591436\"", StringComparison.Ordinal), 1);
            Assert.NotEqual(xml, updated);
            return updated;
        });
        var negativeLineImport = Import(negativeLineSource);
        Assert.True(negativeLineImport.Ok, Diagnostics(negativeLineImport));
        var negativeLine = Assert.Single(negativeLineImport.Artifact.Presentation.Slides).Elements[0];
        Assert.True(negativeLine.Source.Editable);
        Assert.Equal(-591_436, negativeLine.Shape.LeftEmu);
        negativeLine.Shape.LeftEmu = -500_000;
        var negativeLineEdited = Export(negativeLineImport.Artifact);
        Assert.True(negativeLineEdited.Ok, Diagnostics(negativeLineEdited));
        var negativeLineRoundTrip = Import(negativeLineEdited.File.ToByteArray());
        Assert.True(negativeLineRoundTrip.Ok, Diagnostics(negativeLineRoundTrip));
        Assert.Equal(-500_000, Assert.Single(negativeLineRoundTrip.Artifact.Presentation.Slides).Elements[0].Shape.LeftEmu);

        var originalSlideXml = ZipBytes(authored.File.ToByteArray(), "ppt/slides/slide1.xml");
        var unchanged = Export(imported.Artifact);
        Assert.True(unchanged.Ok, Diagnostics(unchanged));
        Assert.Equal(originalSlideXml, ZipBytes(unchanged.File.ToByteArray(), "ppt/slides/slide1.xml"));

        var editedLine = importedLines[0].Shape;
        editedLine.HeightEmu = 450_000;
        editedLine.LineRgb = "0F172A";
        editedLine.LineStyle = "dotted";
        editedLine.StartArrow = "diamond";
        editedLine.StartArrowWidth = "lg";
        editedLine.StartArrowLength = "lg";
        editedLine.EndArrow = "stealth";
        editedLine.EndArrowWidth = "sm";
        editedLine.EndArrowLength = "med";
        editedLine.LineCap = "square";
        editedLine.LineJoin = "miter";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var reimported = Import(edited.File.ToByteArray());
        Assert.True(reimported.Ok, Diagnostics(reimported));
        var roundTrip = Assert.Single(reimported.Artifact.Presentation.Slides).Elements[0].Shape;
        Assert.Equal("line", roundTrip.Geometry);
        Assert.Equal(450_000, roundTrip.HeightEmu);
        Assert.Equal("0F172A", roundTrip.LineRgb);
        Assert.Equal("dotted", roundTrip.LineStyle);
        Assert.Equal("diamond", roundTrip.StartArrow);
        Assert.Equal("lg", roundTrip.StartArrowWidth);
        Assert.Equal("lg", roundTrip.StartArrowLength);
        Assert.Equal("stealth", roundTrip.EndArrow);
        Assert.Equal("sm", roundTrip.EndArrowWidth);
        Assert.Equal("med", roundTrip.EndArrowLength);
        Assert.Equal("square", roundTrip.LineCap);
        Assert.Equal("miter", roundTrip.LineJoin);

        var zeroExtent = request.Clone();
        zeroExtent.Artifact.Presentation.Slides[0].Elements[0].Shape.WidthEmu = 0;
        zeroExtent.Artifact.Presentation.Slides[0].Elements[0].Shape.HeightEmu = 0;
        Assert.Equal("invalid_presentation_frame", Assert.Single(Invoke(zeroExtent).Diagnostics).Code);

        var unknownStyle = request.Clone();
        unknownStyle.Artifact.Presentation.Slides[0].Elements[0].Shape.LineStyle = "long-dash";
        Assert.Equal("unsupported_presentation_line", Assert.Single(Invoke(unknownStyle).Diagnostics).Code);

        var inconsistentNone = request.Clone();
        inconsistentNone.Artifact.Presentation.Slides[0].Elements[0].Shape.LineStyle = "none";
        Assert.Equal("invalid_presentation_line", Assert.Single(Invoke(inconsistentNone).Diagnostics).Code);

        var incompleteLineEnd = request.Clone();
        incompleteLineEnd.Artifact.Presentation.Slides[0].Elements[1].Shape.StartArrowWidth = "lg";
        Assert.Equal("invalid_presentation_line", Assert.Single(Invoke(incompleteLineEnd).Diagnostics).Code);

        var invalidCap = request.Clone();
        invalidCap.Artifact.Presentation.Slides[0].Elements[0].Shape.LineCap = "projecting";
        Assert.Equal("unsupported_presentation_line", Assert.Single(Invoke(invalidCap).Diagnostics).Code);

        var nonLineArrow = request.Clone();
        nonLineArrow.Artifact.Presentation.Slides[0].Elements[0].Shape.Geometry = "rect";
        nonLineArrow.Artifact.Presentation.Slides[0].Elements[0].Shape.HeightEmu = 500_000;
        Assert.Equal("unsupported_presentation_line", Assert.Single(Invoke(nonLineArrow).Diagnostics).Code);

        using var unsupportedStream = new MemoryStream();
        unsupportedStream.Write(authored.File.Span);
        unsupportedStream.Position = 0;
        using (var package = PresentationDocument.Open(unsupportedStream, true, new OpenSettings { AutoSave = true }))
        {
            package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Shape>().First()
                .ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.PresetDash>()!.Val = A.PresetLineDashValues.LargeDash;
        }
        var unsupportedBytes = unsupportedStream.ToArray();
        var unsupportedImport = Import(unsupportedBytes);
        Assert.True(unsupportedImport.Ok, Diagnostics(unsupportedImport));
        var sourceBound = Assert.Single(unsupportedImport.Artifact.Presentation.Slides).Elements[0];
        Assert.Equal(PresentationElement.ContentOneofCase.Shape, sourceBound.ContentCase);
        Assert.False(sourceBound.Source.Editable);
        var preserved = Export(unsupportedImport.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Equal(ZipBytes(unsupportedBytes, "ppt/slides/slide1.xml"), ZipBytes(preserved.File.ToByteArray(), "ppt/slides/slide1.xml"));
        sourceBound.Name = "Forbidden mutation";
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(unsupportedImport.Artifact).Diagnostics).Code);

        using var unspecifiedFillStream = new MemoryStream();
        unspecifiedFillStream.Write(authored.File.Span);
        unspecifiedFillStream.Position = 0;
        using (var package = PresentationDocument.Open(unspecifiedFillStream, true, new OpenSettings { AutoSave = true }))
        {
            package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Shape>().First()
                .ShapeProperties!.GetFirstChild<A.Outline>()!.RemoveAllChildren();
        }
        var unspecifiedFillBytes = unspecifiedFillStream.ToArray();
        var unspecifiedFillImport = Import(unspecifiedFillBytes);
        Assert.True(unspecifiedFillImport.Ok, Diagnostics(unspecifiedFillImport));
        var unspecifiedFillShape = Assert.Single(unspecifiedFillImport.Artifact.Presentation.Slides).Elements[0];
        Assert.False(unspecifiedFillShape.Source.Editable);
        var unspecifiedFillPreserved = Export(unspecifiedFillImport.Artifact);
        Assert.True(unspecifiedFillPreserved.Ok, Diagnostics(unspecifiedFillPreserved));
        Assert.Equal(
            ZipBytes(unspecifiedFillBytes, "ppt/slides/slide1.xml"),
            ZipBytes(unspecifiedFillPreserved.File.ToByteArray(), "ppt/slides/slide1.xml"));
        unspecifiedFillShape.Name = "Forbidden unspecified-fill mutation";
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(unspecifiedFillImport.Artifact).Diagnostics).Code);
    }

    [Fact]
    public void ConnectorConnectionSitesAndLineProfileRoundTripAndFailClosed()
    {
        var request = ExportRequest();
        var slide = request.Artifact.Presentation.Slides[0];
        var source = slide.Elements[0];
        var target = new PresentationElement
        {
            Id = "presentation/slide/1/connector-target",
            Name = "Ellipse target",
            Shape = new PresentationShape
            {
                Geometry = "ellipse",
                LeftEmu = 7_000_000,
                TopEmu = 1_200_000,
                WidthEmu = 2_000_000,
                HeightEmu = 1_000_000,
                Text = "Target",
                FillRgb = "FFFFFF",
                LineRgb = "64748B",
                LineWidthEmu = 12_700,
            },
        };
        slide.Elements.Add(target);
        slide.Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/site-connector",
            Name = "Curved evidence route",
            Connector = new PresentationConnector
            {
                ConnectorType = "curved",
                StartXEmu = 8_763_000,
                StartYEmu = 714_375,
                EndXEmu = 7_000_000,
                EndYEmu = 1_700_000,
                LineRgb = "2563EB",
                LineWidthEmu = 31_750,
                StartArrow = "arrow",
                EndArrow = "diamond",
                StartTargetId = source.Id,
                EndTargetId = target.Id,
                StartConnectionSiteIndex = 3,
                EndConnectionSiteIndex = 2,
                LineStyle = "dash-dot",
                StartArrowWidth = "lg",
                StartArrowLength = "sm",
                EndArrowWidth = "sm",
                EndArrowLength = "lg",
                LineCap = "round",
                LineJoin = "bevel",
            },
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var nativeConnector = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.ConnectionShape>().Single();
            var nativeConnections = nativeConnector.NonVisualConnectionShapeProperties!.NonVisualConnectorShapeDrawingProperties!;
            Assert.Equal(3U, nativeConnections.GetFirstChild<A.StartConnection>()!.Index!.Value);
            Assert.Equal(2U, nativeConnections.GetFirstChild<A.EndConnection>()!.Index!.Value);
            Assert.Equal(A.ShapeTypeValues.CurvedConnector3, nativeConnector.ShapeProperties!.GetFirstChild<A.PresetGeometry>()!.Preset!.Value);
            var outline = nativeConnector.ShapeProperties.GetFirstChild<A.Outline>()!;
            Assert.Equal(A.PresetLineDashValues.DashDot, outline.GetFirstChild<A.PresetDash>()!.Val!.Value);
            Assert.Equal(A.LineCapValues.Round, outline.CapType!.Value);
            Assert.NotNull(outline.GetFirstChild<A.LineJoinBevel>());
            var head = outline.GetFirstChild<A.HeadEnd>()!;
            Assert.Equal(A.LineEndValues.Arrow, head.Type!.Value);
            Assert.Equal(A.LineEndWidthValues.Large, head.Width!.Value);
            Assert.Equal(A.LineEndLengthValues.Small, head.Length!.Value);
            var tail = outline.GetFirstChild<A.TailEnd>()!;
            Assert.Equal(A.LineEndValues.Diamond, tail.Type!.Value);
            Assert.Equal(A.LineEndWidthValues.Small, tail.Width!.Value);
            Assert.Equal(A.LineEndLengthValues.Large, tail.Length!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedConnector = Assert.Single(
            Assert.Single(imported.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector;
        Assert.Equal("curved", importedConnector.ConnectorType);
        Assert.Equal(3U, importedConnector.StartConnectionSiteIndex);
        Assert.Equal(2U, importedConnector.EndConnectionSiteIndex);
        Assert.Equal("dash-dot", importedConnector.LineStyle);
        Assert.Equal("arrow", importedConnector.StartArrow);
        Assert.Equal("lg", importedConnector.StartArrowWidth);
        Assert.Equal("sm", importedConnector.StartArrowLength);
        Assert.Equal("diamond", importedConnector.EndArrow);
        Assert.Equal("sm", importedConnector.EndArrowWidth);
        Assert.Equal("lg", importedConnector.EndArrowLength);
        Assert.Equal("round", importedConnector.LineCap);
        Assert.Equal("bevel", importedConnector.LineJoin);

        var themedRequest = request.Clone();
        var themedConnector = themedRequest.Artifact.Presentation.Slides[0].Elements
            .Single(element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector;
        themedConnector.LineRgb = string.Empty;
        themedConnector.LineScheme = "accent1";
        var themed = Invoke(themedRequest);
        Assert.True(themed.Ok, Diagnostics(themed));
        using (var stream = new MemoryStream(themed.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var themedNativeConnector = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.ConnectionShape>().Single();
            var themedSolid = themedNativeConnector.ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.SolidFill>()!;
            Assert.Equal(A.SchemeColorValues.Accent1, themedSolid.GetFirstChild<A.SchemeColor>()!.Val!.Value);
        }
        var themedImported = Import(themed.File.ToByteArray());
        Assert.True(themedImported.Ok, Diagnostics(themedImported));
        var themedRoundTripConnector = Assert.Single(
            Assert.Single(themedImported.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector;
        Assert.Equal("accent1", themedRoundTripConnector.LineScheme);
        Assert.Empty(themedRoundTripConnector.LineRgb);

        importedConnector.LineStyle = "none";
        importedConnector.LineRgb = string.Empty;
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        using (var stream = new MemoryStream(edited.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            Assert.NotNull(package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.ConnectionShape>().Single()
                .ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.NoFill>());
        }
        var editedRoundTrip = Import(edited.File.ToByteArray());
        Assert.True(editedRoundTrip.Ok, Diagnostics(editedRoundTrip));
        Assert.Equal("none", Assert.Single(
            Assert.Single(editedRoundTrip.Artifact.Presentation.Slides).Elements,
            element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector.LineStyle);

        var invalidEndpoint = request.Clone();
        var invalidEndpointConnector = invalidEndpoint.Artifact.Presentation.Slides[0].Elements
            .Single(element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector;
        invalidEndpointConnector.StartTargetId = string.Empty;
        Assert.Equal("invalid_presentation_connector", Assert.Single(Invoke(invalidEndpoint).Diagnostics).Code);

        var unsupportedLine = request.Clone();
        unsupportedLine.Artifact.Presentation.Slides[0].Elements
            .Single(element => element.ContentCase == PresentationElement.ContentOneofCase.Connector).Connector.LineStyle = "long-dash";
        Assert.Equal("unsupported_presentation_connector", Assert.Single(Invoke(unsupportedLine).Diagnostics).Code);

        using var malformedStream = new MemoryStream();
        malformedStream.Write(authored.File.Span);
        malformedStream.Position = 0;
        using (var package = PresentationDocument.Open(malformedStream, true, new OpenSettings { AutoSave = true }))
        {
            var start = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.StartConnection>().Single();
            start.Index = null;
        }
        var malformedImport = Import(malformedStream.ToArray());
        Assert.True(malformedImport.Ok, Diagnostics(malformedImport));
        var malformedElements = Assert.Single(malformedImport.Artifact.Presentation.Slides).Elements;
        Assert.DoesNotContain(malformedElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Connector);
        Assert.Contains(malformedElements, element => element.ContentCase == PresentationElement.ContentOneofCase.Opaque);
    }

    [Fact]
    public void LiteralAreaDoughnutScatterBubbleAndRadarChartsAuthorImportAndEdit()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Elements.Clear();

        PresentationChart CategoryChart(SpreadsheetChartType type, string title, long left)
        {
            var chart = new PresentationChart
            {
                LeftEmu = left,
                TopEmu = 700_000,
                WidthEmu = 3_400_000,
                HeightEmu = 2_600_000,
                Type = type,
                Title = title,
                HasLegend = true,
            };
            chart.Categories.Add(["North", "Central", "South"]);
            chart.Series.Add(new SpreadsheetChartSeriesArtifact
            {
                Name = "Share",
                Fill = new SpreadsheetColor { Rgb = "0EA5E9" },
                Line = new SpreadsheetChartLineStyleArtifact { Color = new SpreadsheetColor { Rgb = "0369A1" }, DashStyle = SpreadsheetChartLineDashStyle.Solid, WidthPoints = 1.5 },
            });
            chart.Series[0].Values.Add([42, 31, 27]);
            if (type == SpreadsheetChartType.Doughnut)
                chart.DataLabels = new SpreadsheetChartDataLabelsArtifact { ShowCategoryName = true, ShowPercent = true, Position = SpreadsheetChartDataLabelPosition.OutsideEnd };
            else
            {
                chart.XAxis = new SpreadsheetChartAxisArtifact { Title = "Region" };
                chart.YAxis = new SpreadsheetChartAxisArtifact { Title = "Index", Minimum = 0, Maximum = 50, MajorUnit = 10 };
            }
            return chart;
        }

        PresentationChart NumericChart(SpreadsheetChartType type, string title, long left)
        {
            var chart = new PresentationChart
            {
                LeftEmu = left,
                TopEmu = 3_600_000,
                WidthEmu = 3_400_000,
                HeightEmu = 2_600_000,
                Type = type,
                Title = title,
                HasLegend = true,
                XAxis = new SpreadsheetChartAxisArtifact { Title = "Reach", Minimum = 0, Maximum = 40, MajorUnit = 10 },
                YAxis = new SpreadsheetChartAxisArtifact { Title = "Return", Minimum = 0, Maximum = 100, MajorUnit = 20 },
            };
            chart.Series.Add(new SpreadsheetChartSeriesArtifact
            {
                Name = "Portfolio",
                Fill = new SpreadsheetColor { Rgb = "8B5CF6" },
                Marker = type == SpreadsheetChartType.Scatter ? new SpreadsheetChartMarkerArtifact { Symbol = SpreadsheetChartMarkerSymbol.Diamond, Size = 7, Fill = new SpreadsheetColor { Rgb = "8B5CF6" } } : null,
                Line = type == SpreadsheetChartType.Bubble ? new SpreadsheetChartLineStyleArtifact { Color = new SpreadsheetColor { Rgb = "6D28D9" }, DashStyle = SpreadsheetChartLineDashStyle.Solid, WidthPoints = 1 } : null,
            });
            chart.Series[0].XValues.Add([10, 20, 34]);
            chart.Series[0].Values.Add([35, 68, 84]);
            if (type == SpreadsheetChartType.Bubble) chart.Series[0].BubbleSizes.Add([4, 9, 16]);
            return chart;
        }

        var charts = new[]
        {
            CategoryChart(SpreadsheetChartType.Area, "Regional trajectory", 500_000),
            CategoryChart(SpreadsheetChartType.Doughnut, "Regional mix", 4_100_000),
            NumericChart(SpreadsheetChartType.Scatter, "Reach relationship", 500_000),
            NumericChart(SpreadsheetChartType.Bubble, "Opportunity map", 4_100_000),
            CategoryChart(SpreadsheetChartType.Radar, "Risk profile", 7_700_000),
        };
        for (var index = 0; index < charts.Length; index++)
        {
            request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
            {
                Id = $"presentation/slide/1/chart/family-{index + 1}",
                Name = $"{charts[index].Type} chart",
                Chart = charts[index],
            });
        }

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var documents = package.PresentationPart!.SlideParts.Single().ChartParts
                .Select(part => XDocument.Load(part.GetStream(FileMode.Open, FileAccess.Read)))
                .ToArray();
            XNamespace c = "http://schemas.openxmlformats.org/drawingml/2006/chart";
            Assert.Single(documents, document => document.Descendants(c + "areaChart").Any());
            var doughnut = Assert.Single(documents, document => document.Descendants(c + "doughnutChart").Any());
            Assert.Equal("50", doughnut.Descendants(c + "holeSize").Single().Attribute("val")!.Value);
            Assert.Equal("1", doughnut.Descendants(c + "showPercent").Single().Attribute("val")!.Value);
            var scatter = Assert.Single(documents, document => document.Descendants(c + "scatterChart").Any());
            Assert.Equal("marker", scatter.Descendants(c + "scatterStyle").Single().Attribute("val")!.Value);
            Assert.Equal(2, scatter.Descendants(c + "valAx").Count());
            var bubble = Assert.Single(documents, document => document.Descendants(c + "bubbleChart").Any());
            Assert.Single(bubble.Descendants(c + "bubbleSize"));
            Assert.Equal("area", bubble.Descendants(c + "sizeRepresents").Single().Attribute("val")!.Value);
            var radar = Assert.Single(documents, document => document.Descendants(c + "radarChart").Any());
            Assert.Equal("standard", radar.Descendants(c + "radarStyle").Single().Attribute("val")!.Value);
            Assert.Equal("0", radar.Descendants(c + "varyColors").Single().Attribute("val")!.Value);
            Assert.Equal(2, radar.Descendants(c + "radarChart").Single().Elements(c + "axId").Count());
        }

        var imported = Import(authored.File.ToByteArray());
