    [Fact]
    public void OrdinaryShapeTransformAuthorsImportsEditsAndClearsWithPresence()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Elements[0].Shape.Transform = new PresentationShapeTransform
        {
            RotationAngle60000 = 5 * 60_000,
            FlipHorizontal = false,
            FlipVertical = true,
        };

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var presentation = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(presentation));
            var transform = presentation.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.Transform2D>().First();
            Assert.Equal(300_000, transform.Rotation!.Value);
            Assert.False(transform.HorizontalFlip!.Value);
            Assert.True(transform.VerticalFlip!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var shape = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements).Shape;
        Assert.True(shape.Transform.HasRotationAngle60000);
        Assert.Equal(300_000, shape.Transform.RotationAngle60000);
        Assert.True(shape.Transform.HasFlipHorizontal);
        Assert.False(shape.Transform.FlipHorizontal);
        Assert.True(shape.Transform.HasFlipVertical);
        Assert.True(shape.Transform.FlipVertical);

        shape.Transform = new PresentationShapeTransform
        {
            RotationAngle60000 = -12 * 60_000,
            FlipHorizontal = true,
            FlipVertical = false,
        };
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var editedRoundTrip = Import(edited.File.ToByteArray());
        Assert.True(editedRoundTrip.Ok, Diagnostics(editedRoundTrip));
        var editedTransform = Assert.Single(Assert.Single(editedRoundTrip.Artifact.Presentation.Slides).Elements).Shape.Transform;
        Assert.Equal(-720_000, editedTransform.RotationAngle60000);
        Assert.True(editedTransform.FlipHorizontal);
        Assert.False(editedTransform.FlipVertical);

        Assert.Single(Assert.Single(editedRoundTrip.Artifact.Presentation.Slides).Elements).Shape.Transform = null;
        var cleared = Export(editedRoundTrip.Artifact);
        Assert.True(cleared.Ok, Diagnostics(cleared));
        var clearedRoundTrip = Import(cleared.File.ToByteArray());
        Assert.True(clearedRoundTrip.Ok, Diagnostics(clearedRoundTrip));
        Assert.Null(Assert.Single(Assert.Single(clearedRoundTrip.Artifact.Presentation.Slides).Elements).Shape.Transform);
    }

    [Fact]
    public void OrdinaryShapeTransformValidationAndUnknownNativeAttributesFailClosed()
    {
        var empty = ExportRequest();
        empty.Artifact.Presentation.Slides[0].Elements[0].Shape.Transform = new PresentationShapeTransform();
        var emptyResponse = Invoke(empty);
        Assert.False(emptyResponse.Ok);
        Assert.Equal("invalid_presentation_transform", Assert.Single(emptyResponse.Diagnostics).Code);

        var outOfRange = ExportRequest();
        outOfRange.Artifact.Presentation.Slides[0].Elements[0].Shape.Transform = new PresentationShapeTransform
        {
            RotationAngle60000 = 21_600_001,
        };
        var outOfRangeResponse = Invoke(outOfRange);
        Assert.False(outOfRangeResponse.Ok);
        Assert.Equal("invalid_presentation_transform", Assert.Single(outOfRangeResponse.Diagnostics).Code);

        var source = Invoke(ExportRequest()).File.ToByteArray();
        var attributed = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("<a:xfrm", "<a:xfrm xmlns:fixture=\"urn:office-kit:shape-transform\" fixture:opaque=\"kept\"", StringComparison.Ordinal));
        var imported = Import(attributed);
        Assert.True(imported.Ok, Diagnostics(imported));
        var shape = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements);
        Assert.False(shape.Source.Editable);
        Assert.Null(shape.Shape.Transform);

        shape.Shape.Transform = new PresentationShapeTransform { RotationAngle60000 = 60_000 };
        var rejected = Export(imported.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rejected.Diagnostics).Code);
    }

    [Fact]
    public void SourceFreeMasterLayoutAndSlidePlaceholdersRoundTrip()
    {
        var request = ExportRequest();
        var master = new PresentationMaster { Id = "master/authored", Name = "Authored master" };
        master.Placeholders.Add(new PresentationPlaceholder
        {
            Id = "master/authored/title",
            Name = "Master title",
            Type = "title",
            Index = 0U,
            DirectFrame = new PresentationPlaceholderFrame
            {
                LeftEmu = 571_500L,
                TopEmu = 381_000L,
                WidthEmu = 8_191_500L,
                HeightEmu = 666_750L,
            },
        });
        request.Artifact.Presentation.Masters.Add(master);
        var layout = new PresentationLayout
        {
            Id = "layout/title-body",
            Name = "Title and body",
            MasterId = master.Id,
            Type = "obj",
        };
        layout.Placeholders.Add(new PresentationPlaceholder
        {
            Id = "layout/title-body/body",
            Name = "Layout body",
            Type = "body",
            Index = 1U,
            DirectFrame = new PresentationPlaceholderFrame
            {
                LeftEmu = 571_500L,
                TopEmu = 1_333_500L,
                WidthEmu = 8_191_500L,
                HeightEmu = 4_381_500L,
            },
        });
        request.Artifact.Presentation.Layouts.Add(layout);
        var slide = request.Artifact.Presentation.Slides[0];
        slide.LayoutId = layout.Id;
        var shape = slide.Elements[0].Shape;
        shape.Placeholder = new PresentationPlaceholderIdentity
        {
            Type = "title",
            Index = 0U,
            InheritsGeometry = false,
        };
        shape.DirectFrame = new PresentationPlaceholderFrame
        {
            LeftEmu = shape.LeftEmu,
            TopEmu = shape.TopEmu,
            WidthEmu = shape.WidthEmu,
            HeightEmu = shape.HeightEmu,
        };

        var response = Invoke(request);
        Assert.True(response.Ok, Diagnostics(response));
        using (var stream = new MemoryStream(response.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var masterPart = Assert.Single(package.PresentationPart!.SlideMasterParts);
            var nativeMaster = Assert.Single(masterPart.SlideMaster!.CommonSlideData!.ShapeTree!.Elements<P.Shape>());
            Assert.Equal("title", nativeMaster.NonVisualShapeProperties!.ApplicationNonVisualDrawingProperties!.GetFirstChild<P.PlaceholderShape>()!.GetAttribute("type", string.Empty).Value);
            Assert.Equal(0U, nativeMaster.NonVisualShapeProperties.ApplicationNonVisualDrawingProperties.GetFirstChild<P.PlaceholderShape>()!.Index!.Value);
            var nativeLayout = Assert.Single(masterPart.SlideLayoutParts);
            Assert.Equal("obj", nativeLayout.SlideLayout!.GetAttribute("type", string.Empty).Value);
            var nativeLayoutPlaceholder = Assert.Single(nativeLayout.SlideLayout.CommonSlideData!.ShapeTree!.Elements<P.Shape>());
            Assert.Equal("body", nativeLayoutPlaceholder.NonVisualShapeProperties!.ApplicationNonVisualDrawingProperties!.GetFirstChild<P.PlaceholderShape>()!.GetAttribute("type", string.Empty).Value);
            var nativeSlide = Assert.Single(package.PresentationPart.SlideParts).Slide!;
            var nativeSlidePlaceholder = Assert.Single(nativeSlide.CommonSlideData!.ShapeTree!.Elements<P.Shape>());
            Assert.Equal("title", nativeSlidePlaceholder.NonVisualShapeProperties!.ApplicationNonVisualDrawingProperties!.GetFirstChild<P.PlaceholderShape>()!.GetAttribute("type", string.Empty).Value);
            Assert.Equal(571_500L, nativeSlidePlaceholder.ShapeProperties!.Transform2D!.Offset!.X!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var imported = Import(response.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedMaster = Assert.Single(imported.Artifact.Presentation.Masters);
        Assert.Single(importedMaster.Placeholders);
        var importedLayout = Assert.Single(imported.Artifact.Presentation.Layouts);
        Assert.Equal("obj", importedLayout.Type);
        Assert.Single(importedLayout.Placeholders);
        var importedShape = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements).Shape;
        Assert.NotNull(importedShape.Placeholder);
        Assert.False(importedShape.Placeholder.InheritsGeometry);
        Assert.NotNull(importedShape.DirectFrame);
        Assert.Equal(571_500L, importedShape.DirectFrame.LeftEmu);
        var roundTrip = Export(imported.Artifact);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
    }

