        table.ColumnWidthsEmu.Add([700_000, 700_000]);
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 450_000,
            Cells = { new PresentationTableCell { Text = "Gate" }, new PresentationTableCell { Text = "State" } },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 450_000,
            Cells = { new PresentationTableCell { Text = "QA" }, new PresentationTableCell { Text = "Pass" } },
        });
        groupElement.Group.Children.Add(new PresentationElement
        {
            Id = "presentation/slide/1/group/1/table",
            Name = "Grouped table",
            Table = table,
        });
        var chart = new PresentationChart
        {
            LeftEmu = 2_700_000,
            TopEmu = 700_000,
            WidthEmu = 1_100_000,
            HeightEmu = 900_000,
            Type = SpreadsheetChartType.Bar,
            Title = "Grouped chart",
            HasLegend = false,
        };
        chart.Categories.Add(["A", "B"]);
        chart.Series.Add(new SpreadsheetChartSeriesArtifact { Name = "Score" });
        chart.Series[0].Values.Add([3, 5]);
        groupElement.Group.Children.Add(new PresentationElement
        {
            Id = "presentation/slide/1/group/1/chart",
            Name = "Grouped chart",
            Chart = chart,
        });
        var nested = new PresentationElement
        {
            Id = "presentation/slide/1/group/1/nested",
            Name = "Nested group",
            Group = new PresentationGroup
            {
                LeftEmu = 0,
                TopEmu = 1_800_000,
                WidthEmu = 1_000_000,
                HeightEmu = 400_000,
                ChildWidthEmu = 1_000_000,
                ChildHeightEmu = 400_000,
            },
        };
        nested.Group.Children.Add(new PresentationElement
        {
            Id = "presentation/slide/1/group/1/nested/label",
            Name = "Nested label",
            Shape = new PresentationShape
            {
                Geometry = "rect",
                LeftEmu = 0,
                TopEmu = 0,
                WidthEmu = 1_000_000,
                HeightEmu = 400_000,
                Text = "Nested",
                FillRgb = "DBEAFE",
                LineRgb = "2563EB",
                LineWidthEmu = 12_700,
            },
        });
        groupElement.Group.Children.Add(nested);
        request.Artifact.Presentation.Slides[0].Elements.Add(groupElement);

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slide = package.PresentationPart!.SlideParts.Single().Slide!;
            Assert.Equal(2, slide.Descendants<P.GroupShape>().Count());
            var outer = slide.Descendants<P.GroupShape>().First();
            var transform = outer.GroupShapeProperties!.GetFirstChild<A.TransformGroup>()!;
            Assert.Equal(-100_000L, transform.ChildOffset!.X!.Value);
            Assert.Equal(200_000L, transform.ChildOffset.Y!.Value);
            Assert.Equal(2, outer.Elements<P.Shape>().Count());
            Assert.Single(outer.Elements<P.ConnectionShape>());
            Assert.Single(outer.Elements<P.Picture>());
            Assert.Equal(2, outer.Elements<P.GraphicFrame>().Count());
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedGroup = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Group);
        Assert.True(importedGroup.Source.Editable);
        Assert.Equal(-100_000L, importedGroup.Group.ChildLeftEmu);
        Assert.Equal([
            PresentationElement.ContentOneofCase.Shape,
            PresentationElement.ContentOneofCase.Shape,
            PresentationElement.ContentOneofCase.Connector,
            PresentationElement.ContentOneofCase.Image,
            PresentationElement.ContentOneofCase.Table,
            PresentationElement.ContentOneofCase.Chart,
            PresentationElement.ContentOneofCase.Group,
        ], importedGroup.Group.Children.Select(child => child.ContentCase));
        Assert.All(importedGroup.Group.Children, child => Assert.True(child.Source.Editable));
        Assert.Single(importedGroup.Group.Children[^1].Group.Children);

        importedGroup.Name = "Edited agent card group";
        importedGroup.Group.LeftEmu = 1_200_000;
        importedGroup.Group.ChildLeftEmu = -50_000;
        importedGroup.Group.Children[0].Shape.Text = "Edited grouped evidence";
        importedGroup.Group.Children[0].Shape.TextBody.Paragraphs[0].Runs[0].Text = "Edited grouped evidence";
        importedGroup.Group.Children[2].Connector.EndArrow = string.Empty;
        importedGroup.Group.Children[3].Image.AltText = "Edited grouped image";
        importedGroup.Group.Children[4].Table.Rows[1].Cells[1].Text = "After";
        importedGroup.Group.Children[5].Chart.Title = "Edited grouped chart";
        importedGroup.Group.Children[5].Chart.Series[0].Values[1] = 8;
        importedGroup.Group.Children[6].Group.TopEmu = 1_900_000;
        importedGroup.Group.Children[6].Group.Children[0].Shape.FillRgb = "FDE68A";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        using (var stream = new MemoryStream(edited.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var outer = package.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.GroupShape>().First();
            Assert.Equal("Edited agent card group", outer.NonVisualGroupShapeProperties!.NonVisualDrawingProperties!.Name!.Value);
            Assert.Equal(1_200_000L, outer.GroupShapeProperties!.GetFirstChild<A.TransformGroup>()!.Offset!.X!.Value);
            Assert.Equal("Edited grouped evidence", outer.Elements<P.Shape>().First().Descendants<A.Text>().Single().Text);
            Assert.Null(outer.Elements<P.ConnectionShape>().Single().ShapeProperties!.GetFirstChild<A.Outline>()!.GetFirstChild<A.TailEnd>());
            Assert.Equal("Edited grouped image", outer.Elements<P.Picture>().Single().NonVisualPictureProperties!.NonVisualDrawingProperties!.Description!.Value);
            Assert.Contains("After", outer.Elements<P.GraphicFrame>().Single(frame => frame.Descendants<A.Table>().Any()).Descendants<A.Text>().Select(text => text.Text));
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripGroup = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Group);
        Assert.Equal("Edited grouped evidence", roundTripGroup.Group.Children[0].Shape.Text);
        Assert.Equal("After", roundTripGroup.Group.Children[4].Table.Rows[1].Cells[1].Text);
        Assert.Equal(8D, roundTripGroup.Group.Children[5].Chart.Series[0].Values[1]);
        Assert.Equal("FDE68A", roundTripGroup.Group.Children[6].Group.Children[0].Shape.FillRgb);

        roundTripGroup.Group.Children.RemoveAt(1);
        var topologyRejected = Export(roundTrip.Artifact);
        Assert.False(topologyRejected.Ok);
        Assert.Equal("presentation_group_topology_changed", Assert.Single(topologyRejected.Diagnostics).Code);

        var irregularSource = ReplaceZipText(authored.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            Regex.Replace(
                xml,
                "(<p:grpSp><p:nvGrpSpPr><p:cNvPr\\b[^>]*name=\"Agent card group\"[^>]*/>[\\s\\S]*?<p:grpSpPr)(>)",
                "$1 bwMode=\"gray\"$2",
                RegexOptions.CultureInvariant,
                TimeSpan.FromSeconds(1)));
        var irregularImported = Import(irregularSource);
        Assert.True(irregularImported.Ok, Diagnostics(irregularImported));
        var irregular = Assert.Single(Assert.Single(irregularImported.Artifact.Presentation.Slides).Elements, item => item.Name == "Agent card group");
        Assert.Equal(PresentationElement.ContentOneofCase.Opaque, irregular.ContentCase);
        Assert.False(irregular.Source.Editable);
    }

    [Fact]
    public void TopLevelPicturesAuthorImportEditReplaceAndPreserveResidualGraph()
    {
        var authoredRequest = ExportRequest();
        var authoredBytes = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=");
        var authoredAssetId = AddPictureAsset(authoredRequest.Artifact, authoredBytes, "image/png");
        authoredRequest.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/image/1",
            Name = "Authored picture",
            Image = new PresentationImage
            {
                AssetId = authoredAssetId,
                AltText = "Authored image evidence",
                AccessibilityTitle = "Authored evidence image",
                AccessibilityDecorative = false,
                LeftEmu = 500_000,
                TopEmu = 1_250_000,
                WidthEmu = 1_500_000,
                HeightEmu = 1_000_000,
                Crop = new PresentationImageCrop
                {
                    LeftThousandthPercent = 25_000,
                    RightThousandthPercent = 25_000,
                },
                Transform = new PresentationImageTransform
                {
                    RotationAngle60000 = 180_000,
                    FlipHorizontal = false,
                    FlipVertical = true,
                },
            },
        });
        var authored = Invoke(authoredRequest);
        Assert.True(authored.Ok, Diagnostics(authored));
        var authoredRoundTrip = Import(authored.File.ToByteArray());
        Assert.True(authoredRoundTrip.Ok, Diagnostics(authoredRoundTrip));
        var authoredImage = Assert.Single(Assert.Single(authoredRoundTrip.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Image);
        Assert.True(authoredImage.Source.AccessibilityEditable);
        Assert.Equal("Authored evidence image", authoredImage.Image.AccessibilityTitle);
        Assert.Equal("Authored image evidence", authoredImage.Image.AltText);
        Assert.True(authoredImage.Image.HasAccessibilityDecorative);
        Assert.False(authoredImage.Image.AccessibilityDecorative);
        Assert.Equal(25_000, authoredImage.Image.Crop.LeftThousandthPercent);
        Assert.Equal(25_000, authoredImage.Image.Crop.RightThousandthPercent);
        Assert.Equal(180_000, authoredImage.Image.Transform.RotationAngle60000);
        Assert.True(authoredImage.Image.Transform.HasFlipHorizontal);
        Assert.False(authoredImage.Image.Transform.FlipHorizontal);
        Assert.True(authoredImage.Image.Transform.FlipVertical);

        var first = Invoke(ExportRequest());
        var source = AddPicture(first.File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.Equal(2, slide.Elements.Count);
        Assert.True(slide.Elements[0].Source.Editable);
        Assert.True(slide.Elements[1].Source.Editable);
        Assert.True(slide.Elements[1].Source.AccessibilityEditable);
        Assert.Equal(PresentationElement.ContentOneofCase.Image, slide.Elements[1].ContentCase);
        Assert.Equal("Opaque package evidence", slide.Elements[1].Image.AltText);
        Assert.All(imported.Artifact.OpaqueOpc.Parts, part => Assert.False(string.IsNullOrWhiteSpace(part.ContentType)));
        var imagePart = Assert.Single(imported.Artifact.OpaqueOpc.Parts,
            part => part.Path.EndsWith("/image.png", StringComparison.OrdinalIgnoreCase) || part.Path.EndsWith("/image1.png", StringComparison.OrdinalIgnoreCase));
        Assert.Equal("image/png", imagePart.ContentType);
        Assert.Contains(imported.Artifact.OpaqueOpc.PackageRelationships,
            relationship => relationship.SourcePath == "ppt/slides/slide1.xml" && relationship.Id == "rIdImage1");

        slide.Elements[0].Shape.Text = "Edited safely";
        var replacement = Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl2nGQAAAAASUVORK5CYII=");
        var replacementId = AddPictureAsset(imported.Artifact, replacement, "image/png");
        slide.Elements[1].Name = "Edited picture";
        slide.Elements[1].Image.AccessibilityTitle = "Edited picture evidence";
        slide.Elements[1].Image.AltText = "Edited alternative text";
        slide.Elements[1].Image.LeftEmu = 750_000;
        slide.Elements[1].Image.WidthEmu = 2_000_000;
        slide.Elements[1].Image.Crop = new PresentationImageCrop
        {
            LeftThousandthPercent = -10_000,
            TopThousandthPercent = 2_000,
            RightThousandthPercent = 5_000,
            BottomThousandthPercent = 3_000,
        };
        slide.Elements[1].Image.Transform = new PresentationImageTransform
        {
            RotationAngle60000 = -360_000,
            FlipHorizontal = true,
            FlipVertical = false,
        };
        slide.Elements[1].Image.AssetId = replacementId;
        var preserved = Export(imported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Equal("opaque_content_preserved", Assert.Single(preserved.Diagnostics).Code);
        using (var stream = new MemoryStream(preserved.File.ToByteArray()))
        using (var presentation = PresentationDocument.Open(stream, false))
        {
            var slidePart = presentation.PresentationPart!.SlideParts.Single();
            Assert.Equal("Edited safely", string.Concat(slidePart.Slide!.Descendants<A.Text>().Take(1).Select(text => text.Text)));
            Assert.Equal(2, slidePart.ImageParts.Count());
            var picture = Assert.Single(slidePart.Slide!.Descendants<P.Picture>());
            Assert.Equal("Edited picture", picture.NonVisualPictureProperties!.NonVisualDrawingProperties!.Name!.Value);
            Assert.Equal("Edited picture evidence", picture.NonVisualPictureProperties.NonVisualDrawingProperties.GetAttribute("title", string.Empty).Value);
            Assert.Equal("Edited alternative text", picture.NonVisualPictureProperties.NonVisualDrawingProperties.Description!.Value);
            Assert.Equal(-360_000, picture.ShapeProperties!.Transform2D!.Rotation!.Value);
            Assert.True(picture.ShapeProperties.Transform2D.HorizontalFlip!.Value);
            Assert.False(picture.ShapeProperties.Transform2D.VerticalFlip!.Value);
            var crop = picture.BlipFill!.GetFirstChild<A.SourceRectangle>() ?? throw new InvalidOperationException("Expected edited picture crop.");
            Assert.Equal(-10_000, crop.Left!.Value);
            Assert.Equal(2_000, crop.Top!.Value);
            Assert.Equal(5_000, crop.Right!.Value);
            Assert.Equal(3_000, crop.Bottom!.Value);
            var selected = Assert.IsType<ImagePart>(slidePart.GetPartById(picture.BlipFill!.Blip!.Embed!.Value!));
            using var selectedStream = selected.GetStream(FileMode.Open, FileAccess.Read);
            using var selectedBytes = new MemoryStream();
            selectedStream.CopyTo(selectedBytes);
            Assert.Equal(replacement, selectedBytes.ToArray());
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(presentation));
        }

        var roundTrip = Import(preserved.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripImage = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Image);
        Assert.Equal("Edited picture", roundTripImage.Name);
        Assert.Equal("Edited picture evidence", roundTripImage.Image.AccessibilityTitle);
        Assert.Equal("Edited alternative text", roundTripImage.Image.AltText);
        Assert.False(roundTripImage.Image.HasAccessibilityDecorative);
        Assert.Equal(750_000L, roundTripImage.Image.LeftEmu);
        Assert.Equal(2_000_000L, roundTripImage.Image.WidthEmu);
        Assert.Equal(replacementId, roundTripImage.Image.AssetId);
        Assert.Equal(-10_000, roundTripImage.Image.Crop.LeftThousandthPercent);
        Assert.Equal(2_000, roundTripImage.Image.Crop.TopThousandthPercent);
        Assert.Equal(5_000, roundTripImage.Image.Crop.RightThousandthPercent);
        Assert.Equal(3_000, roundTripImage.Image.Crop.BottomThousandthPercent);

        var decorativeArtifact = roundTrip.Artifact.Clone();
        var decorativeImage = Assert.Single(Assert.Single(decorativeArtifact.Presentation.Slides).Elements,
            item => item.ContentCase == PresentationElement.ContentOneofCase.Image).Image;
        decorativeImage.AccessibilityTitle = string.Empty;
        decorativeImage.AltText = string.Empty;
        decorativeImage.AccessibilityDecorative = true;
        var decorativeExport = Export(decorativeArtifact);
        Assert.True(decorativeExport.Ok, Diagnostics(decorativeExport));
        using (var stream = new MemoryStream(decorativeExport.File.ToByteArray()))
        using (var presentation = PresentationDocument.Open(stream, false))
        {
            var nonVisual = Assert.Single(presentation.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Picture>())
                .NonVisualPictureProperties!.NonVisualDrawingProperties!;
            Assert.Null(nonVisual.Title);
            Assert.Null(nonVisual.Description);
            Assert.True(Assert.Single(nonVisual.Descendants<AD.Decorative>()).Val!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(presentation));
        }
        var decorativeRoundTrip = Import(decorativeExport.File.ToByteArray());
        Assert.True(decorativeRoundTrip.Ok, Diagnostics(decorativeRoundTrip));
        var roundTripDecorativeImage = Assert.Single(Assert.Single(decorativeRoundTrip.Artifact.Presentation.Slides).Elements,
            item => item.ContentCase == PresentationElement.ContentOneofCase.Image).Image;
        Assert.True(roundTripDecorativeImage.HasAccessibilityDecorative);
        Assert.True(roundTripDecorativeImage.AccessibilityDecorative);
        Assert.Empty(roundTripDecorativeImage.AccessibilityTitle);
        Assert.Empty(roundTripDecorativeImage.AltText);

        roundTripImage.Image.Crop = null;
        var uncropped = Export(roundTrip.Artifact);
        Assert.True(uncropped.Ok, Diagnostics(uncropped));
        using (var stream = new MemoryStream(uncropped.File.ToByteArray()))
        using (var presentation = PresentationDocument.Open(stream, false))
            Assert.Null(Assert.Single(presentation.PresentationPart!.SlideParts.Single().Slide!.Descendants<P.Picture>()).BlipFill!.GetFirstChild<A.SourceRectangle>());

        roundTripImage.Image.Crop = new PresentationImageCrop { LeftThousandthPercent = 80_000, RightThousandthPercent = 30_000 };
        var invalidCrop = Export(roundTrip.Artifact);
        Assert.False(invalidCrop.Ok);
        Assert.Equal("invalid_presentation_image", Assert.Single(invalidCrop.Diagnostics).Code);
        roundTripImage.Image.Crop = null;

        var residualMetadataSource = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            Regex.Replace(
                xml,
                "(<p:cNvPr\\b[^>]*name=\"Preserved picture\"[^>]*)/>",
                "$1 xmlns:fixture=\"urn:office-kit:image-accessibility\"><a:extLst><a:ext uri=\"{B0A9F838-8A5A-4E24-B521-0C9AA5407A54}\"><fixture:opaque value=\"kept\"/></a:ext></a:extLst></p:cNvPr>",
                RegexOptions.CultureInvariant,
                TimeSpan.FromSeconds(1)));
        var residualMetadataImported = Import(residualMetadataSource);
        Assert.True(residualMetadataImported.Ok, Diagnostics(residualMetadataImported));
        var residualMetadataImage = Assert.Single(
            Assert.Single(residualMetadataImported.Artifact.Presentation.Slides).Elements,
            item => item.ContentCase == PresentationElement.ContentOneofCase.Image);
        Assert.True(residualMetadataImage.Source.AccessibilityEditable);
        residualMetadataImage.Image.AccessibilityTitle = "Reviewed opaque image metadata";
        var residualMetadataEdited = Export(residualMetadataImported.Artifact);
        Assert.True(residualMetadataEdited.Ok, Diagnostics(residualMetadataEdited));
        var residualMetadataXml = Encoding.UTF8.GetString(ZipBytes(residualMetadataEdited.File.ToByteArray(), "ppt/slides/slide1.xml"));
        Assert.Contains("fixture:opaque value=\"kept\"", residualMetadataXml, StringComparison.Ordinal);
        Assert.Contains("title=\"Reviewed opaque image metadata\"", residualMetadataXml, StringComparison.Ordinal);
        var residualMetadataRoundTrip = Import(residualMetadataEdited.File.ToByteArray());
        Assert.True(residualMetadataRoundTrip.Ok, Diagnostics(residualMetadataRoundTrip));
        Assert.Equal(
            "Reviewed opaque image metadata",
            Assert.Single(
                Assert.Single(residualMetadataRoundTrip.Artifact.Presentation.Slides).Elements,
                item => item.ContentCase == PresentationElement.ContentOneofCase.Image).Image.AccessibilityTitle);

        var duplicateDecorativeSource = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            Regex.Replace(
                xml,
                "(<p:cNvPr\\b[^>]*name=\"Preserved picture\"[^>]*)/>",
                "$1><a:extLst>" +
                "<a:ext uri=\"{C183D7F6-B498-43B3-948B-1728B52AA6E4}\"><adec:decorative xmlns:adec=\"http://schemas.microsoft.com/office/drawing/2017/decorative\" val=\"1\"/></a:ext>" +
                "<a:ext uri=\"{C183D7F6-B498-43B3-948B-1728B52AA6E4}\"><adec:decorative xmlns:adec=\"http://schemas.microsoft.com/office/drawing/2017/decorative\" val=\"0\"/></a:ext>" +
                "</a:extLst></p:cNvPr>",
                RegexOptions.CultureInvariant,
                TimeSpan.FromSeconds(1)));
        var duplicateDecorativeImported = Import(duplicateDecorativeSource);
        Assert.True(duplicateDecorativeImported.Ok, Diagnostics(duplicateDecorativeImported));
        var duplicateDecorativePicture = Assert.Single(
            Assert.Single(duplicateDecorativeImported.Artifact.Presentation.Slides).Elements,
            item => item.ContentCase == PresentationElement.ContentOneofCase.Image);
        Assert.True(duplicateDecorativePicture.Source.Editable);
        Assert.False(duplicateDecorativePicture.Source.AccessibilityEditable);
        Assert.Empty(duplicateDecorativePicture.Image.AccessibilityTitle);
        Assert.Empty(duplicateDecorativePicture.Image.AltText);
        Assert.False(duplicateDecorativePicture.Image.HasAccessibilityDecorative);
        var duplicateDecorativeNoOp = Export(duplicateDecorativeImported.Artifact);
        Assert.True(duplicateDecorativeNoOp.Ok, Diagnostics(duplicateDecorativeNoOp));
        Assert.Equal(duplicateDecorativeSource, duplicateDecorativeNoOp.File.ToByteArray());
        duplicateDecorativePicture.Image.AccessibilityDecorative = true;
        var duplicateDecorativeRejected = Export(duplicateDecorativeImported.Artifact);
        Assert.False(duplicateDecorativeRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(duplicateDecorativeRejected.Diagnostics).Code);

        var emptyTitleSource = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("name=\"Preserved picture\"", "name=\"Preserved picture\" title=\"\"", StringComparison.Ordinal));
        var emptyTitleImported = Import(emptyTitleSource);
        Assert.True(emptyTitleImported.Ok, Diagnostics(emptyTitleImported));
        var emptyTitlePicture = Assert.Single(
            Assert.Single(emptyTitleImported.Artifact.Presentation.Slides).Elements,
            item => item.ContentCase == PresentationElement.ContentOneofCase.Image);
        Assert.True(emptyTitlePicture.Source.Editable);
        Assert.False(emptyTitlePicture.Source.AccessibilityEditable);
        emptyTitlePicture.Image.AccessibilityTitle = "Unsafe bypass";
        var emptyTitleRejected = Export(emptyTitleImported.Artifact);
        Assert.False(emptyTitleRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(emptyTitleRejected.Diagnostics).Code);

        var jpegId = AddPictureAsset(roundTrip.Artifact, [0xff, 0xd8, 0xff, 0xd9], "image/jpeg");
        roundTripImage.Image.AssetId = jpegId;
        var rejected = Export(roundTrip.Artifact);
        Assert.False(rejected.Ok);
        Assert.Equal("unsupported_presentation_image", Assert.Single(rejected.Diagnostics).Code);

        var complexSource = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("<a:blip r:embed=\"rIdImage1\"", "<a:blip r:embed=\"rIdImage1\" cstate=\"print\"", StringComparison.Ordinal));
        var complexImported = Import(complexSource);
        var complexPicture = Assert.Single(Assert.Single(complexImported.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Opaque);
        Assert.False(complexPicture.Source.Editable);
        complexPicture.Name = "Escalated picture";
        var complexRejected = Export(complexImported.Artifact);
        Assert.False(complexRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(complexRejected.Diagnostics).Code);

        var irregularCropSource = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("<a:stretch>", "<a:srcRect l=\"1000\" fixture:unknown=\"1\" xmlns:fixture=\"urn:office-kit:test\"/><a:stretch>", StringComparison.Ordinal));
        var irregularCropImported = Import(irregularCropSource);
        Assert.True(irregularCropImported.Ok, Diagnostics(irregularCropImported));
        var irregularCropPicture = Assert.Single(Assert.Single(irregularCropImported.Artifact.Presentation.Slides).Elements, item => item.ContentCase == PresentationElement.ContentOneofCase.Opaque);
        Assert.False(irregularCropPicture.Source.Editable);
    }

    [Fact]
    public void TopLevelTablesAuthorImportEditResizeAndFailClosedOnMergedCells()
    {
        var request = ExportRequest();
        var table = new PresentationTable
        {
            LeftEmu = 500_000,
            TopEmu = 1_300_000,
            WidthEmu = 4_000_000,
            HeightEmu = 1_600_000,
            FirstRow = true,
            BandedRows = false,
        };
        table.ColumnWidthsEmu.Add([1_500_000, 2_500_000]);
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 600_000,
            Cells = { new PresentationTableCell { Text = "Metric" }, new PresentationTableCell { Text = "Value" } },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 1_000_000,
            Cells = { new PresentationTableCell { Text = "Revenue" }, new PresentationTableCell { Text = "$42M" } },
        });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/table/1",
            Name = "Authored metrics",
            Table = table,
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var native = Assert.Single(package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.Table>());
            Assert.Equal([1_500_000L, 2_500_000L], native.GetFirstChild<A.TableGrid>()!.Elements<A.GridColumn>().Select(column => column.Width!.Value));
            Assert.Equal(["Metric", "Value", "Revenue", "$42M"], native.Descendants<A.Text>().Select(text => text.Text));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedTable = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.True(importedTable.Source.Editable);
        Assert.True(importedTable.Table.HasFirstRow);
        Assert.True(importedTable.Table.FirstRow);
        Assert.True(importedTable.Table.HasBandedRows);
        Assert.False(importedTable.Table.BandedRows);
        Assert.Equal("Revenue", importedTable.Table.Rows[1].Cells[0].Text);

        importedTable.Name = "Edited metrics";
        importedTable.Table.LeftEmu = 750_000;
        importedTable.Table.WidthEmu = 5_000_000;
        importedTable.Table.HeightEmu = 2_000_000;
        importedTable.Table.ColumnWidthsEmu.Clear();
        importedTable.Table.ColumnWidthsEmu.Add([2_000_000, 3_000_000]);
        importedTable.Table.Rows[0].HeightEmu = 750_000;
        importedTable.Table.Rows[1].HeightEmu = 1_250_000;
        importedTable.Table.Rows[1].Cells[1].Text = "$47M";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripTable = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.Equal("Edited metrics", roundTripTable.Name);
        Assert.Equal(750_000L, roundTripTable.Table.LeftEmu);
        Assert.Equal(5_000_000L, roundTripTable.Table.WidthEmu);
        Assert.Equal([2_000_000L, 3_000_000L], roundTripTable.Table.ColumnWidthsEmu);
        Assert.Equal("$47M", roundTripTable.Table.Rows[1].Cells[1].Text);

        var topologyChanged = Import(edited.File.ToByteArray());
        topologyChanged.Artifact.Presentation.Slides[0].Elements[1].Table.Rows[0].Cells.Add(new PresentationTableCell { Text = "extra" });
        var topologyRejected = Export(topologyChanged.Artifact);
        Assert.False(topologyRejected.Ok);
        Assert.Equal("invalid_presentation_table", Assert.Single(topologyRejected.Diagnostics).Code);

        var mergedSource = ReplaceZipText(edited.File.ToByteArray(), "ppt/slides/slide1.xml", xml =>
            xml.Replace("<a:tc>", "<a:tc gridSpan=\"2\">", StringComparison.Ordinal));
        var merged = Import(mergedSource);
        Assert.True(merged.Ok, Diagnostics(merged));
        var opaque = Assert.Single(Assert.Single(merged.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Opaque);
        Assert.False(opaque.Source.Editable);
    }

    [Fact]
    public void TopLevelTablesAuthorImportAndEditCanonicalRectangularMerges()
    {
        var request = ExportRequest();
        var table = new PresentationTable
        {
            LeftEmu = 500_000,
            TopEmu = 1_300_000,
            WidthEmu = 4_000_000,
            HeightEmu = 2_000_000,
            FirstRow = true,
            BandedRows = true,
        };
        table.ColumnWidthsEmu.Add([1_000_000, 1_000_000, 1_000_000, 1_000_000]);
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells =
            {
                new PresentationTableCell { Text = "Readiness evidence" },
                new PresentationTableCell(),
                new PresentationTableCell(),
                new PresentationTableCell { Text = "Owner" },
            },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells =
            {
                new PresentationTableCell { Text = "Native QA" },
                new PresentationTableCell(),
                new PresentationTableCell { Text = "Pass" },
                new PresentationTableCell { Text = "Release" },
            },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells =
            {
                new PresentationTableCell(),
                new PresentationTableCell(),
                new PresentationTableCell { Text = "Verified" },
                new PresentationTableCell(),
            },
        });
        table.Rows.Add(new PresentationTableRow
        {
            HeightEmu = 500_000,
            Cells =
            {
                new PresentationTableCell { Text = "Audit" },
                new PresentationTableCell { Text = "Bound" },
                new PresentationTableCell { Text = "Ready" },
                new PresentationTableCell(),
            },
        });
        table.MergeRanges.Add(new PresentationTableMergeRange { StartRow = 0, EndRow = 0, StartColumn = 0, EndColumn = 2 });
        table.MergeRanges.Add(new PresentationTableMergeRange { StartRow = 1, EndRow = 2, StartColumn = 0, EndColumn = 1 });
        table.MergeRanges.Add(new PresentationTableMergeRange { StartRow = 1, EndRow = 3, StartColumn = 3, EndColumn = 3 });
        request.Artifact.Presentation.Slides[0].Elements.Add(new PresentationElement
        {
            Id = "presentation/slide/1/table/merged",
            Name = "Merged evidence",
            Table = table,
        });

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var rows = Assert.Single(package.PresentationPart!.SlideParts.Single().Slide!.Descendants<A.Table>()).Elements<A.TableRow>().ToArray();
            var first = rows[0].Elements<A.TableCell>().ToArray();
            Assert.Equal(3, first[0].GridSpan!.Value);
            Assert.True(first[1].HorizontalMerge!.Value);
            Assert.True(first[2].HorizontalMerge!.Value);
            var second = rows[1].Elements<A.TableCell>().ToArray();
            Assert.Equal(2, second[0].RowSpan!.Value);
            Assert.Equal(2, second[0].GridSpan!.Value);
            Assert.True(second[1].HorizontalMerge!.Value);
            Assert.Equal(3, second[3].RowSpan!.Value);
            var third = rows[2].Elements<A.TableCell>().ToArray();
            Assert.True(third[0].VerticalMerge!.Value);
            Assert.True(third[1].HorizontalMerge!.Value);
            Assert.True(third[1].VerticalMerge!.Value);
            Assert.True(third[3].VerticalMerge!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var importedTable = Assert.Single(Assert.Single(imported.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.True(importedTable.Source.Editable);
        Assert.Equal(
            [(0u, 0u, 0u, 2u), (1u, 2u, 0u, 1u), (1u, 3u, 3u, 3u)],
            importedTable.Table.MergeRanges.Select(range => (range.StartRow, range.EndRow, range.StartColumn, range.EndColumn)));
        Assert.Equal(string.Empty, importedTable.Table.Rows[2].Cells[1].Text);

        importedTable.Name = "Edited merged evidence";
        importedTable.Table.Rows[0].Cells[0].Text = "Release evidence";
        importedTable.Table.Rows[1].Cells[0].Text = "Native + visual QA";
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var roundTrip = Import(edited.File.ToByteArray());
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripTable = Assert.Single(Assert.Single(roundTrip.Artifact.Presentation.Slides).Elements, element => element.ContentCase == PresentationElement.ContentOneofCase.Table);
        Assert.Equal("Edited merged evidence", roundTripTable.Name);
        Assert.Equal("Release evidence", roundTripTable.Table.Rows[0].Cells[0].Text);
        Assert.Equal("Native + visual QA", roundTripTable.Table.Rows[1].Cells[0].Text);
        Assert.Equal(3, roundTripTable.Table.MergeRanges.Count);

        var coveredText = Import(edited.File.ToByteArray());
        coveredText.Artifact.Presentation.Slides[0].Elements[1].Table.Rows[0].Cells[1].Text = "hidden";
        var coveredRejected = Export(coveredText.Artifact);
        Assert.False(coveredRejected.Ok);
        Assert.Equal("invalid_presentation_table", Assert.Single(coveredRejected.Diagnostics).Code);

        var topologyChanged = Import(edited.File.ToByteArray());
        topologyChanged.Artifact.Presentation.Slides[0].Elements[1].Table.MergeRanges[0].EndColumn = 1;
        var topologyRejected = Export(topologyChanged.Artifact);
        Assert.False(topologyRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(topologyRejected.Diagnostics).Code);
    }

    [Fact]
    public void NativeObjectGraphClassifiesAndPreservesOleDiagramAndContentPart()
    {
        var source = AddNativeObjectGraph(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.Equal(4, slide.Elements.Count);

        var oleElement = slide.Elements[1];
        var ole = oleElement.Opaque;
        Assert.Equal("oleObject", ole.NativeKind);
        Assert.True(oleElement.Source.Editable);
        Assert.Equal(["rIdNativeOle", "rIdNativePreview"], ole.RelationshipReferences.Select(item => item.RelationshipId));
        Assert.Equal(["ppt/embeddings/native-workbook.xlsx", "ppt/media/native-preview.png"], ole.PreservedPartPaths);
        Assert.NotNull(ole.OleWorkbook);
        Assert.Equal("ppt/embeddings/native-workbook.xlsx", ole.OleWorkbook.PartPath);
        Assert.Equal("rIdNativeOle", ole.OleWorkbook.RelationshipId);
        Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(ZipBytes(source, ole.OleWorkbook.PartPath))).ToLowerInvariant(), ole.OleWorkbook.SourceSha256);
        Assert.Empty(ole.OleWorkbook.ReplacementAssetId);

        var diagramElement = slide.Elements[2];
        var diagram = diagramElement.Opaque;
        Assert.Equal("diagram", diagram.NativeKind);
        Assert.True(diagramElement.Source.Editable);
        Assert.Equal(["rIdNativeDm", "rIdNativeLo", "rIdNativeQs", "rIdNativeCs"], diagram.RelationshipReferences.Select(item => item.RelationshipId));
        Assert.Equal(4, diagram.PreservedPartPaths.Count);
        Assert.All(diagram.RelationshipReferences, item => Assert.Contains("relationships", item.NamespaceUri));

        var contentElement = slide.Elements[3];
        var content = contentElement.Opaque;
        Assert.Equal("contentPart", content.NativeKind);
        Assert.True(contentElement.Source.Editable);
        Assert.Equal("rIdNativeContent", Assert.Single(content.RelationshipReferences).RelationshipId);
        Assert.Equal(["ppt/customXml/native-content.xml", "ppt/customXml/itemProps1.xml"], content.PreservedPartPaths);
        Assert.Equal(2, content.PreservedPartPaths.Distinct(StringComparer.OrdinalIgnoreCase).Count());

        slide.Elements[0].Shape.Text = "Edited beside native objects";
        oleElement.Name = "Edited embedded workbook";
        ole.LeftEmu = 1_500_000;
        ole.TopEmu = 1_250_000;
        ole.WidthEmu = 4_000_000;
        ole.HeightEmu = 2_500_000;
        diagramElement.Name = "Edited SmartArt";
        diagram.LeftEmu = 750_000;
        diagram.TopEmu = 4_000_000;
        diagram.WidthEmu = 5_250_000;
        diagram.HeightEmu = 1_500_000;
        contentElement.Name = "Edited content part";
        content.LeftEmu = 7_250_000;
        content.TopEmu = 4_750_000;
        content.WidthEmu = 1_250_000;
        content.HeightEmu = 1_100_000;
        var preserved = Export(imported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Equal("opaque_content_preserved", Assert.Single(preserved.Diagnostics).Code);
        Assert.Equal(ZipBytes(source, "ppt/embeddings/native-workbook.xlsx"), ZipBytes(preserved.File.ToByteArray(), "ppt/embeddings/native-workbook.xlsx"));
        Assert.Equal(ZipBytes(source, "ppt/customXml/itemProps1.xml"), ZipBytes(preserved.File.ToByteArray(), "ppt/customXml/itemProps1.xml"));

        var reimported = Import(preserved.File.ToByteArray());
        Assert.True(reimported.Ok, Diagnostics(reimported));
        var edited = reimported.Artifact.Presentation.Slides[0].Elements.Skip(1).ToArray();
        Assert.Equal(["oleObject", "diagram", "contentPart"], edited.Select(item => item.Opaque.NativeKind));
        Assert.Equal(["Edited embedded workbook", "Edited SmartArt", "Edited content part"], edited.Select(item => item.Name));
        Assert.Equal([(1_500_000L, 1_250_000L, 4_000_000L, 2_500_000L), (750_000L, 4_000_000L, 5_250_000L, 1_500_000L), (7_250_000L, 4_750_000L, 1_250_000L, 1_100_000L)],
            edited.Select(item => (item.Opaque.LeftEmu, item.Opaque.TopEmu, item.Opaque.WidthEmu, item.Opaque.HeightEmu)));
        Assert.All(edited, item => Assert.True(item.Source.Editable));

        imported = Import(source);
        imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.RawXml += " ";
        var rawXmlRejected = Export(imported.Artifact);
        Assert.False(rawXmlRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(rawXmlRejected.Diagnostics).Code);

        imported = Import(source);
        imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.WidthEmu = 0;
        var frameRejected = Export(imported.Artifact);
        Assert.False(frameRejected.Ok);
        Assert.Equal("invalid_presentation_frame", Assert.Single(frameRejected.Diagnostics).Code);
    }

    [Fact]
    public void OleWorkbookPayloadReplacementIsValidatedAndGraphBound()
    {
        var source = AddNativeObjectGraph(Invoke(ExportRequest()).File.ToByteArray());
        var sharedSource = ReplaceZipText(source, "ppt/slides/_rels/slide1.xml.rels", xml => xml.Replace(
            "</Relationships>",
            "<Relationship Id=\"rIdSharedOlePackage\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/package\" Target=\"../embeddings/native-workbook.xlsx\"/></Relationships>",
            StringComparison.Ordinal));
        var sharedImported = Import(sharedSource);
        Assert.True(sharedImported.Ok, Diagnostics(sharedImported));
        Assert.Null(sharedImported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook);

        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var oleElement = imported.Artifact.Presentation.Slides[0].Elements[1];
        var binding = Assert.IsType<PresentationOleWorkbook>(oleElement.Opaque.OleWorkbook);
        var preview = ZipBytes(source, "ppt/media/native-preview.png");
        var diagram = ZipBytes(source, "ppt/diagrams/native-data.xml");
        var replacement = CreateEmbeddedWorkbook("Replacement workbook marker");
        var replacementId = AddOleWorkbookAsset(imported.Artifact, replacement);
        binding.ReplacementAssetId = replacementId;

        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        Assert.Equal(replacement, ZipBytes(exported.File.ToByteArray(), binding.PartPath));
        Assert.Equal(preview, ZipBytes(exported.File.ToByteArray(), "ppt/media/native-preview.png"));
        Assert.Equal(diagram, ZipBytes(exported.File.ToByteArray(), "ppt/diagrams/native-data.xml"));

        var reimported = Import(exported.File.ToByteArray());
        Assert.True(reimported.Ok, Diagnostics(reimported));
        var rebound = Assert.IsType<PresentationOleWorkbook>(reimported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook);
        Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(replacement)).ToLowerInvariant(), rebound.SourceSha256);
        Assert.Empty(rebound.ReplacementAssetId);

        var ppjProjected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/ole-workbook.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(ppjProjected.Ok, Diagnostics(ppjProjected));
        var ppjState = JsonNode.Parse(ppjProjected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var ppjOle = ppjState["pages"]![0]!["elements"]!.AsArray()
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "ole");
        var sourcePayloadId = ppjOle["payloadAsset"]!.GetValue<string>();
        var sourcePayload = Assert.Single(ppjProjected.PresentationProgram.Assets, asset => asset.Id == sourcePayloadId);
        Assert.Equal(ZipBytes(source, binding.PartPath), sourcePayload.Data.ToByteArray());
        Assert.Contains(ppjOle["nativeRef"]!["capabilities"]!.AsArray(), capability =>
            capability!["operation"]!.GetValue<string>() == "setOlePayload" &&
            capability["fields"]!.AsArray().Any(field => field!.GetValue<string>() == "ole.payload"));

        const string replacementProgramAssetId = "replacement-workbook";
        var replacementHash = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(replacement)).ToLowerInvariant();
        ppjState["assets"]!.AsArray().Add(new JsonObject
        {
            ["id"] = replacementProgramAssetId,
            ["uri"] = $"deck.assets/media/{replacementHash}.xlsx",
            ["mimeType"] = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            ["sha256"] = replacementHash,
            ["rights"] = new JsonObject { ["status"] = "user-provided" },
            ["accessibility"] = new JsonObject { ["decorative"] = false, ["description"] = "Replacement embedded workbook." },
        });
        ppjOle["payloadAsset"] = replacementProgramAssetId;
        var ppjCompileRequest = new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(ppjState.ToJsonString()),
                IncludeNodeMap = true,
            },
        };
        ppjCompileRequest.PresentationProgram.Assets.Add(new Asset
        {
            Id = replacementProgramAssetId,
            FileName = $"{replacementHash}.xlsx",
            ContentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            Data = ByteString.CopyFrom(replacement),
            Sha256 = replacementHash,
        });
        var ppjEdited = Invoke(ppjCompileRequest);
        Assert.True(ppjEdited.Ok, Diagnostics(ppjEdited));
        Assert.Equal([binding.PartPath], ppjEdited.PresentationProgram.ChangedParts);
        var ppjBytes = ppjEdited.File.ToByteArray();
        Assert.Equal(replacement, ZipBytes(ppjBytes, binding.PartPath));
        foreach (var path in ZipPartPaths(source).Where(path => !path.Equals(binding.PartPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(source, path), ZipBytes(ppjBytes, path));

        var ppjReprojected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ppjEdited.File,
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/ole-workbook-edited.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(ppjReprojected.Ok, Diagnostics(ppjReprojected));
        using (var ppjJson = JsonDocument.Parse(ppjReprojected.PresentationProgram.ProgramJson.ToByteArray()))
        {
            var reprojectedOle = ppjJson.RootElement.GetProperty("pages")[0].GetProperty("elements")
                .EnumerateArray().Single(item => item.GetProperty("type").GetString() == "ole");
            var reprojectedAssetId = reprojectedOle.GetProperty("payloadAsset").GetString();
            Assert.Equal(replacementHash, ppjJson.RootElement.GetProperty("assets").EnumerateArray()
                .Single(item => item.GetProperty("id").GetString() == reprojectedAssetId)
                .GetProperty("sha256").GetString());
        }

        imported = Import(source);
        imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook.PartPath = "ppt/embeddings/other.xlsx";
        var pathRejected = Export(imported.Artifact);
        Assert.False(pathRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(pathRejected.Diagnostics).Code);

        imported = Import(source);
        imported.Artifact.Presentation.Slides[0].Elements[2].Opaque.OleWorkbook = imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook.Clone();
        var diagramRejected = Export(imported.Artifact);
        Assert.False(diagramRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(diagramRejected.Diagnostics).Code);

        imported = Import(source);
        imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook.ReplacementAssetId = "asset/presentation/ole-workbook/" + new string('0', 64);
        var missingAsset = Export(imported.Artifact);
        Assert.False(missingAsset.Ok);
        Assert.Equal("invalid_presentation_asset", Assert.Single(missingAsset.Diagnostics).Code);

        imported = Import(source);
        var malformed = new byte[] { 0x50, 0x4b, 0x03, 0x04, 1, 2, 3, 4 };
        imported.Artifact.Presentation.Slides[0].Elements[1].Opaque.OleWorkbook.ReplacementAssetId = AddOleWorkbookAsset(imported.Artifact, malformed);
        var malformedRejected = Export(imported.Artifact);
        Assert.False(malformedRejected.Ok);
        Assert.Contains(Assert.Single(malformedRejected.Diagnostics).Code, new[] { "invalid_opc_package", "invalid_presentation_ole_workbook" });
    }

    [Fact]
    public void OleOfficePackagePayloadReplacementIsValidatedAndGraphBound()
    {
        var source = AddNativeDocumentOleGraph(Invoke(ExportRequest()).File.ToByteArray());
        var sharedSource = ReplaceZipText(source, "ppt/slides/_rels/slide1.xml.rels", xml => xml.Replace(
            "</Relationships>",
