            Assert.Equal(ZipBytes(source, path), ZipBytes(exportedBytes, path));
        Assert.Equal(replacement, ZipBytes(exportedBytes, binding.PartPath));
        Assert.Equal(preview, ZipBytes(exportedBytes, "ppt/media/native-document-preview.png"));

        var reimported = Import(exportedBytes);
        Assert.True(reimported.Ok, Diagnostics(reimported));
        var reboundElement = Assert.Single(reimported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject");
        var rebound = Assert.IsType<PresentationOleOfficePackage>(reboundElement.Opaque.OleOfficePackage);
        Assert.Equal(Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(replacement)).ToLowerInvariant(), rebound.SourceSha256);
        Assert.Equal("docx", rebound.Kind);
        Assert.Empty(rebound.ReplacementAssetId);

        imported = Import(source);
        var sourceBinding = Assert.IsType<PresentationOleOfficePackage>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject").Opaque.OleOfficePackage);
        sourceBinding.PartPath = "ppt/embeddings/other.docx";
        var pathRejected = Export(imported.Artifact);
        Assert.False(pathRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(pathRejected.Diagnostics).Code);

        imported = Import(source);
        sourceBinding = Assert.IsType<PresentationOleOfficePackage>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject").Opaque.OleOfficePackage);
        sourceBinding.Kind = "xlsx";
        var kindRejected = Export(imported.Artifact);
        Assert.False(kindRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(kindRejected.Diagnostics).Code);

        imported = Import(source);
        sourceBinding = Assert.IsType<PresentationOleOfficePackage>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject").Opaque.OleOfficePackage);
        sourceBinding.ReplacementAssetId = "asset/presentation/ole-office-package/" + new string('0', 64);
        var missingAsset = Export(imported.Artifact);
        Assert.False(missingAsset.Ok);
        Assert.Equal("invalid_presentation_asset", Assert.Single(missingAsset.Diagnostics).Code);

        imported = Import(source);
        sourceBinding = Assert.IsType<PresentationOleOfficePackage>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject").Opaque.OleOfficePackage);
        var malformed = new byte[] { 0x50, 0x4b, 0x03, 0x04, 1, 2, 3, 4 };
        sourceBinding.ReplacementAssetId = AddOleOfficePackageAsset(imported.Artifact, malformed);
        var malformedRejected = Export(imported.Artifact);
        Assert.False(malformedRejected.Ok);
        Assert.Contains(Assert.Single(malformedRejected.Diagnostics).Code, new[] { "invalid_opc_package", "invalid_presentation_ole_office_package" });

        imported = Import(source);
        sourceBinding = Assert.IsType<PresentationOleOfficePackage>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject").Opaque.OleOfficePackage);
        sourceBinding.ReplacementAssetId = AddOleOfficePackageAsset(imported.Artifact, CreateEmbeddedWorkbook("Wrong package family"));
        var contentTypeRejected = Export(imported.Artifact);
        Assert.False(contentTypeRejected.Ok);
        Assert.Contains(Assert.Single(contentTypeRejected.Diagnostics).Code, new[] { "invalid_opc_package", "invalid_presentation_ole_office_package" });
    }

    [Fact]
    public void EmbeddedXlsxOleWorkbookCloneCopiesIndependentPackageAndSharesPreview()
    {
        var source = AddCloneableOleWorkbookGraph(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var sourceOle = Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element =>
            element.ContentCase == PresentationElement.ContentOneofCase.Opaque && element.Opaque.NativeKind == "oleObject");
        Assert.NotNull(sourceOle.Opaque.OleWorkbook);

        AddPendingClone(imported.Artifact.Presentation, 0, "presentation/clone/ole-workbook");
        var cloned = Export(imported.Artifact);
        Assert.True(cloned.Ok, Diagnostics(cloned));
        var clonedBytes = cloned.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(clonedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(clonedBytes, "ppt/slides/_rels/slide1.xml.rels"));

        using (var stream = new MemoryStream(clonedBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(2, slides.Length);
            var sourcePackage = Assert.Single(slides[0].Parts, pair => pair.OpenXmlPart is EmbeddedPackagePart);
            var clonePackage = Assert.Single(slides[1].Parts, pair => pair.OpenXmlPart is EmbeddedPackagePart);
            Assert.Equal("rIdCloneOleWorkbook", sourcePackage.RelationshipId);
            Assert.Equal(sourcePackage.RelationshipId, clonePackage.RelationshipId);
            Assert.NotEqual(sourcePackage.OpenXmlPart.Uri, clonePackage.OpenXmlPart.Uri);
            Assert.Equal(
                ZipBytes(clonedBytes, sourcePackage.OpenXmlPart.Uri.OriginalString.TrimStart('/')),
                ZipBytes(clonedBytes, clonePackage.OpenXmlPart.Uri.OriginalString.TrimStart('/')));

            var sourcePreview = Assert.Single(slides[0].Parts, pair => pair.OpenXmlPart is ImagePart);
            var clonePreview = Assert.Single(slides[1].Parts, pair => pair.OpenXmlPart is ImagePart);
            Assert.Equal("rIdCloneOlePreview", sourcePreview.RelationshipId);
            Assert.Equal(sourcePreview.RelationshipId, clonePreview.RelationshipId);
            Assert.Equal(sourcePreview.OpenXmlPart.Uri, clonePreview.OpenXmlPart.Uri);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var roundTrip = Import(clonedBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripSource = Assert.Single(roundTrip.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "oleObject");
        var roundTripClone = Assert.Single(roundTrip.Artifact.Presentation.Slides[1].Elements, element => element.Opaque?.NativeKind == "oleObject");
        Assert.NotEqual(roundTripSource.Opaque.OleWorkbook.PartPath, roundTripClone.Opaque.OleWorkbook.PartPath);
        Assert.Equal(roundTripSource.Opaque.OleWorkbook.SourceSha256, roundTripClone.Opaque.OleWorkbook.SourceSha256);

        var replacement = CreateEmbeddedWorkbook("Independent cloned workbook");
        roundTripClone.Opaque.OleWorkbook.ReplacementAssetId = AddOleWorkbookAsset(roundTrip.Artifact, replacement);
        var edited = Export(roundTrip.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(ZipBytes(source, "ppt/embeddings/clone-source-workbook.xlsx"), ZipBytes(edited.File.ToByteArray(), roundTripSource.Opaque.OleWorkbook.PartPath));
        Assert.Equal(replacement, ZipBytes(edited.File.ToByteArray(), roundTripClone.Opaque.OleWorkbook.PartPath));

        var pendingEdit = Import(source);
        AddPendingClone(pendingEdit.Artifact.Presentation, 0, "presentation/clone/ole-workbook-edit");
        var pendingOle = pendingEdit.Artifact.Presentation.Slides[1].Elements.Single(element => element.Opaque?.NativeKind == "oleObject");
        pendingOle.Opaque.OleWorkbook.ReplacementAssetId = AddOleWorkbookAsset(pendingEdit.Artifact, replacement);
        var pendingRejected = Export(pendingEdit.Artifact);
        Assert.False(pendingRejected.Ok);
        Assert.Equal("presentation_slide_clone_mismatch", Assert.Single(pendingRejected.Diagnostics).Code);

    }

    [Fact]
    public void ComponentCloneCanDropAnExclusiveOleGraphWithoutChangingTheSource()
    {
        var source = AddCloneableOleWorkbookGraph(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var sourceSlideXml = ZipBytes(source, "ppt/slides/slide1.xml");
        var sourceSlideRels = ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels");

        AddPendingClone(imported.Artifact.Presentation, 0, "presentation/clone/ole-workbook-delete");
        var clone = imported.Artifact.Presentation.Slides[1];
        var removed = Assert.Single(clone.Elements, element => element.Opaque?.NativeKind == "oleObject");
        Assert.True(removed.Source.DeletionCapability.Supported);
        clone.ElementDeletions.Add(new PresentationElementDeletion
        {
            Id = removed.Id,
            Source = removed.Source.Clone(),
        });
        clone.Elements.Remove(removed);

        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        var output = exported.File.ToByteArray();
        Assert.Equal(sourceSlideXml, ZipBytes(output, "ppt/slides/slide1.xml"));
        Assert.Equal(sourceSlideRels, ZipBytes(output, "ppt/slides/_rels/slide1.xml.rels"));

        using (var stream = new MemoryStream(output, writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var slides = OrderedSlides(package);
            Assert.Equal(2, slides.Length);
            Assert.Single(slides[0].Parts, pair => pair.OpenXmlPart is EmbeddedPackagePart);
            Assert.DoesNotContain(slides[1].Parts, pair => pair.OpenXmlPart is EmbeddedPackagePart);
            Assert.DoesNotContain(slides[1].Slide!.Descendants<P.GraphicFrame>(),
                frame => frame.Graphic?.GraphicData?.Uri?.ToString()?.Contains("/ole", StringComparison.OrdinalIgnoreCase) == true);
        }

        var roundTrip = Import(output);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        Assert.Contains(roundTrip.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "oleObject");
        Assert.DoesNotContain(roundTrip.Artifact.Presentation.Slides[1].Elements,
            element => element.Opaque?.NativeKind == "oleObject");
    }

    [Fact]
    public void ClosedSmartArtCloneCopiesFourIndependentDiagramParts()
    {
        var source = AddCloneableDiagramGraph(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var sourceDiagram = Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element =>
            element.ContentCase == PresentationElement.ContentOneofCase.Opaque && element.Opaque.NativeKind == "diagram");
        Assert.Equal(4, sourceDiagram.Opaque.RelationshipReferences.Count);
        Assert.Equal(4, sourceDiagram.Opaque.PreservedPartPaths.Count);

        AddPendingClone(imported.Artifact.Presentation, 0, "presentation/clone/closed-smartart");
        var cloned = Export(imported.Artifact);
        Assert.True(cloned.Ok, Diagnostics(cloned));
        var clonedBytes = cloned.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(clonedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(clonedBytes, "ppt/slides/_rels/slide1.xml.rels"));

        using (var stream = new MemoryStream(clonedBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(2, slides.Length);
            var sourceParts = slides[0].Parts
                .Where(pair => pair.OpenXmlPart is DiagramDataPart or DiagramLayoutDefinitionPart or DiagramStylePart or DiagramColorsPart)
                .ToDictionary(pair => pair.RelationshipId, pair => pair.OpenXmlPart, StringComparer.Ordinal);
            var cloneParts = slides[1].Parts
                .Where(pair => pair.OpenXmlPart is DiagramDataPart or DiagramLayoutDefinitionPart or DiagramStylePart or DiagramColorsPart)
                .ToDictionary(pair => pair.RelationshipId, pair => pair.OpenXmlPart, StringComparer.Ordinal);
            Assert.Equal(4, sourceParts.Count);
            Assert.Equal(sourceParts.Keys.Order(StringComparer.Ordinal), cloneParts.Keys.Order(StringComparer.Ordinal));
            foreach (var (relationshipId, sourcePart) in sourceParts)
            {
                var clonePart = cloneParts[relationshipId];
                Assert.Equal(sourcePart.GetType(), clonePart.GetType());
                Assert.NotEqual(sourcePart.Uri, clonePart.Uri);
                Assert.Equal(
                    ZipBytes(clonedBytes, sourcePart.Uri.OriginalString.TrimStart('/')),
                    ZipBytes(clonedBytes, clonePart.Uri.OriginalString.TrimStart('/')));
            }
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var roundTrip = Import(clonedBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripSource = Assert.Single(roundTrip.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram");
        var roundTripClone = Assert.Single(roundTrip.Artifact.Presentation.Slides[1].Elements, element => element.Opaque?.NativeKind == "diagram");
        Assert.Empty(roundTripSource.Opaque.PreservedPartPaths.Intersect(roundTripClone.Opaque.PreservedPartPaths, StringComparer.OrdinalIgnoreCase));

    }

    [Fact]
    public void SourceBoundSmartArtProjectsProvenContentGraphWithoutRewritingNativeParts()
    {
        const string dataPath = "ppt/diagrams/clone-data.xml";
        var source = ReplaceZipText(
            AddDiagramPersistLayoutGraph(AddCloneableDiagramGraph(Invoke(ExportRequest()).File.ToByteArray())),
            dataPath,
            _ => "<dgm:dataModel xmlns:dgm=\"http://schemas.openxmlformats.org/drawingml/2006/diagram\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\" xmlns:dsp=\"http://schemas.microsoft.com/office/drawing/2008/diagram\"><dgm:ptLst><dgm:pt modelId=\"0\" type=\"doc\"/><dgm:pt modelId=\"1\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Parent</a:t></a:r></a:p></dgm:t></dgm:pt><dgm:pt modelId=\"2\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>First child</a:t></a:r></a:p></dgm:t></dgm:pt><dgm:pt modelId=\"3\" type=\"asst\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Assistant</a:t></a:r></a:p></dgm:t></dgm:pt><dgm:pt modelId=\"4\" type=\"pres\"/></dgm:ptLst><dgm:cxnLst><dgm:cxn modelId=\"10\" srcId=\"0\" destId=\"1\" srcOrd=\"0\" destOrd=\"0\"/><dgm:cxn modelId=\"11\" type=\"parOf\" srcId=\"1\" destId=\"2\" srcOrd=\"0\" destOrd=\"0\"/><dgm:cxn modelId=\"12\" type=\"parOf\" srcId=\"1\" destId=\"3\" srcOrd=\"1\" destOrd=\"0\"/><dgm:cxn modelId=\"13\" type=\"presOf\" srcId=\"1\" destId=\"4\" srcOrd=\"0\" destOrd=\"0\"/></dgm:cxnLst><dgm:bg/><dgm:whole/><dgm:extLst><a:ext uri=\"{C28D6A17-3A09-4B91-8F6C-3E9D4F6A8C12}\"><dsp:dataModelExt relId=\"rIdCloneDiagramDrawing\"/></a:ext></dgm:extLst></dgm:dataModel>");

        using (var stream = new MemoryStream(source))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));

        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var binding = Assert.IsType<PresentationDiagramText>(Assert.Single(
            imported.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        Assert.Equal("urn:office-kit:clone-layout", binding.LayoutDefinitionId);
        Assert.Equal([("1", "node"), ("2", "node"), ("3", "asst")], binding.Nodes.Select(node => (node.ModelId, node.PointType)));
        Assert.Equal([("11", "1", "2", 0u), ("12", "1", "3", 1u)], binding.Connections.Select(connection =>
            (connection.ModelId, connection.FromModelId, connection.ToModelId, connection.Order)));

        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/third-party-smartart.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        var state = JsonNode.Parse(projected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var smartArt = state["pages"]![0]!["elements"]!.AsArray()
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "smartArt");
        Assert.Equal("source-bound", smartArt["mode"]!.GetValue<string>());
        Assert.Equal("urn:office-kit:clone-layout", smartArt["layoutDefinitionId"]!.GetValue<string>());
        var nodes = smartArt["nodes"]!.AsArray().Select(node => node!.AsObject()).ToArray();
        Assert.Equal(["node", "node", "assistant"], nodes.Select(node => node["kind"]!.GetValue<string>()));
        var connections = smartArt["connections"]!.AsArray().Select(connection => connection!.AsObject()).ToArray();
        Assert.Equal(2, connections.Length);
        Assert.All(connections, connection => Assert.Equal("parent", connection["role"]!.GetValue<string>()));
        Assert.Equal(nodes[0]["id"]!.GetValue<string>(), connections[0]["from"]!.GetValue<string>());
        Assert.Equal(nodes[1]["id"]!.GetValue<string>(), connections[0]["to"]!.GetValue<string>());
        Assert.Equal(nodes[2]["id"]!.GetValue<string>(), connections[1]["to"]!.GetValue<string>());
        Assert.Equal(1u, connections[1]["order"]!.GetValue<uint>());

        nodes[1]["text"] = "Edited child";
        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(state.ToJsonString()),
                IncludeNodeMap = true,
            },
        });
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([dataPath], edited.PresentationProgram.ChangedParts);
        var output = edited.File.ToByteArray();
        Assert.Contains("Edited child", Encoding.UTF8.GetString(ZipBytes(output, dataPath)));
        foreach (var path in ZipPartPaths(source).Where(path => !path.Equals(dataPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(source, path), ZipBytes(output, path));

        var topologyEdit = state.DeepClone().AsObject();
        topologyEdit["pages"]![0]!["elements"]!.AsArray()
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "smartArt")["connections"]![0]!["order"] = 2;
        var topologyRejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(topologyEdit.ToJsonString()),
            },
        });
        Assert.False(topologyRejected.Ok);
        Assert.Equal("ppj.source.unsupportedMutation", Assert.Single(topologyRejected.Diagnostics).Code);

        var unknownRelationship = ReplaceZipText(
            source,
            dataPath,
            xml => xml.Replace("type=\"parOf\" srcId=\"1\" destId=\"2\"", "type=\"unknownRelationship\" srcId=\"1\" destId=\"2\"", StringComparison.Ordinal));
        var unknownImport = Import(unknownRelationship);
        Assert.True(unknownImport.Ok, Diagnostics(unknownImport));
        var unknownBinding = Assert.IsType<PresentationDiagramText>(Assert.Single(
            unknownImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        Assert.Empty(unknownBinding.Nodes);
        Assert.Empty(unknownBinding.Connections);
        Assert.Equal("urn:office-kit:clone-layout", unknownBinding.LayoutDefinitionId);
        var unknownProjection = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(unknownRelationship),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/unknown-relationship-smartart.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(unknownProjection.Ok, Diagnostics(unknownProjection));
        var unknownState = JsonNode.Parse(unknownProjection.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var unknownSmartArt = unknownState["pages"]![0]!["elements"]!.AsArray()
            .Select(item => item!.AsObject()).Single(item => item["type"]!.GetValue<string>() == "smartArt");
        Assert.Empty(unknownSmartArt["nodes"]!.AsArray());
        Assert.DoesNotContain(unknownSmartArt["nativeRef"]!["capabilities"]!.AsArray(), capability =>
            capability!["operation"]!.GetValue<string>() == "setSmartArtText");
        var unknownNoOp = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(unknownRelationship),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = unknownProjection.PresentationProgram.ProgramJson,
            },
        });
        Assert.True(unknownNoOp.Ok, Diagnostics(unknownNoOp));
        Assert.Equal(unknownRelationship, unknownNoOp.File.ToByteArray());
    }

    [Fact]
    public void SourceBoundSmartArtPlainNodeTextCanBeEditedWithoutChangingItsGraph()
    {
        const string dataPath = "ppt/diagrams/clone-data.xml";
        var source = ReplaceZipText(
            AddCloneableDiagramGraph(Invoke(ExportRequest()).File.ToByteArray()),
            dataPath,
            _ => "<dgm:dataModel xmlns:dgm=\"http://schemas.openxmlformats.org/drawingml/2006/diagram\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\"><dgm:ptLst><dgm:pt modelId=\"{B31B1833-2B65-4D6B-B3D4-9B3988427B21}\" type=\"doc\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Original node</a:t></a:r></a:p></dgm:t></dgm:pt><dgm:pt modelId=\"1\" type=\"doc\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Second node</a:t></a:r></a:p></dgm:t></dgm:pt></dgm:ptLst><dgm:cxnLst/><dgm:bg/><dgm:whole/></dgm:dataModel>");
        source = ReplaceZipText(
            source,
            "ppt/diagrams/clone-layout.xml",
            xml => xml.Replace(
                "</dgm:layoutDef>",
                "<dgm:extLst><dgm:ext uri=\"{A4E4965B-2160-4B10-B9C0-9B596F3A1E20}\"><vendor:layoutResidue xmlns:vendor=\"urn:vendor:smartart:test\" value=\"preserve-me\"/></dgm:ext></dgm:extLst></dgm:layoutDef>",
                StringComparison.Ordinal));
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var diagram = Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram");
        var binding = Assert.IsType<PresentationDiagramText>(diagram.Opaque.DiagramText);
        Assert.Equal("rIdCloneDiagramData", binding.RelationshipId);
        Assert.Equal(dataPath, binding.PartPath);
        Assert.Equal([("{B31B1833-2B65-4D6B-B3D4-9B3988427B21}", "Original node"), ("1", "Second node")], binding.Nodes.Select(node => (node.ModelId, node.Text)));
        Assert.Equal([["Original node"], ["Second node"]], binding.Nodes.Select(node => node.RunTexts.ToArray()));

        binding.Nodes[0].Text = " Revised node ";
        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        var output = exported.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(output, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(output, "ppt/slides/_rels/slide1.xml.rels"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-layout.xml"), ZipBytes(output, "ppt/diagrams/clone-layout.xml"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-style.xml"), ZipBytes(output, "ppt/diagrams/clone-style.xml"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-colors.xml"), ZipBytes(output, "ppt/diagrams/clone-colors.xml"));
        Assert.NotEqual(ZipBytes(source, dataPath), ZipBytes(output, dataPath));
        Assert.Contains("xml:space=\"preserve\"", Encoding.UTF8.GetString(ZipBytes(output, dataPath)));

        var roundTrip = Import(output);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var rebound = Assert.IsType<PresentationDiagramText>(Assert.Single(roundTrip.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        Assert.Equal([("{B31B1833-2B65-4D6B-B3D4-9B3988427B21}", " Revised node "), ("1", "Second node")], rebound.Nodes.Select(node => (node.ModelId, node.Text)));
        Assert.NotEqual(binding.SourceSha256, rebound.SourceSha256);

        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/smartart.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        var state = JsonNode.Parse(projected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var smartArt = state["pages"]![0]!["elements"]!.AsArray()
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "smartArt");
        Assert.Equal("source-bound", smartArt["mode"]!.GetValue<string>());
        Assert.Equal(["Original node", "Second node"], smartArt["nodes"]!.AsArray().Select(node => node!["text"]!.GetValue<string>()));
        var sourceSections = smartArt["nativeSections"]!.AsObject().DeepClone().AsObject();
        Assert.Equal(binding.SourceSha256, sourceSections["dataSha256"]!.GetValue<string>());
        Assert.Matches("^[a-f0-9]{64}$", sourceSections["closureSha256"]!.GetValue<string>());
        Assert.All(new[] { "layoutSha256", "styleSha256", "colorsSha256" }, section =>
            Assert.Matches("^[a-f0-9]{64}$", sourceSections[section]!.GetValue<string>()));
        Assert.Contains(smartArt["nativeRef"]!["capabilities"]!.AsArray(), capability =>
            capability!["operation"]!.GetValue<string>() == "setSmartArtText" &&
            capability["fields"]!.AsArray().Any(field => field!.GetValue<string>() == "smartArt.text"));
        smartArt["nodes"]![0]!["text"] = "PPJ revised node";

        var ppjEdited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(state.ToJsonString()),
                IncludeNodeMap = true,
            },
        });
        Assert.True(ppjEdited.Ok, Diagnostics(ppjEdited));
        Assert.Equal([dataPath], ppjEdited.PresentationProgram.ChangedParts);
        var ppjOutput = ppjEdited.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(ppjOutput, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(ppjOutput, "ppt/slides/_rels/slide1.xml.rels"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-layout.xml"), ZipBytes(ppjOutput, "ppt/diagrams/clone-layout.xml"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-style.xml"), ZipBytes(ppjOutput, "ppt/diagrams/clone-style.xml"));
        Assert.Equal(ZipBytes(source, "ppt/diagrams/clone-colors.xml"), ZipBytes(ppjOutput, "ppt/diagrams/clone-colors.xml"));
        Assert.Contains("PPJ revised node", Encoding.UTF8.GetString(ZipBytes(ppjOutput, dataPath)));

        var ppjReprojected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ppjEdited.File,
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "deck.assets/source/smartart-edited.pptx",
                AssetRootUri = "deck.assets/media",
            },
        });
        Assert.True(ppjReprojected.Ok, Diagnostics(ppjReprojected));
        using (var ppjJson = JsonDocument.Parse(ppjReprojected.PresentationProgram.ProgramJson.ToByteArray()))
        {
            var ppjSmartArt = ppjJson.RootElement.GetProperty("pages")[0].GetProperty("elements")
                .EnumerateArray().Single(item => item.GetProperty("type").GetString() == "smartArt");
            Assert.Equal("PPJ revised node", ppjSmartArt.GetProperty("nodes")[0].GetProperty("text").GetString());
            var editedSections = ppjSmartArt.GetProperty("nativeSections");
            Assert.NotEqual(sourceSections["dataSha256"]!.GetValue<string>(), editedSections.GetProperty("dataSha256").GetString());
            Assert.Equal(sourceSections["layoutSha256"]!.GetValue<string>(), editedSections.GetProperty("layoutSha256").GetString());
            Assert.Equal(sourceSections["styleSha256"]!.GetValue<string>(), editedSections.GetProperty("styleSha256").GetString());
            Assert.Equal(sourceSections["colorsSha256"]!.GetValue<string>(), editedSections.GetProperty("colorsSha256").GetString());
        }

        imported = Import(source);
        var changedIdentifier = Assert.IsType<PresentationDiagramText>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        changedIdentifier.Nodes[0].ModelId = "other-node";
        var identifierRejected = Export(imported.Artifact);
        Assert.False(identifierRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(identifierRejected.Diagnostics).Code);

        imported = Import(source);
        var addedNode = Assert.IsType<PresentationDiagramText>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        addedNode.Nodes.Add(new PresentationDiagramTextNode { ModelId = "new-node", Text = "must fail" });
        var topologyRejected = Export(imported.Artifact);
        Assert.False(topologyRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(topologyRejected.Diagnostics).Code);

        var connected = AddZipText(
            source,
            "ppt/diagrams/_rels/clone-data.xml.rels",
            "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rIdUnsafeDiagramLink\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink\" Target=\"https://example.invalid/smartart\" TargetMode=\"External\"/></Relationships>");
        var connectedImport = Import(connected);
        Assert.True(connectedImport.Ok, Diagnostics(connectedImport));
        Assert.Null(Assert.Single(connectedImport.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);

        var invalidModelId = ReplaceZipText(
            source,
            dataPath,
            xml => xml.Replace("{B31B1833-2B65-4D6B-B3D4-9B3988427B21}", "agent-node-1", StringComparison.Ordinal));
        var invalidModelIdImport = Import(invalidModelId);
        Assert.True(invalidModelIdImport.Ok, Diagnostics(invalidModelIdImport));
        Assert.Empty(Assert.IsType<PresentationDiagramText>(Assert.Single(
            invalidModelIdImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);

        var annotatedText = ReplaceZipText(
            source,
            dataPath,
            xml => xml.Replace("<a:t>Original node</a:t>", "<a:t><!--source-owned annotation-->Original node</a:t>", StringComparison.Ordinal));
        var annotatedTextImport = Import(annotatedText);
        Assert.True(annotatedTextImport.Ok, Diagnostics(annotatedTextImport));
        Assert.Empty(Assert.IsType<PresentationDiagramText>(Assert.Single(
            annotatedTextImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);
    }

    [Fact]
    public void EditPlanChangesOneSmartArtRunWithoutReserializingDiagramDataPart()
    {
        const string dataPath = "ppt/diagrams/clone-data.xml";
        var source = ReplaceZipText(
            AddCloneableDiagramGraph(Invoke(ExportRequest()).File.ToByteArray()),
            dataPath,
            _ => "<dgm:dataModel xmlns:dgm=\"http://schemas.openxmlformats.org/drawingml/2006/diagram\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\"><dgm:ptLst><dgm:pt modelId=\"{B31B1833-2B65-4D6B-B3D4-9B3988427B21}\" type=\"doc\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Frame</a:t></a:r></a:p></dgm:t></dgm:pt><dgm:pt modelId=\"1\" type=\"doc\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:r><a:t>Scale candidate</a:t></a:r></a:p></dgm:t></dgm:pt></dgm:ptLst><dgm:cxnLst/><dgm:bg/><dgm:whole/></dgm:dataModel>");
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        var element = Assert.Single(slide.Elements, candidate => candidate.Opaque?.NativeKind == "diagram");
        var binding = Assert.IsType<PresentationDiagramText>(element.Opaque.DiagramText);
        var node = Assert.Single(binding.Nodes, candidate => candidate.ModelId == "1");
        Assert.Equal("Scale candidate", Assert.Single(node.RunTexts));
        const string replacement = "Scale";
        var operation = new PresentationEditOperation
        {
            OperationId = "diagram-text-0001",
            SlideId = slide.Id,
            SlidePartPath = slide.Source.PartPath,
            ExpectedSlideSha256 = slide.Source.SlideXmlSha256,
            TargetId = element.Id,
            ShapeTreeIndex = element.Source.ShapeTreeIndex,
            ExpectedElementSha256 = element.Source.ElementSha256,
            ExpectedSemanticSha256 = element.Source.SemanticSha256,
            TextLeafIndex = 1,
            LeafKind = "diagramText",
            ExpectedTextSha256 = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(node.Text))).ToLowerInvariant(),
            ExpectedValue = node.Text,
            Value = replacement,
            TargetPartPath = binding.PartPath,
            ExpectedTargetPartSha256 = binding.SourceSha256,
            RelationshipId = binding.RelationshipId,
            DiagramModelId = node.ModelId,
            DiagramRunIndex = 0,
        };
        var editRequest = new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ApplyPptxEditPlan,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationEditPlan = new PresentationEditPlanRequest
            {
                ExpectedSourceSha256 = imported.Artifact.Source.PackageSha256,
                Operations = { operation },
            },
        };

        var edited = Invoke(editRequest);
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal([dataPath], edited.PresentationEditPlan.ChangedParts);
        var result = Assert.Single(edited.PresentationEditPlan.Operations);
        Assert.Equal(dataPath, result.MutationPartPath);
        Assert.Equal("diagramText", result.LeafKind);
        Assert.Equal(result.SourceElementSha256, result.OutputElementSha256);
        Assert.Empty(result.NestedFootprints);
        var output = edited.File.ToByteArray();
        var sourceData = ZipBytes(source, dataPath);
        var outputData = ZipBytes(output, dataPath);
        Assert.Equal(node.Text, Encoding.UTF8.GetString(sourceData[(int)result.SourceStartOffset..(int)result.SourceEndOffset]));
        var outputStart = checked((int)result.OutputEndOffset - Encoding.UTF8.GetByteCount(replacement));
        Assert.Equal(replacement, Encoding.UTF8.GetString(outputData[outputStart..(int)result.OutputEndOffset]));
        Assert.Equal(sourceData, outputData[..outputStart]
            .Concat(Encoding.UTF8.GetBytes(node.Text))
            .Concat(outputData[(int)result.OutputEndOffset..])
            .ToArray());
        foreach (var path in ZipPartPaths(source).Where(path => !path.Equals(dataPath, StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(source, path), ZipBytes(output, path));
        var reopened = Import(output);
        Assert.True(reopened.Ok, Diagnostics(reopened));
        var reopenedBinding = Assert.IsType<PresentationDiagramText>(Assert.Single(
            Assert.Single(reopened.Artifact.Presentation.Slides).Elements,
            candidate => candidate.Id == element.Id).Opaque.DiagramText);
        Assert.Equal(replacement, Assert.Single(reopenedBinding.Nodes, candidate => candidate.ModelId == node.ModelId).Text);

        var stale = editRequest.Clone();
        stale.PresentationEditPlan.Operations[0].DiagramModelId = "{00000000-0000-0000-0000-000000000000}";
        var rejected = Invoke(stale);
        Assert.False(rejected.Ok);
        Assert.Equal("presentation_leaf_precondition_failed", Assert.Single(rejected.Diagnostics).Code);

        var whitespace = editRequest.Clone();
        whitespace.PresentationEditPlan.Operations[0].Value = " Scale ";
        var whitespaceRejected = Invoke(whitespace);
        Assert.False(whitespaceRejected.Ok);
        Assert.Equal("invalid_presentation_edit_operation", Assert.Single(whitespaceRejected.Diagnostics).Code);

        var foreignChartBinding = editRequest.Clone();
        foreignChartBinding.PresentationEditPlan.Operations[0].ChartSeriesIndex = 1;
        var foreignChartBindingRejected = Invoke(foreignChartBinding);
        Assert.False(foreignChartBindingRejected.Ok);
        Assert.Equal("invalid_presentation_edit_target", Assert.Single(foreignChartBindingRejected.Diagnostics).Code);
    }

    [Fact]
    public void SourceBoundSmartArtStyledRunsCanBeEditedWithoutFlatteningFormatting()
    {
        const string dataPath = "ppt/diagrams/clone-data.xml";
        var source = ReplaceZipText(
            AddCloneableDiagramGraph(Invoke(ExportRequest()).File.ToByteArray()),
            dataPath,
            _ => "<dgm:dataModel xmlns:dgm=\"http://schemas.openxmlformats.org/drawingml/2006/diagram\" xmlns:a=\"http://schemas.openxmlformats.org/drawingml/2006/main\"><dgm:ptLst><dgm:pt modelId=\"{B31B1833-2B65-4D6B-B3D4-9B3988427B21}\" type=\"doc\"><dgm:t><a:bodyPr/><a:lstStyle/><a:p><a:pPr algn=\"ctr\"/><a:r><a:rPr b=\"1\"/><a:t>Bold</a:t></a:r><a:br><a:rPr lang=\"fr-FR\"/></a:br><a:endParaRPr lang=\"en-US\"/></a:p><a:p><a:pPr marL=\"91440\"/><a:endParaRPr lang=\"de-DE\"/></a:p><a:p><a:r><a:rPr i=\"1\"/><a:t> italic</a:t></a:r></a:p></dgm:t></dgm:pt></dgm:ptLst><dgm:cxnLst/><dgm:bg/><dgm:whole/></dgm:dataModel>");
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var binding = Assert.IsType<PresentationDiagramText>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        var node = Assert.Single(binding.Nodes);
        Assert.Equal("Bold italic", node.Text);
        Assert.Equal(["Bold", " italic"], node.RunTexts);

        node.RunTexts[0] = "Strong";
        node.Text = "Strong italic";
        var exported = Export(imported.Artifact);
        Assert.True(exported.Ok, Diagnostics(exported));
        var output = exported.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(output, "ppt/slides/slide1.xml"));
        Assert.NotEqual(ZipBytes(source, dataPath), ZipBytes(output, dataPath));
        var xml = Encoding.UTF8.GetString(ZipBytes(output, dataPath));
        Assert.Equal(3, Regex.Matches(xml, "<a:p(?:\\s|>)").Count);
        Assert.Contains("<a:pPr algn=\"ctr\"", xml);
        Assert.Contains("<a:pPr marL=\"91440\"", xml);
        Assert.Contains("<a:br><a:rPr lang=\"fr-FR\"", xml);
        Assert.Contains("<a:endParaRPr lang=\"en-US\"", xml);
        Assert.Contains("<a:endParaRPr lang=\"de-DE\"", xml);
        Assert.Contains("<a:rPr b=\"1\"", xml);
        Assert.Contains("<a:rPr i=\"1\"", xml);
        Assert.Contains("<a:t>Strong</a:t>", xml);
        using (var stream = new MemoryStream(output))
        using (var package = PresentationDocument.Open(stream, false))
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));

        var rebound = Assert.IsType<PresentationDiagramText>(Assert.Single(Import(output).Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText);
        Assert.Equal("Strong italic", Assert.Single(rebound.Nodes).Text);
        Assert.Equal(["Strong", " italic"], Assert.Single(rebound.Nodes).RunTexts);

        imported = Import(source);
        node = Assert.Single(Assert.IsType<PresentationDiagramText>(Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);
        node.RunTexts.RemoveAt(1);
        node.Text = "Bold";
        var topologyRejected = Export(imported.Artifact);
        Assert.False(topologyRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(topologyRejected.Diagnostics).Code);

        var attributedBreakSource = ReplaceZipText(source, dataPath, xml => xml.Replace(
            "<a:br><a:rPr lang=\"fr-FR\"/></a:br>",
            "<a:br dirty=\"1\"><a:rPr lang=\"fr-FR\"/></a:br>",
            StringComparison.Ordinal));
        var attributedBreakImport = Import(attributedBreakSource);
        Assert.True(attributedBreakImport.Ok, Diagnostics(attributedBreakImport));
        Assert.Empty(Assert.IsType<PresentationDiagramText>(Assert.Single(
            attributedBreakImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);

        var fieldSource = ReplaceZipText(source, dataPath, xml => xml.Replace(
            "<a:r><a:rPr i=\"1\"/><a:t> italic</a:t></a:r>",
            "<a:fld id=\"{DAD748A6-978C-4A61-9D4D-EB37A70A8D2B}\" type=\"slidenum\"><a:t>1</a:t></a:fld>",
            StringComparison.Ordinal));
        var fieldImport = Import(fieldSource);
        Assert.True(fieldImport.Ok, Diagnostics(fieldImport));
        Assert.Empty(Assert.IsType<PresentationDiagramText>(Assert.Single(
            fieldImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);

        var emptyNodeSource = ReplaceZipText(source, dataPath, xml => xml
            .Replace("<a:r><a:rPr b=\"1\"/><a:t>Bold</a:t></a:r>", string.Empty, StringComparison.Ordinal)
            .Replace("<a:r><a:rPr i=\"1\"/><a:t> italic</a:t></a:r>", string.Empty, StringComparison.Ordinal));
        var emptyNodeImport = Import(emptyNodeSource);
        Assert.True(emptyNodeImport.Ok, Diagnostics(emptyNodeImport));
        Assert.Empty(Assert.IsType<PresentationDiagramText>(Assert.Single(
            emptyNodeImport.Artifact.Presentation.Slides[0].Elements,
            element => element.Opaque?.NativeKind == "diagram").Opaque.DiagramText).Nodes);
    }

    [Fact]
    public void ClosedInkMlContentPartCloneCopiesIndependentCustomXmlPart()
    {
        var source = AddCloneableInkContentPart(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var sourceInk = Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element =>
            element.ContentCase == PresentationElement.ContentOneofCase.Opaque && element.Opaque.NativeKind == "contentPart");
        Assert.Equal("Clone-safe ink", sourceInk.Name);
        Assert.Equal(914_400L, sourceInk.Opaque.LeftEmu);
        Assert.Equal(4_572_000L, sourceInk.Opaque.WidthEmu);
        Assert.Single(sourceInk.Opaque.RelationshipReferences);
        Assert.Single(sourceInk.Opaque.PreservedPartPaths);

        AddPendingClone(imported.Artifact.Presentation, 0, "presentation/clone/closed-inkml");
        var cloned = Export(imported.Artifact);
        Assert.True(cloned.Ok, Diagnostics(cloned));
        var clonedBytes = cloned.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(clonedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(clonedBytes, "ppt/slides/_rels/slide1.xml.rels"));

        using (var stream = new MemoryStream(clonedBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(2, slides.Length);
            var sourcePart = Assert.Single(slides[0].Parts, pair => pair.OpenXmlPart is CustomXmlPart);
            var clonePart = Assert.Single(slides[1].Parts, pair => pair.OpenXmlPart is CustomXmlPart);
            Assert.Equal("rIdCloneInk", sourcePart.RelationshipId);
            Assert.Equal(sourcePart.RelationshipId, clonePart.RelationshipId);
            Assert.Equal("application/inkml+xml", sourcePart.OpenXmlPart.ContentType);
            Assert.Equal(sourcePart.OpenXmlPart.ContentType, clonePart.OpenXmlPart.ContentType);
            Assert.NotEqual(sourcePart.OpenXmlPart.Uri, clonePart.OpenXmlPart.Uri);
            Assert.StartsWith("/ppt/customXml/", clonePart.OpenXmlPart.Uri.OriginalString, StringComparison.Ordinal);
            Assert.Equal(
                ZipBytes(clonedBytes, sourcePart.OpenXmlPart.Uri.OriginalString.TrimStart('/')),
                ZipBytes(clonedBytes, clonePart.OpenXmlPart.Uri.OriginalString.TrimStart('/')));
            Assert.Empty(clonePart.OpenXmlPart.Parts);
            Assert.Empty(clonePart.OpenXmlPart.ExternalRelationships);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var roundTrip = Import(clonedBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripSource = Assert.Single(roundTrip.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "contentPart");
        var roundTripClone = Assert.Single(roundTrip.Artifact.Presentation.Slides[1].Elements, element => element.Opaque?.NativeKind == "contentPart");
        Assert.Empty(roundTripSource.Opaque.PreservedPartPaths.Intersect(roundTripClone.Opaque.PreservedPartPaths, StringComparer.OrdinalIgnoreCase));

    }

    [Fact]
    public void SourceBoundOpaqueMediaAccessibilityEditsOnlyMediaSlideAndReprojects()
    {
        var authored = Invoke(ExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var source = RemoveEmbeddedPpj(AddCloneableEmbeddedMp4(authored.File.ToByteArray()));
        var projected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "media-accessibility/source.pptx",
                AssetRootUri = "media-accessibility/assets",
            },
        });
        Assert.True(projected.Ok, Diagnostics(projected));
        var program = JsonNode.Parse(projected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var media = program["pages"]!.AsArray()
            .SelectMany(page => page!["elements"]!.AsArray())
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "opaque" && item["nativeKind"]!.GetValue<string>() == "media");
        Assert.False(media.ContainsKey("accessibility"));
        var capabilities = media["nativeRef"]!["capabilities"]!.AsArray();
        Assert.Contains(capabilities, capability => capability!["operation"]!.GetValue<string>() == "setAccessibility");

        media["accessibility"] = new JsonObject
        {
            ["decorative"] = false,
            ["title"] = "Imported field video",
            ["description"] = "A source-bound media accessibility proof.",
        };
        var edited = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.CompilePpjToPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            PresentationProgram = new PresentationProgramRequest
            {
                ProgramJson = ByteString.CopyFromUtf8(program.ToJsonString()),
            },
        });
        Assert.True(edited.Ok, Diagnostics(edited));
        Assert.Equal(["ppt/slides/slide1.xml"], edited.PresentationProgram.ChangedParts);

        var sourceSlideXml = Encoding.UTF8.GetString(ZipBytes(source, "ppt/slides/slide1.xml"));
        var output = edited.File.ToByteArray();
        var outputSlideXml = Encoding.UTF8.GetString(ZipBytes(output, "ppt/slides/slide1.xml"));
        Assert.Contains("title=\"Imported field video\"", outputSlideXml, StringComparison.Ordinal);
        Assert.Contains("descr=\"A source-bound media accessibility proof.\"", outputSlideXml, StringComparison.Ordinal);
        Assert.DoesNotContain("title=\"Imported field video\"", sourceSlideXml, StringComparison.Ordinal);
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(output, "ppt/slides/_rels/slide1.xml.rels"));
        Assert.Equal(ZipBytes(source, "ppt/media/clone-video.mp4"), ZipBytes(output, "ppt/media/clone-video.mp4"));
        using (var stream = new MemoryStream(output, writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var mediaPicture = Assert.Single(package.PresentationPart!.SlideParts.Single().Slide!.CommonSlideData!.ShapeTree!.Elements<P.Picture>(), PptxNativeObjectCatalog.IsMediaPicture);
            var nonVisual = mediaPicture.NonVisualPictureProperties!.NonVisualDrawingProperties!;
            Assert.Equal("ppaction://media", nonVisual.GetFirstChild<A.HyperlinkOnClick>()!.Action!.Value);
            Assert.Equal("Imported field video", nonVisual.GetAttribute("title", string.Empty).Value);
            Assert.Equal("A source-bound media accessibility proof.", nonVisual.GetAttribute("descr", string.Empty).Value);
            var mediaProperties = mediaPicture.NonVisualPictureProperties.ApplicationNonVisualDrawingProperties!;
            Assert.Equal("rIdCloneVideo", mediaProperties.GetFirstChild<A.VideoFromFile>()!.Link!.Value);
            Assert.Equal("rIdCloneMedia", mediaProperties.Descendants<P14.Media>().Single().Embed!.Value);
        }

        var reprojected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ProjectPptxToPpj,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(output),
            PresentationProgram = new PresentationProgramRequest
            {
                SourceUri = "media-accessibility/edited.pptx",
                AssetRootUri = "media-accessibility/assets",
            },
        });
        Assert.True(reprojected.Ok, Diagnostics(reprojected));
        var secondProgram = JsonNode.Parse(reprojected.PresentationProgram.ProgramJson.ToByteArray())!.AsObject();
        var secondMedia = secondProgram["pages"]!.AsArray()
            .SelectMany(page => page!["elements"]!.AsArray())
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "opaque" && item["nativeKind"]!.GetValue<string>() == "media");
        Assert.Equal("Imported field video", secondMedia["accessibility"]!["title"]!.GetValue<string>());
        Assert.Equal("A source-bound media accessibility proof.", secondMedia["accessibility"]!["description"]!.GetValue<string>());
        Assert.False(secondMedia["accessibility"]!["decorative"]!.GetValue<bool>());
        Assert.Contains(secondMedia["nativeRef"]!["capabilities"]!.AsArray(), capability => capability!["operation"]!.GetValue<string>() == "setAccessibility");
    }

    [Fact]
    public void ClosedEmbeddedMp4MediaCloneCopiesIndependentPayloadAndSharesPoster()
    {
        var source = AddCloneableEmbeddedMp4(Invoke(ExportRequest()).File.ToByteArray());
        var imported = Import(source);
        Assert.True(imported.Ok, Diagnostics(imported));
        var sourceMedia = Assert.Single(imported.Artifact.Presentation.Slides[0].Elements, element =>
            element.ContentCase == PresentationElement.ContentOneofCase.Opaque && element.Opaque.NativeKind == "media");
        Assert.Equal("Clone-safe video", sourceMedia.Name);
        Assert.Equal(3, sourceMedia.Opaque.RelationshipReferences.Count);
        Assert.Equal(2, sourceMedia.Opaque.PreservedPartPaths.Count);

        AddPendingClone(imported.Artifact.Presentation, 0, "presentation/clone/closed-mp4-media");
        var cloned = Export(imported.Artifact);
        Assert.True(cloned.Ok, Diagnostics(cloned));
        var clonedBytes = cloned.File.ToByteArray();
        Assert.Equal(ZipBytes(source, "ppt/slides/slide1.xml"), ZipBytes(clonedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(source, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(clonedBytes, "ppt/slides/_rels/slide1.xml.rels"));

        using (var stream = new MemoryStream(clonedBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(2, slides.Length);
            var sourceVideo = Assert.Single(slides[0].DataPartReferenceRelationships.OfType<VideoReferenceRelationship>());
            var sourceMediaReference = Assert.Single(slides[0].DataPartReferenceRelationships.OfType<MediaReferenceRelationship>());
            var cloneVideo = Assert.Single(slides[1].DataPartReferenceRelationships.OfType<VideoReferenceRelationship>());
            var cloneMediaReference = Assert.Single(slides[1].DataPartReferenceRelationships.OfType<MediaReferenceRelationship>());
            Assert.Equal("rIdCloneVideo", sourceVideo.Id);
            Assert.Equal("rIdCloneMedia", sourceMediaReference.Id);
            Assert.Equal(sourceVideo.Id, cloneVideo.Id);
            Assert.Equal(sourceMediaReference.Id, cloneMediaReference.Id);
            Assert.Same(sourceVideo.DataPart, sourceMediaReference.DataPart);
            Assert.Same(cloneVideo.DataPart, cloneMediaReference.DataPart);
            Assert.NotEqual(sourceVideo.DataPart.Uri, cloneVideo.DataPart.Uri);
            Assert.Equal("video/mp4", sourceVideo.DataPart.ContentType);
            Assert.Equal(sourceVideo.DataPart.ContentType, cloneVideo.DataPart.ContentType);
            Assert.Equal(ReadDataPart(sourceVideo.DataPart), ReadDataPart(cloneVideo.DataPart));

            var sourcePoster = Assert.Single(slides[0].Parts, pair => pair.OpenXmlPart is ImagePart);
            var clonePoster = Assert.Single(slides[1].Parts, pair => pair.OpenXmlPart is ImagePart);
            Assert.Equal("rIdCloneVideoPoster", sourcePoster.RelationshipId);
            Assert.Equal(sourcePoster.RelationshipId, clonePoster.RelationshipId);
            Assert.Equal(sourcePoster.OpenXmlPart.Uri, clonePoster.OpenXmlPart.Uri);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var roundTrip = Import(clonedBytes);
        Assert.True(roundTrip.Ok, Diagnostics(roundTrip));
        var roundTripSource = Assert.Single(roundTrip.Artifact.Presentation.Slides[0].Elements, element => element.Opaque?.NativeKind == "media");
        var roundTripClone = Assert.Single(roundTrip.Artifact.Presentation.Slides[1].Elements, element => element.Opaque?.NativeKind == "media");
        var roundTripParts = roundTrip.Artifact.OpaqueOpc.Parts.ToDictionary(part => part.Path, StringComparer.OrdinalIgnoreCase);
        var roundTripSourceVideo = Assert.Single(roundTripSource.Opaque.PreservedPartPaths.Select(path => roundTripParts[path]), part => part.ContentType == "video/mp4");
        var roundTripCloneVideo = Assert.Single(roundTripClone.Opaque.PreservedPartPaths.Select(path => roundTripParts[path]), part => part.ContentType == "video/mp4");
        var roundTripSourcePoster = Assert.Single(roundTripSource.Opaque.PreservedPartPaths.Select(path => roundTripParts[path]), part => part.ContentType.StartsWith("image/", StringComparison.Ordinal));
        var roundTripClonePoster = Assert.Single(roundTripClone.Opaque.PreservedPartPaths.Select(path => roundTripParts[path]), part => part.ContentType.StartsWith("image/", StringComparison.Ordinal));
        Assert.NotEqual(roundTripSourceVideo.Path, roundTripCloneVideo.Path);
        Assert.Equal(roundTripSourceVideo.Sha256, roundTripCloneVideo.Sha256);
        Assert.Equal(roundTripSourcePoster.Path, roundTripClonePoster.Path);

    }

    [Fact]
    public void NativeObjectGraphRejectsMissingRelationshipsPartsAndExcessiveTraversal()
    {
        var source = AddNativeObjectGraph(Invoke(ExportRequest()).File.ToByteArray());
        var cyclic = AddZipText(source, "ppt/customXml/_rels/itemProps1.xml.rels", "<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rIdCycle\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/customXml\" Target=\"native-content.xml\"/></Relationships>");
        var cyclicImported = Import(cyclic);
        Assert.True(cyclicImported.Ok, Diagnostics(cyclicImported));
        Assert.Equal(2, cyclicImported.Artifact.Presentation.Slides[0].Elements[3].Opaque.PreservedPartPaths.Count);

        var missingRelationship = ReplaceZipText(source, "ppt/slides/slide1.xml", xml => xml.Replace("rIdNativeOle", "rIdMissingOle", StringComparison.Ordinal));
        var relationshipRejected = Import(missingRelationship);
        Assert.False(relationshipRejected.Ok);
        Assert.Equal("missing_presentation_native_relationship", Assert.Single(relationshipRejected.Diagnostics).Code);

        var missingPart = RemoveZipEntry(source, "ppt/customXml/itemProps1.xml");
        var partRejected = Import(missingPart);
        Assert.False(partRejected.Ok);
        Assert.Equal("missing_presentation_native_part", Assert.Single(partRejected.Diagnostics).Code);

        var budgetRejected = Invoke(new CodecRequest
        {
            ProtocolVersion = CodecProtocol.ProtocolVersion,
            Operation = CodecOperation.ImportPptx,
            Family = ArtifactFamily.Presentation,
            File = ByteString.CopyFrom(source),
            Limits = new CodecLimits { MaxCells = 4 },
        });
        Assert.False(budgetRejected.Ok);
        Assert.Equal("presentation_native_graph_budget_exceeded", Assert.Single(budgetRejected.Diagnostics).Code);
    }

    [Fact]
    public void SourcePreservingExportRejectsTamperedBindingAndTopology()
    {
        var imported = Import(Invoke(ExportRequest()).File.ToByteArray());
        imported.Artifact.Presentation.Slides[0].Elements[0].Source.SemanticSha256 = new string('0', 64);
        var tampered = Export(imported.Artifact);
        Assert.False(tampered.Ok);
        Assert.Equal("presentation_source_semantics_mismatch", Assert.Single(tampered.Diagnostics).Code);

        imported = Import(Invoke(ExportRequest()).File.ToByteArray());
        imported.Artifact.Presentation.Slides[0].Elements.Clear();
        var changed = Export(imported.Artifact);
        Assert.False(changed.Ok);
        Assert.Equal("presentation_element_topology_changed", Assert.Single(changed.Diagnostics).Code);

        imported = Import(Invoke(ExportRequest()).File.ToByteArray());
