    [Fact]
    public void InvalidFieldsBreaksAndTabStopsFailClosed()
    {
        var request = RichTextExportRequest();
        var run = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[0];
        run.Field = new PresentationTextField { Id = "not-a-guid", Type = "slidenum", Text = "1" };
        var invalidId = Invoke(request);
        Assert.False(invalidId.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(invalidId.Diagnostics).Code);

        request = RichTextExportRequest();
        run = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[0];
        run.Field = new PresentationTextField { Id = "{11111111-2222-4333-8444-555555555555}", Type = "\u0001", Text = "1" };
        var invalidType = Invoke(request);
        Assert.False(invalidType.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(invalidType.Diagnostics).Code);

        request = RichTextExportRequest();
        run = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[0];
        run.Field = new PresentationTextField
        {
            Id = "{11111111-2222-4333-8444-555555555555}",
            Type = "date",
            Text = "2026-09-06",
            Automatic = true,
        };
        var invalidAutomaticType = Invoke(request);
        Assert.False(invalidAutomaticType.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(invalidAutomaticType.Diagnostics).Code);

        request = RichTextExportRequest();
        run = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[0];
        run.LineBreak = false;
        var invalidBreak = Invoke(request);
        Assert.False(invalidBreak.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(invalidBreak.Diagnostics).Code);

        request = RichTextExportRequest();
        var paragraph = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0];
        paragraph.NoTabStops = false;
        var invalidDeletion = Invoke(request);
        Assert.False(invalidDeletion.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(invalidDeletion.Diagnostics).Code);

        request = RichTextExportRequest();
        paragraph = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0];
        paragraph.TabStops.Add(new PresentationTabStop { PositionEmu = 100, Alignment = "left" });
        paragraph.NoTabStops = true;
        var contradictoryTabs = Invoke(request);
        Assert.False(contradictoryTabs.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(contradictoryTabs.Diagnostics).Code);

        request = RichTextExportRequest();
        paragraph = request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0];
        paragraph.TabStops.Add(new PresentationTabStop { PositionEmu = 200, Alignment = "left" });
        paragraph.TabStops.Add(new PresentationTabStop { PositionEmu = 100, Alignment = "decimal" });
        var unsortedTabs = Invoke(request);
        Assert.False(unsortedTabs.Ok);
        Assert.Equal("invalid_presentation_text", Assert.Single(unsortedTabs.Diagnostics).Code);
    }

    [Fact]
    public void RunHyperlinksRoundTripAndEditOwnedSlideRelationships()
    {
        var authored = Invoke(HyperlinkExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slidePart = OrderedSlides(package)[0];
            var links = slidePart.Slide!.Descendants<A.HyperlinkOnClick>().ToArray();
            Assert.Equal(4, links.Length);
            Assert.Equal("https://example.com/guide?x=1&y=2", Assert.Single(slidePart.HyperlinkRelationships).Uri.OriginalString);
            Assert.Equal("ppaction://hlinksldjump", links[1].Action!.Value);
            Assert.IsType<SlidePart>(slidePart.GetPartById(links[1].Id!.Value!));
            Assert.Equal("ppaction://hlinkshowjump?jump=nextslide", links[2].Action!.Value);
            Assert.Equal(string.Empty, links[2].Id!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.Contains(imported.Artifact.OpaqueOpc.PackageRelationships,
            relationship => relationship.SourcePath == "ppt/slides/slide1.xml" && relationship.Type.EndsWith("/hyperlink", StringComparison.Ordinal));
        Assert.Contains(imported.Artifact.OpaqueOpc.PackageRelationships,
            relationship => relationship.SourcePath == "ppt/slides/slide1.xml" && relationship.Type.EndsWith("/slide", StringComparison.Ordinal));
        var runs = imported.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs;
        Assert.Equal("https://example.com/guide?x=1&y=2", runs[0].RunHyperlink.Uri);
        Assert.Equal("Read the guide", runs[0].RunHyperlink.Tooltip);
        Assert.True(runs[0].RunHyperlink.HasHistory);
        Assert.False(runs[0].RunHyperlink.History);
        Assert.True(runs[0].RunHyperlink.HighlightClick);
        Assert.Equal("presentation/slide/2", runs[1].RunHyperlink.SlideId);
        Assert.Equal("nextSlide", runs[2].RunHyperlink.Action);

        runs[0].RunHyperlink = new PresentationRunHyperlink { Uri = "https://example.com/updated", TargetFrame = "_blank" };
        runs[1].RunHyperlink = new PresentationRunHyperlink { SlideId = "presentation/slide/3", Tooltip = "Third slide" };
        runs[2].RunHyperlink = new PresentationRunHyperlink { Action = "lastSlide", HighlightClick = false };
        runs[3].NoHyperlink = true;
        var preserved = Export(imported.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Equal("opaque_content_preserved", Assert.Single(preserved.Diagnostics).Code);
        using (var stream = new MemoryStream(preserved.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            var links = slides[0].Slide!.Descendants<A.HyperlinkOnClick>().ToArray();
            Assert.Equal(3, links.Length);
            Assert.Equal("https://example.com/updated", slides[0].HyperlinkRelationships.Single(link => link.Id == links[0].Id).Uri.OriginalString);
            Assert.Same(slides[2], slides[0].GetPartById(links[1].Id!.Value!));
            Assert.Equal("ppaction://hlinkshowjump?jump=lastslide", links[2].Action!.Value);
            Assert.False(links[2].HighlightClick!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }
        var reimported = Import(preserved.File.ToByteArray());
        var reimportedRuns = reimported.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs;
        Assert.Equal("https://example.com/updated", reimportedRuns[0].RunHyperlink.Uri);
        Assert.Equal("presentation/slide/3", reimportedRuns[1].RunHyperlink.SlideId);
        Assert.Equal("lastSlide", reimportedRuns[2].RunHyperlink.Action);
        Assert.Equal(PresentationTextRun.HyperlinkOneofCase.None, reimportedRuns[3].HyperlinkCase);
    }

    [Fact]
    public void CustomShowRunHyperlinksKeepStableIdentityAcrossShowRenameAndClone()
    {
        var authored = Invoke(CustomShowHyperlinkExportRequest());
        Assert.True(authored.Ok, Diagnostics(authored));
        var sourceBytes = authored.File.ToByteArray();
        using (var stream = new MemoryStream(sourceBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var custom = OrderedSlides(package)[0].Slide!.Descendants<A.HyperlinkOnClick>().Last();
            Assert.Equal(string.Empty, custom.Id!.Value);
            Assert.Equal("ppaction://customshow?id=7&return=true", custom.Action!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var imported = Import(sourceBytes);
        Assert.True(imported.Ok, Diagnostics(imported));
        var run = imported.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4];
        Assert.Equal("custom-show/1", run.RunHyperlink.CustomShowId);
        Assert.True(run.RunHyperlink.HasReturnToSlide);
        Assert.True(run.RunHyperlink.ReturnToSlide);
        imported.Artifact.Presentation.CustomShows[0].Name = "Executive route";

        var renamed = Export(imported.Artifact);
        Assert.True(renamed.Ok, Diagnostics(renamed));
        var renamedBytes = renamed.File.ToByteArray();
        Assert.Equal(ZipBytes(sourceBytes, "ppt/slides/slide1.xml"), ZipBytes(renamedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(sourceBytes, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(renamedBytes, "ppt/slides/_rels/slide1.xml.rels"));
        var renamedImport = Import(renamedBytes);
        Assert.True(renamedImport.Ok, Diagnostics(renamedImport));
        Assert.Equal("Executive route", renamedImport.Artifact.Presentation.CustomShows[0].Name);
        Assert.Equal("custom-show/1", renamedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].RunHyperlink.CustomShowId);

        var retargetedRun = renamedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4];
        retargetedRun.RunHyperlink = new PresentationRunHyperlink { CustomShowId = "custom-show/2", ReturnToSlide = false };
        var retargeted = Export(renamedImport.Artifact);
        Assert.True(retargeted.Ok, Diagnostics(retargeted));
        using (var stream = new MemoryStream(retargeted.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var custom = OrderedSlides(package)[0].Slide!.Descendants<A.HyperlinkOnClick>().Last();
            Assert.Equal("ppaction://customshow?id=11&return=false", custom.Action!.Value);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }
        var retargetedImport = Import(retargeted.File.ToByteArray());
        var roundTripLink = retargetedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].RunHyperlink;
        Assert.Equal("custom-show/2", roundTripLink.CustomShowId);
        Assert.True(roundTripLink.HasReturnToSlide);
        Assert.False(roundTripLink.ReturnToSlide);

        var missing = Import(sourceBytes);
        missing.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].RunHyperlink =
            new PresentationRunHyperlink { CustomShowId = "custom-show/missing" };
        var missingRejected = Export(missing.Artifact);
        Assert.False(missingRejected.Ok);
        Assert.Equal("invalid_presentation_hyperlink", Assert.Single(missingRejected.Diagnostics).Code);

        var clone = Import(renamedBytes);
        AddPendingClone(clone.Artifact.Presentation, 0, "presentation/clone/custom-show-link");
        var cloned = Export(clone.Artifact);
        Assert.True(cloned.Ok, Diagnostics(cloned));
        var clonedBytes = cloned.File.ToByteArray();
        Assert.Equal(ZipBytes(renamedBytes, "ppt/slides/slide1.xml"), ZipBytes(clonedBytes, "ppt/slides/slide1.xml"));
        Assert.Equal(ZipBytes(renamedBytes, "ppt/slides/_rels/slide1.xml.rels"), ZipBytes(clonedBytes, "ppt/slides/_rels/slide1.xml.rels"));
        using (var stream = new MemoryStream(clonedBytes))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(4, slides.Length);
            var origin = slides[0];
            var outputClone = slides[3];
            var originCustom = origin.Slide!.Descendants<A.HyperlinkOnClick>().Last();
            var cloneCustom = outputClone.Slide!.Descendants<A.HyperlinkOnClick>().Last();
            Assert.Equal(originCustom.OuterXml, cloneCustom.OuterXml);
            Assert.Equal(string.Empty, cloneCustom.Id!.Value);
            Assert.Equal("ppaction://customshow?id=7&return=true", cloneCustom.Action!.Value);
            Assert.Equal(origin.HyperlinkRelationships.Count(), outputClone.HyperlinkRelationships.Count());
            Assert.Equal(origin.Parts.Count(pair => pair.OpenXmlPart is SlidePart), outputClone.Parts.Count(pair => pair.OpenXmlPart is SlidePart));

            var board = Assert.Single(
                package.PresentationPart!.Presentation!.CustomShowList!.Elements<P.CustomShow>(),
                show => show.Id?.Value == 7u);
            var memberships = board.GetFirstChild<P.SlideList>()!.Elements<P.SlideListEntry>()
                .Select(entry => entry.Id!.Value!)
                .ToArray();
            Assert.Equal(2, memberships.Length);
            Assert.DoesNotContain(package.PresentationPart.GetIdOfPart(outputClone), memberships);
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
        }

        var clonedImport = Import(clonedBytes);
        Assert.True(clonedImport.Ok, Diagnostics(clonedImport));
        Assert.Equal("Executive route", clonedImport.Artifact.Presentation.CustomShows[0].Name);
        Assert.DoesNotContain(
            clonedImport.Artifact.Presentation.Slides[3].Id,
            clonedImport.Artifact.Presentation.CustomShows[0].SlideIds);
        var clonedRun = clonedImport.Artifact.Presentation.Slides[3].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].RunHyperlink;
        Assert.Equal("custom-show/1", clonedRun.CustomShowId);
        Assert.True(clonedRun.HasReturnToSlide);
        Assert.True(clonedRun.ReturnToSlide);

        var compoundMembershipEdit = Import(renamedBytes);
        AddPendingClone(compoundMembershipEdit.Artifact.Presentation, 0, "presentation/clone/custom-show-membership-edit");
        compoundMembershipEdit.Artifact.Presentation.CustomShows[0].SlideIds.Clear();
        compoundMembershipEdit.Artifact.Presentation.CustomShows[0].SlideIds.Add("presentation/clone/custom-show-membership-edit");
        var compoundMembershipRejected = Export(compoundMembershipEdit.Artifact);
        Assert.False(compoundMembershipRejected.Ok);
        Assert.Equal("unsupported_presentation_slide_clone", Assert.Single(compoundMembershipRejected.Diagnostics).Code);
    }

    [Fact]
    public void MalformedOrRelationshipBearingCustomShowRunLinksRemainOpaqueAcrossClone()
    {
        var source = Invoke(CustomShowHyperlinkExportRequest()).File.ToByteArray();
        var malformed = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("ppaction://customshow?id=7&amp;return=true", "ppaction://customshow?id=7&amp;return=maybe", StringComparison.Ordinal));
        var malformedImport = Import(malformed);
        Assert.True(malformedImport.Ok, Diagnostics(malformedImport));
        var malformedRun = malformedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4];
        Assert.Equal(PresentationTextRun.HyperlinkOneofCase.None, malformedRun.HyperlinkCase);
        malformedRun.Text = "Edited board route";
        malformedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.Text =
            PptxTextCodec.Flatten(malformedImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody);
        var preserved = Export(malformedImport.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        Assert.Contains(
            "ppaction://customshow?id=7&amp;return=maybe",
            System.Text.Encoding.UTF8.GetString(ZipBytes(preserved.File.ToByteArray(), "ppt/slides/slide1.xml")),
            StringComparison.Ordinal);
        var malformedClone = Import(malformed);
        AddPendingClone(malformedClone.Artifact.Presentation, 0, "presentation/clone/malformed-custom-show-link");
        var malformedCloneResult = Export(malformedClone.Artifact);
        Assert.True(malformedCloneResult.Ok, Diagnostics(malformedCloneResult));
        using (var stream = new MemoryStream(malformedCloneResult.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(4, slides.Length);
            Assert.Equal(slides[0].Slide!.OuterXml, slides[^1].Slide!.OuterXml);
        }

        var replacementImport = Import(malformed);
        replacementImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].RunHyperlink =
            new PresentationRunHyperlink { Uri = "https://example.com/replacement" };
        var replacementRejected = Export(replacementImport.Artifact);
        Assert.False(replacementRejected.Ok);
        Assert.Equal("unsupported_presentation_edit", Assert.Single(replacementRejected.Diagnostics).Code);

        var relationshipBearing = ReplaceZipText(source, "ppt/slides/slide1.xml", xml =>
            xml.Replace("r:id=\"\" action=\"ppaction://customshow?id=7&amp;return=true\"", "r:id=\"rIdLayout1\" action=\"ppaction://customshow?id=7&amp;return=true\"", StringComparison.Ordinal));
        var relationshipImport = Import(relationshipBearing);
        Assert.True(relationshipImport.Ok, Diagnostics(relationshipImport));
        Assert.Equal(
            PresentationTextRun.HyperlinkOneofCase.None,
            relationshipImport.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.Paragraphs[0].Runs[4].HyperlinkCase);
        AddPendingClone(relationshipImport.Artifact.Presentation, 0, "presentation/clone/relationship-custom-show-link");
        var relationshipCloneResult = Export(relationshipImport.Artifact);
        Assert.True(relationshipCloneResult.Ok, Diagnostics(relationshipCloneResult));
        using (var stream = new MemoryStream(relationshipCloneResult.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            var slides = OrderedSlides(package);
            Assert.Equal(4, slides.Length);
            Assert.Equal(slides[0].Slide!.OuterXml, slides[^1].Slide!.OuterXml);
            Assert.Equal(
                slides[0].Parts.Select(pair => pair.RelationshipId).OrderBy(id => id, StringComparer.Ordinal),
                slides[^1].Parts.Select(pair => pair.RelationshipId).OrderBy(id => id, StringComparer.Ordinal));
        }
    }

