        Assert.Equal("invalid_presentation_text", Assert.Single(Invoke(request).Diagnostics).Code);
        request = RichTextExportRequest();
        request.Artifact.Presentation.Slides[0].Elements[0].Shape.TextBody.BodyProperties = new PresentationTextBodyProperties { ColumnSpacingEmu = -1 };
        Assert.Equal("invalid_presentation_text", Assert.Single(Invoke(request).Diagnostics).Code);
    }

    [Fact]
    public void SlideTransitionsAuthorImportEditAddAndFailClosedForOpaqueOrTimedImports()
    {
        var request = ExportRequest();
        request.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "wipe",
            Direction = "left",
            Speed = "medium",
            DurationMs = 750,
            AdvanceOnClick = true,
            AdvanceAfterMs = 1_250,
        };
        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray()))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var transition = package.PresentationPart!.SlideParts.Single().Slide!.Transition!;
            Assert.Equal(P.TransitionSpeedValues.Medium, transition.Speed!.Value);
            Assert.Equal("750", transition.Duration!.Value);
            Assert.True(transition.AdvanceOnClick!.Value);
            Assert.Equal("1250", transition.AdvanceAfterTime!.Value);
            var wipe = Assert.IsType<P.WipeTransition>(Assert.Single(transition.ChildElements));
            Assert.Equal(P.TransitionSlideDirectionValues.Left, wipe.Direction!.Value);
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        var slide = Assert.Single(imported.Artifact.Presentation.Slides);
        Assert.Equal(("wipe", "left", "medium", 750U, true, 1_250U), (slide.Transition.Effect, slide.Transition.Direction, slide.Transition.Speed, slide.Transition.DurationMs, slide.Transition.AdvanceOnClick, slide.Transition.AdvanceAfterMs));
        Assert.True(slide.Source!.TransitionPresent);
        Assert.True(slide.Source.TransitionEditable);

        slide.Transition = new PresentationTransition
        {
            Effect = "push",
            Direction = "right",
            Speed = "fast",
            DurationMs = 500,
            AdvanceOnClick = false,
            AdvanceAfterMs = 0,
        };
        var edited = Export(imported.Artifact);
        Assert.True(edited.Ok, Diagnostics(edited));
        var editedRoundTrip = Import(edited.File.ToByteArray());
        Assert.True(editedRoundTrip.Ok, Diagnostics(editedRoundTrip));
        var editedTransition = Assert.Single(editedRoundTrip.Artifact.Presentation.Slides).Transition;
        Assert.Equal(("push", "right", "fast", 500U, false, 0U), (editedTransition.Effect, editedTransition.Direction, editedTransition.Speed, editedTransition.DurationMs, editedTransition.AdvanceOnClick, editedTransition.AdvanceAfterMs));

        editedRoundTrip.Artifact.Presentation.Slides[0].Transition = null;
        var cleared = Export(editedRoundTrip.Artifact);
        Assert.True(cleared.Ok, Diagnostics(cleared));
        Assert.Null(Assert.Single(Import(cleared.File.ToByteArray()).Artifact.Presentation.Slides).Transition);

        var absentSource = Invoke(ExportRequest());
        Assert.True(absentSource.Ok, Diagnostics(absentSource));
        var absentBytes = absentSource.File.ToByteArray();
        var absent = Import(absentBytes);
        Assert.True(absent.Ok, Diagnostics(absent));
        var absentSlide = Assert.Single(absent.Artifact.Presentation.Slides);
        Assert.False(absentSlide.Source!.TransitionPresent);
        Assert.False(absentSlide.Source.TransitionEditable);
        Assert.True(absentSlide.Source.TransitionAddable);
        absentSlide.Transition = new PresentationTransition
        {
            Effect = "wipe",
            Direction = "up",
            Speed = "medium",
            DurationMs = 900,
            AdvanceOnClick = true,
        };
        var added = Export(absent.Artifact);
        Assert.True(added.Ok, Diagnostics(added));
        var addedBytes = added.File.ToByteArray();
        Assert.Equal(ZipPartPaths(absentBytes), ZipPartPaths(addedBytes));
        foreach (var path in ZipPartPaths(absentBytes).Where(path => !path.Equals("ppt/slides/slide1.xml", StringComparison.OrdinalIgnoreCase)))
            Assert.Equal(ZipBytes(absentBytes, path), ZipBytes(addedBytes, path));
        using (var stream = new MemoryStream(addedBytes, writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            var transition = package.PresentationPart!.SlideParts.Single().Slide!.Transition!;
            Assert.Equal(P.TransitionSpeedValues.Medium, transition.Speed!.Value);
            Assert.Equal("900", transition.Duration!.Value);
            Assert.True(transition.AdvanceOnClick!.Value);
            var wipe = Assert.IsType<P.WipeTransition>(Assert.Single(transition.ChildElements));
            Assert.Equal(P.TransitionSlideDirectionValues.Up, wipe.Direction!.Value);
        }
        var addedRoundTrip = Import(addedBytes);
        Assert.True(addedRoundTrip.Ok, Diagnostics(addedRoundTrip));
        var addedRoundTripSlide = Assert.Single(addedRoundTrip.Artifact.Presentation.Slides);
        Assert.Equal(("wipe", "up", "medium", 900U, true), (addedRoundTripSlide.Transition.Effect, addedRoundTripSlide.Transition.Direction, addedRoundTripSlide.Transition.Speed, addedRoundTripSlide.Transition.DurationMs, addedRoundTripSlide.Transition.AdvanceOnClick));
        Assert.True(addedRoundTripSlide.Source!.TransitionPresent);
        Assert.True(addedRoundTripSlide.Source.TransitionEditable);
        Assert.False(addedRoundTripSlide.Source.TransitionAddable);

        var timedBytes = ReplaceZipText(
            absentBytes,
            "ppt/slides/slide1.xml",
            xml => xml.Replace("</p:sld>", "<p:timing/></p:sld>", StringComparison.Ordinal));
        var timed = Import(timedBytes);
        Assert.True(timed.Ok, Diagnostics(timed));
        var timedSlide = Assert.Single(timed.Artifact.Presentation.Slides);
        Assert.False(timedSlide.Source!.TransitionPresent);
        Assert.False(timedSlide.Source.TransitionAddable);
        timedSlide.Transition = new PresentationTransition
        {
            Effect = "fade",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(timed.Artifact).Diagnostics).Code);

        var timedExistingBytes = ReplaceZipText(
            authored.File.ToByteArray(),
            "ppt/slides/slide1.xml",
            xml => xml.Replace("</p:transition>", "</p:transition><p:timing/>", StringComparison.Ordinal));
        var timedExisting = Import(timedExistingBytes);
        Assert.True(timedExisting.Ok, Diagnostics(timedExisting));
        var timedExistingSlide = Assert.Single(timedExisting.Artifact.Presentation.Slides);
        Assert.NotNull(timedExistingSlide.Transition);
        Assert.True(timedExistingSlide.Source!.TransitionPresent);
        Assert.False(timedExistingSlide.Source.TransitionEditable);
        Assert.False(timedExistingSlide.Source.TransitionAddable);
        timedExistingSlide.Transition = new PresentationTransition
        {
            Effect = "push",
            Direction = "right",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(timedExisting.Artifact).Diagnostics).Code);

        var nonCanonicalDurationBytes = ReplaceZipText(
            authored.File.ToByteArray(),
            "ppt/slides/slide1.xml",
            xml => xml.Replace("p14:dur=\"750\"", "p14:dur=\"0.75s\"", StringComparison.Ordinal));
        var nonCanonicalDuration = Import(nonCanonicalDurationBytes);
        Assert.True(nonCanonicalDuration.Ok, Diagnostics(nonCanonicalDuration));
        var nonCanonicalDurationSlide = Assert.Single(nonCanonicalDuration.Artifact.Presentation.Slides);
        Assert.Null(nonCanonicalDurationSlide.Transition);
        Assert.True(nonCanonicalDurationSlide.Source!.TransitionPresent);
        Assert.False(nonCanonicalDurationSlide.Source.TransitionEditable);
        Assert.False(nonCanonicalDurationSlide.Source.TransitionAddable);
        var nonCanonicalDurationPreserved = Export(nonCanonicalDuration.Artifact);
        Assert.True(nonCanonicalDurationPreserved.Ok, Diagnostics(nonCanonicalDurationPreserved));
        using (var sourceStream = new MemoryStream(nonCanonicalDurationBytes, writable: false))
        using (var outputStream = new MemoryStream(nonCanonicalDurationPreserved.File.ToByteArray(), writable: false))
        using (var sourcePackage = PresentationDocument.Open(sourceStream, false))
        using (var outputPackage = PresentationDocument.Open(outputStream, false))
            Assert.Equal(
                sourcePackage.PresentationPart!.SlideParts.Single().Slide!.Transition!.OuterXml,
                outputPackage.PresentationPart!.SlideParts.Single().Slide!.Transition!.OuterXml);

        byte[] opaqueBytes;
        using (var stream = new MemoryStream())
        {
            stream.Write(authored.File.Span);
            stream.Position = 0;
            using (var package = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
            {
                var sourceSlide = package.PresentationPart!.SlideParts.Single();
                var opaqueCut = new P.CutTransition();
                opaqueCut.SetAttribute(new OpenXmlAttribute("fixture", "opaque", "urn:office-kit:test", "kept"));
                sourceSlide.Slide!.Transition = new P.Transition(
                    opaqueCut)
                {
                    Speed = P.TransitionSpeedValues.Medium,
                    AdvanceOnClick = true,
                };
                sourceSlide.Slide.Save();
            }
            opaqueBytes = stream.ToArray();
        }
        var opaque = Import(opaqueBytes);
        Assert.True(opaque.Ok, Diagnostics(opaque));
        var opaqueSlide = Assert.Single(opaque.Artifact.Presentation.Slides);
        Assert.Null(opaqueSlide.Transition);
        Assert.True(opaqueSlide.Source!.TransitionPresent);
        Assert.False(opaqueSlide.Source.TransitionEditable);
        Assert.False(opaqueSlide.Source.TransitionAddable);
        var preserved = Export(opaque.Artifact);
        Assert.True(preserved.Ok, Diagnostics(preserved));
        using (var sourceStream = new MemoryStream(opaqueBytes, writable: false))
        using (var outputStream = new MemoryStream(preserved.File.ToByteArray(), writable: false))
        using (var sourcePackage = PresentationDocument.Open(sourceStream, false))
        using (var outputPackage = PresentationDocument.Open(outputStream, false))
            Assert.Equal(
                sourcePackage.PresentationPart!.SlideParts.Single().Slide!.Transition!.OuterXml,
                outputPackage.PresentationPart!.SlideParts.Single().Slide!.Transition!.OuterXml);

        opaqueSlide.Transition = new PresentationTransition
        {
            Effect = "fade",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("unsupported_presentation_edit", Assert.Single(Export(opaque.Artifact).Diagnostics).Code);

        var invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition { Effect = "fade", Speed = "medium" };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
        invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "fade",
            Speed = "medium",
            DurationMs = 86_400_001,
            AdvanceOnClick = true,
        };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
        invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "wipe",
            Direction = "diagonal",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
        invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "split",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
        invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "wheel",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
        invalid = ExportRequest();
        invalid.Artifact.Presentation.Slides[0].Transition = new PresentationTransition
        {
            Effect = "circle",
            Orientation = "horizontal",
            Speed = "medium",
            AdvanceOnClick = true,
        };
        Assert.Equal("invalid_presentation_transition", Assert.Single(Invoke(invalid).Diagnostics).Code);
    }

    [Fact]
    public void BaseSlideTransitionVocabularyAuthorsImportsAndValidates()
    {
        var transitions = new[]
        {
            new PresentationTransition { Effect = "blinds", Orientation = "vertical", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "checker", Orientation = "horizontal", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "circle", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "comb", Orientation = "vertical", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "cover", Direction = "rightUp", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "cut", ThroughBlack = true, Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "diamond", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "dissolve", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "fade", ThroughBlack = false, Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "newsflash", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "plus", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "pull", Direction = "leftDown", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "push", Direction = "up", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "random", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "randomBar", Orientation = "vertical", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "split", Orientation = "horizontal", Direction = "in", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "strips", Direction = "rightDown", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "wedge", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "wheel", Spokes = 8, Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "wipe", Direction = "down", Speed = "medium", AdvanceOnClick = true },
            new PresentationTransition { Effect = "zoom", Direction = "out", Speed = "medium", AdvanceOnClick = true },
        };
        var expectedNativeTypes = new[]
        {
            nameof(P.BlindsTransition), nameof(P.CheckerTransition), nameof(P.CircleTransition), nameof(P.CombTransition),
            nameof(P.CoverTransition), nameof(P.CutTransition), nameof(P.DiamondTransition), nameof(P.DissolveTransition),
            nameof(P.FadeTransition), nameof(P.NewsflashTransition), nameof(P.PlusTransition), nameof(P.PullTransition),
            nameof(P.PushTransition), nameof(P.RandomTransition), nameof(P.RandomBarTransition), nameof(P.SplitTransition),
            nameof(P.StripsTransition), nameof(P.WedgeTransition), nameof(P.WheelTransition), nameof(P.WipeTransition),
            nameof(P.ZoomTransition),
        };

        var request = ExportRequest();
        var slideTemplate = request.Artifact.Presentation.Slides[0].Clone();
        request.Artifact.Presentation.Slides.Clear();
        for (var index = 0; index < transitions.Length; index++)
        {
            var slide = slideTemplate.Clone();
            slide.Id = $"presentation/slide/{index + 1}";
            slide.Name = $"Transition {transitions[index].Effect}";
            slide.Transition = transitions[index].Clone();
            request.Artifact.Presentation.Slides.Add(slide);
        }

        var authored = Invoke(request);
        Assert.True(authored.Ok, Diagnostics(authored));
        using (var stream = new MemoryStream(authored.File.ToByteArray(), writable: false))
        using (var package = PresentationDocument.Open(stream, false))
        {
            Assert.Empty(new OpenXmlValidator(FileFormatVersions.Office2021).Validate(package));
            Assert.Equal(
                expectedNativeTypes.OrderBy(item => item, StringComparer.Ordinal),
                package.PresentationPart!.SlideParts
                    .Select(part => Assert.Single(part.Slide!.Transition!.ChildElements).GetType().Name)
                    .OrderBy(item => item, StringComparer.Ordinal));
        }

        var imported = Import(authored.File.ToByteArray());
        Assert.True(imported.Ok, Diagnostics(imported));
        Assert.Equal(transitions.Length, imported.Artifact.Presentation.Slides.Count);
        for (var index = 0; index < transitions.Length; index++)
        {
            Assert.Equal(transitions[index], imported.Artifact.Presentation.Slides[index].Transition);
            Assert.True(imported.Artifact.Presentation.Slides[index].Source!.TransitionEditable);
        }

        var secondExport = Export(imported.Artifact);
        Assert.True(secondExport.Ok, Diagnostics(secondExport));
        var secondImport = Import(secondExport.File.ToByteArray());
        Assert.True(secondImport.Ok, Diagnostics(secondImport));
        for (var index = 0; index < transitions.Length; index++)
            Assert.Equal(transitions[index], secondImport.Artifact.Presentation.Slides[index].Transition);
    }

    private static CodecResponse Invoke(CodecRequest request) =>
        CodecResponse.Parser.ParseFrom(CodecProtocol.Invoke(request.ToByteArray()));

    private static CodecResponse Import(byte[] bytes) => Invoke(new CodecRequest
    {
        ProtocolVersion = CodecProtocol.ProtocolVersion,
        Operation = CodecOperation.ImportPptx,
        Family = ArtifactFamily.Presentation,
        File = ByteString.CopyFrom(bytes),
    });

    private static CodecResponse Export(ArtifactEnvelope artifact) => Invoke(new CodecRequest
    {
        ProtocolVersion = CodecProtocol.ProtocolVersion,
        Operation = CodecOperation.ExportPptx,
        Family = ArtifactFamily.Presentation,
        Artifact = artifact,
    });

    private static string Diagnostics(CodecResponse response) =>
        string.Join("\n", response.Diagnostics.Select(item => $"{item.Code} {item.SourcePath}: {item.Message}"));

