    private static byte[] AddUnsupportedSpeakerNotesField(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var package = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var paragraph = OrderedSlides(package)[0].NotesSlidePart!.NotesSlide!.Descendants<A.Paragraph>().First();
            var run = paragraph.Elements<A.Run>().First();
            var field = new A.Field(new A.Text(run.Text?.Text ?? string.Empty))
            {
                Id = "{11111111-2222-4333-8444-555555555555}",
                Type = "datetime1",
            };
            run.InsertAfterSelf(field);
            run.Remove();
        }
        return stream.ToArray();
    }

    private static byte[] AddNotesRelationshipIdCollision(byte[] bytes, int slideIndex)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var package = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            OrderedSlides(package)[slideIndex].AddHyperlinkRelationship(
                new Uri("https://example.invalid/notes-relationship-collision"),
                true,
                "rIdNotes1");
        }
        return stream.ToArray();
    }

    private static byte[] AddLegacyCommentRelationshipIdCollisions(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var package = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var presentationPart = package.PresentationPart!;
            presentationPart.AddHyperlinkRelationship(
                new Uri("https://example.invalid/comment-authors-relationship-collision"),
                true,
                "rIdCommentAuthors1");
            foreach (var slide in OrderedSlides(package))
                slide.AddHyperlinkRelationship(
                    new Uri("https://example.invalid/comments-relationship-collision"),
                    true,
                    "rIdComments1");
        }
        return stream.ToArray();
    }

    private static byte[] AddUnsupportedSlideBackground(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var package = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var common = OrderedSlides(package)[0].Slide!.CommonSlideData!;
            common.Background!.Remove();
            common.AddChild(new P.Background(
                new P.BackgroundProperties(new A.NoFill(), new A.EffectList())), true);
        }
        return stream.ToArray();
    }

    private static byte[] SetFirstCustomPathFill(byte[] bytes, A.PathFillModeValues fill)
    {
