    private static byte[] CreateEmbeddedDocument(string value)
    {
        using var stream = new MemoryStream();
        using (var document = WordprocessingDocument.Create(stream, WordprocessingDocumentType.Document, autoSave: true))
        {
            var mainPart = document.AddMainDocumentPart();
            mainPart.Document = new W.Document(new W.Body(
                new W.Paragraph(new W.Run(new W.Text(value))),
                new W.SectionProperties()));
            mainPart.Document.Save();
        }
        return stream.ToArray();
    }

    private static byte[] ReplaceZipText(byte[] bytes, string path, Func<string, string> transform)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Update, leaveOpen: true)) ReplaceZipText(archive, path, transform);
        return stream.ToArray();
    }

    private static void ReplaceZipText(ZipArchive archive, string path, Func<string, string> transform)
    {
        var entry = archive.GetEntry(path) ?? throw new InvalidOperationException($"Missing fixture entry {path}.");
        string text;
        using (var reader = new StreamReader(entry.Open())) text = reader.ReadToEnd();
        entry.Delete();
        AddZipText(archive, path, transform(text));
    }

    private static byte[] RemoveZipEntry(byte[] bytes, string path)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Update, leaveOpen: true))
            (archive.GetEntry(path) ?? throw new InvalidOperationException($"Missing fixture entry {path}.")).Delete();
        return stream.ToArray();
    }

    private static byte[] RemoveEmbeddedPpj(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Update, leaveOpen: true))
        {
            foreach (var entry in archive.Entries.Where(entry =>
                         entry.FullName.StartsWith("officeKit/", StringComparison.OrdinalIgnoreCase)).ToArray())
                entry.Delete();
            ReplaceZipText(archive, "_rels/.rels", xml =>
            {
                var document = XDocument.Parse(xml);
                document.Descendants().Where(element =>
                    element.Name.LocalName == "Relationship" &&
                    element.Attribute("Type")?.Value == "https://schemas.officekit.dev/relationships/presentation-program").Remove();
                return document.ToString(SaveOptions.DisableFormatting);
            });
            ReplaceZipText(archive, "[Content_Types].xml", xml =>
            {
                var document = XDocument.Parse(xml);
                document.Descendants().Where(element =>
                    element.Name.LocalName == "Override" &&
                    element.Attribute("PartName")?.Value.StartsWith("/officeKit/", StringComparison.OrdinalIgnoreCase) == true).Remove();
                return document.ToString(SaveOptions.DisableFormatting);
            });
        }
        return stream.ToArray();
    }

    private static byte[] SetZipTimestamp(byte[] bytes, string path, DateTimeOffset timestamp)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Update, leaveOpen: true))
            (archive.GetEntry(path) ?? throw new InvalidOperationException($"Missing fixture entry {path}.")).LastWriteTime = timestamp;
        return stream.ToArray();
    }

    private static DateTimeOffset ZipTimestamp(byte[] bytes, string path)
    {
        using var stream = new MemoryStream(bytes, writable: false);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
        return (archive.GetEntry(path) ?? throw new InvalidOperationException($"Missing fixture entry {path}.")).LastWriteTime;
    }

    private static byte[] ZipBytes(byte[] bytes, string path)
    {
        using var stream = new MemoryStream(bytes, writable: false);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
        using var entry = (archive.GetEntry(path) ?? throw new InvalidOperationException($"Missing fixture entry {path}.")).Open();
        using var copy = new MemoryStream();
        entry.CopyTo(copy);
        return copy.ToArray();
    }

    private static string[] ZipPartPaths(byte[] bytes)
    {
        using var stream = new MemoryStream(bytes, writable: false);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
        return archive.Entries
            .Where(entry => !string.IsNullOrEmpty(entry.Name))
            .Select(entry => entry.FullName)
            .OrderBy(path => path, StringComparer.Ordinal)
            .ToArray();
    }

    private static byte[] ModernPartBytes<T>(byte[] bytes) where T : OpenXmlPart
    {
        using var stream = new MemoryStream(bytes, writable: false);
        using var package = PresentationDocument.Open(stream, false);
        var presentationPart = package.PresentationPart!;
        var part = Assert.Single(
            presentationPart.Parts.Select(pair => pair.OpenXmlPart)
                .Concat(presentationPart.SlideParts.SelectMany(slide => slide.Parts.Select(pair => pair.OpenXmlPart)))
                .OfType<T>());
        using var source = part.GetStream(FileMode.Open, FileAccess.Read);
        using var output = new MemoryStream();
        source.CopyTo(output);
        return output.ToArray();
    }

    private static string SingleZipEntryPath(byte[] bytes, Func<string, bool> predicate)
    {
        using var stream = new MemoryStream(bytes, writable: false);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Read);
        return Assert.Single(archive.Entries, entry => predicate(entry.FullName)).FullName;
    }

    private static void AddZipText(ZipArchive archive, string path, string text)
    {
        using var writer = new StreamWriter(archive.CreateEntry(path).Open());
        writer.Write(text);
    }

    private static byte[] AddZipText(byte[] bytes, string path, string text)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var archive = new ZipArchive(stream, ZipArchiveMode.Update, leaveOpen: true)) AddZipText(archive, path, text);
        return stream.ToArray();
    }

    private static void AddZipBytes(ZipArchive archive, string path, byte[] bytes)
    {
        using var target = archive.CreateEntry(path).Open();
        target.Write(bytes);
    }

    private static P.Shape TemplatePlaceholder(
        uint id,
        string name,
        P.PlaceholderValues type,
        uint index,
        string text,
        bool hasCustomPrompt = false,
        int? rotation = null,
        bool? flipHorizontal = null,
        bool? flipVertical = null)
    {
        var transform = new A.Transform2D(
            new A.Offset { X = 762_000L, Y = 571_500L },
            new A.Extents { Cx = 6_858_000L, Cy = 1_143_000L });
        if (rotation.HasValue) transform.Rotation = rotation.Value;
        if (flipHorizontal.HasValue) transform.HorizontalFlip = flipHorizontal.Value;
        if (flipVertical.HasValue) transform.VerticalFlip = flipVertical.Value;
        return new P.Shape(
            new P.NonVisualShapeProperties(
                new P.NonVisualDrawingProperties { Id = id, Name = name },
                new P.NonVisualShapeDrawingProperties(new A.ShapeLocks { NoGrouping = true }),
                new P.ApplicationNonVisualDrawingProperties(
                    new P.PlaceholderShape { Type = type, Index = index, HasCustomPrompt = hasCustomPrompt })),
            new P.ShapeProperties(
                transform,
                new A.PresetGeometry(new A.AdjustValueList()) { Preset = A.ShapeTypeValues.Rectangle },
                new A.NoFill()),
            new P.TextBody(
                new A.BodyProperties(),
                new A.ListStyle(),
                new A.Paragraph(
                    new A.Run(new A.RunProperties { Language = "en-US" }, new A.Text(text)),
                    new A.EndParagraphRunProperties { Language = "en-US" })));
    }

    private static byte[] AddPicture(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var presentation = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var slidePart = presentation.PresentationPart!.SlideParts.Single();
            var imagePart = slidePart.AddImagePart(ImagePartType.Png, "rIdImage1");
            using (var image = new MemoryStream(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")))
                imagePart.FeedData(image);
            slidePart.Slide!.CommonSlideData!.ShapeTree!.Append(new P.Picture(
                new P.NonVisualPictureProperties(
                    new P.NonVisualDrawingProperties { Id = 3U, Name = "Preserved picture", Description = "Opaque package evidence" },
                    new P.NonVisualPictureDrawingProperties(new A.PictureLocks { NoChangeAspect = true }),
                    new P.ApplicationNonVisualDrawingProperties()),
                new P.BlipFill(
                    new A.Blip { Embed = "rIdImage1" },
                    new A.Stretch(new A.FillRectangle())),
                new P.ShapeProperties(
                    new A.Transform2D(
                        new A.Offset { X = 571_500L, Y = 1_524_000L },
                        new A.Extents { Cx = 1_714_500L, Cy = 1_143_000L }),
                    new A.PresetGeometry(new A.AdjustValueList()) { Preset = A.ShapeTypeValues.Rectangle })));
            slidePart.Slide.Save();
        }
        return stream.ToArray();
    }

    private static byte[] AddPictureWithOwnedFallbackRelationship(byte[] bytes)
    {
        bytes = AddPicture(bytes);
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var presentation = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var slidePart = presentation.PresentationPart!.SlideParts.Single();
            var fallbackPart = slidePart.AddImagePart(ImagePartType.Png, "rIdImageFallback");
            using (var image = new MemoryStream(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")))
                fallbackPart.FeedData(image);
        }
        return ReplaceZipText(stream.ToArray(), "ppt/slides/slide1.xml", xml =>
        {
            const string replacement = "<a:blip r:embed=\"rIdImage1\"><a:extLst><a:ext uri=\"{BEBA8EAE-BF5A-486C-A8C5-ECC9F3942E4B}\"><a14:imgProps xmlns:a14=\"http://schemas.microsoft.com/office/drawing/2010/main\"><a14:imgLayer r:embed=\"rIdImageFallback\"><a14:imgEffect><a14:brightnessContrast contrast=\"80000\"/></a14:imgEffect></a14:imgLayer></a14:imgProps></a:ext></a:extLst></a:blip>";
            var updated = new Regex("<a:blip\\b[^>]*r:embed=\"rIdImage1\"[^>]*(?:/>|>.*?</a:blip>)", RegexOptions.Singleline).Replace(xml, replacement, 1);
            if (updated == xml) throw new InvalidOperationException("Picture fallback fixture could not locate the canonical blip.");
            return updated.Replace("<p:sld ", "<p:sld xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" ", StringComparison.Ordinal);
        });
    }

    private static byte[] AddPairedSvgFallback(byte[] bytes)
    {
        const string fallbackRelationshipId = "rIdPpjSvgRasterFallback";
        string? slidePath = null;
        string? svgRelationshipId = null;
        uint? pictureId = null;
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var presentation = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            foreach (var slidePart in presentation.PresentationPart!.SlideParts)
            {
                var match = slidePart.Slide!.Descendants<P.Picture>()
                    .Select(picture => new
                    {
                        Picture = picture,
                        RelationshipId = picture.BlipFill?.GetFirstChild<A.Blip>()?.Embed?.Value,
                    })
                    .FirstOrDefault(item =>
                        !string.IsNullOrEmpty(item.RelationshipId) &&
                        slidePart.GetPartById(item.RelationshipId) is ImagePart imagePart &&
                        imagePart.ContentType.Equals("image/svg+xml", StringComparison.OrdinalIgnoreCase));
                if (match is null) continue;
                if (slidePart.Parts.Any(pair => pair.RelationshipId.Equals(fallbackRelationshipId, StringComparison.Ordinal)))
                    throw new InvalidOperationException("Paired SVG fixture fallback relationship ID is already in use.");
                var fallbackPart = slidePart.AddImagePart(ImagePartType.Png, fallbackRelationshipId);
                using (var image = new MemoryStream(Convert.FromBase64String(
                    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")))
                    fallbackPart.FeedData(image);
                slidePath = slidePart.Uri.ToString().TrimStart('/');
                svgRelationshipId = match.RelationshipId;
                pictureId = match.Picture.NonVisualPictureProperties!.NonVisualDrawingProperties!.Id!.Value;
                break;
            }
        }
        if (slidePath is null || svgRelationshipId is null || pictureId is null)
            throw new InvalidOperationException("Paired SVG fixture could not locate an authored SVG picture.");
        return ReplaceZipText(stream.ToArray(), slidePath, xml =>
        {
            XNamespace presentation = "http://schemas.openxmlformats.org/presentationml/2006/main";
            XNamespace drawing = "http://schemas.openxmlformats.org/drawingml/2006/main";
            XNamespace relationships = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
            XNamespace svg = "http://schemas.microsoft.com/office/drawing/2016/SVG/main";
            var document = XDocument.Parse(xml, LoadOptions.PreserveWhitespace);
            var picture = document.Descendants(presentation + "pic").Single(element =>
                element.Descendants(presentation + "cNvPr").Any(nonVisual => (uint?)nonVisual.Attribute("id") == pictureId));
            var blip = picture.Descendants(drawing + "blip").Single(element =>
                (string?)element.Attribute(relationships + "embed") == svgRelationshipId);
            blip.SetAttributeValue(relationships + "embed", fallbackRelationshipId);
            var extensionList = blip.Element(drawing + "extLst");
            if (extensionList is null)
            {
                extensionList = new XElement(drawing + "extLst");
                blip.Add(extensionList);
            }
            extensionList.Add(new XElement(
                drawing + "ext",
                new XAttribute("uri", "{96DAC541-7B7A-43D3-8B79-37D633B846F1}"),
                new XElement(
                    svg + "svgBlip",
                    new XAttribute(XNamespace.Xmlns + "asvg", svg.NamespaceName),
                    new XAttribute(relationships + "embed", svgRelationshipId))));
            return document.ToString(SaveOptions.DisableFormatting);
        });
    }

    private static byte[] DuplicatePictureWithSharedRelationship(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var presentation = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var slide = presentation.PresentationPart!.SlideParts.Single().Slide!;
            var source = slide.CommonSlideData!.ShapeTree!.Elements<P.Picture>().Single();
            var duplicate = (P.Picture)source.CloneNode(true);
            duplicate.NonVisualPictureProperties!.NonVisualDrawingProperties!.Id = 4U;
            duplicate.NonVisualPictureProperties.NonVisualDrawingProperties.Name = "Shared relationship picture";
            slide.CommonSlideData.ShapeTree.Append(duplicate);
            slide.Save();
        }
        return stream.ToArray();
    }

    private static byte[] DuplicateChartWithSharedRelationship(byte[] bytes)
    {
        using var stream = new MemoryStream();
        stream.Write(bytes);
        stream.Position = 0;
        using (var presentation = PresentationDocument.Open(stream, true, new OpenSettings { AutoSave = true }))
        {
            var slide = presentation.PresentationPart!.SlideParts.Single().Slide!;
            var source = slide.CommonSlideData!.ShapeTree!.Elements<P.GraphicFrame>()
                .Single(frame => frame.Graphic?.GraphicData?.Elements<C.ChartReference>().Any() == true);
            var duplicate = (P.GraphicFrame)source.CloneNode(true);
            duplicate.NonVisualGraphicFrameProperties!.NonVisualDrawingProperties!.Id = 999U;
            duplicate.NonVisualGraphicFrameProperties.NonVisualDrawingProperties.Name = "Shared relationship chart";
            slide.CommonSlideData.ShapeTree.Append(duplicate);
            slide.Save();
        }
        return stream.ToArray();
    }

