        }

        var edited = program.DeepClone().AsObject();
        var editedTable = edited["pages"]!.AsArray()
            .SelectMany(page => page!.AsObject()["elements"]!.AsArray())
            .Select(item => item!.AsObject())
            .Single(item => item["type"]!.GetValue<string>() == "table");
