            ["showGridlines"] = new JsonObject { ["token"] = "chartShowGridlines" },
            ["frame"] = new JsonObject
            {
                ["fill"] = new JsonObject
                {
                    ["type"] = "solid",
                    ["color"] = "#F0E0D0",
                },
            },
            ["legendTextStyle"] = new JsonObject
            {
                ["fontSize"] = 9,
                ["fontFamily"] = "Arial",
                ["color"] = "#908070",
            },
        };
